INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90518, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "叫车", "is_correct": true, "explanation": "“叫车”指用电话或软件呼叫出租车、网约车，是本词的意思。"}, {"text": "驾车", "is_correct": false, "explanation": "jià 与 jiào 韵母不同（jiào 多一个 o），意思是驾驶车辆。"}, {"text": "叫出", "is_correct": false, "explanation": "chū 与 chē 韵母不同（ū 与 ē），意思是大声喊出来。"}, {"text": "跳车", "is_correct": false, "explanation": "t 与 j 声母不同，意思是从行驶中的车上跳下来。"}], "explanations": {"叫车": "“叫车”指用电话或软件呼叫出租车、网约车，是本词的意思。", "驾车": "jià 与 jiào 韵母不同（jiào 多一个 o），意思是驾驶车辆。", "叫出": "chū 与 chē 韵母不同（ū 与 ē），意思是大声喊出来。", "跳车": "t 与 j 声母不同，意思是从行驶中的车上跳下来。"}, "sentence_index": null, "correct_answer": "叫车"}, "level_3": {"options": [{"text": "叫车", "is_correct": true, "explanation": "“叫车”指用软件呼叫网约车或出租车，这句说的是用这个软件叫车比较便宜，符合语境，是正确答案。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”与“用这个软件”的语境冲突，句子说不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“用这个软件”的语境冲突，句子说不通。"}, {"text": "扶", "is_correct": false, "explanation": "配价：“扶”后面要带被扶的人，这句中“扶”后直接接“比较便宜”，缺少宾语，不能这样使用。"}], "explanations": {"叫车": "“叫车”指用软件呼叫网约车或出租车，这句说的是用这个软件叫车比较便宜，符合语境，是正确答案。", "洗澡": "语义：“洗澡”与“用这个软件”的语境冲突，句子说不通。", "睡觉": "语义：“睡觉”与“用这个软件”的语境冲突，句子说不通。", "扶": "配价：“扶”后面要带被扶的人，这句中“扶”后直接接“比较便宜”，缺少宾语，不能这样使用。"}, "sentence_index": 6, "correct_answer": "叫车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在群里叫车大家下午来开会。", "explanation": "这里应该用〈召集〉。叫车只指呼叫车辆，不能用来召集人员，应说〈召集〉大家下午来开会。"}, {"text": "妈妈在门口叫车我回家吃饭。", "explanation": "这里应该用〈叫〉。叫车只指呼叫车辆，不能用来喊人回家。"}, {"text": "周末我叫车朋友来家里玩。", "explanation": "这里应该用〈请〉。叫车只指呼叫车辆，不能用来邀请朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天用软件过叫车，很方便。", "corrected_sentence": "我昨天用软件叫过车，很方便。", "error_description": "「过」位置错误。体标「过」要放在动词「叫」之后，应说「叫过车」，不能放在「叫车」前面说「过叫车」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天我没叫车，就走路去吧。", "corrected_sentence": "明天我不叫车，就走路去吧。", "error_description": "未来的事情不能用「没」，应说「不」。「没」只否定已经发生的动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acce491f-b54d-4189-8320-74d1477149e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
