INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90519, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "肚子里不舒服，想吐；或者看到脏东西不想看。", "primary_collocate": null, "pronunciation": "ě xin", "ipa": "ɤ˨˩ ɕin", "syllable_count": 2, "sentences": [{"text": "吃了坏东西，他肚子疼，还恶心。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的垃圾好几天没倒，真恶心。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上到处是虫子，看着很恶心。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我晕车，一上车就恶心。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有很多脏东西，让人恶心。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯水里有头发，太恶心了。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃得太多，肚子很难受，有点恶心。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脏袜子放在饭桌上，真恶心。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闻着鱼的腥味，我就觉得恶心。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗手间又脏又臭，进去就恶心。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "肚子不舒服想吐，或看到脏东西觉得难受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2a424d-fb6a-4c27-a32b-e3eed49ee37f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90519, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恶心", "is_correct": true, "explanation": "“恶心”指肚子不舒服想吐，与“肚子疼”相符，“还”后面接的是新的不适。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”表示愉快，与“肚子疼”的不适状态矛盾，不能接在“还”后面。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”指质地，不能用来形容人的身体感觉。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌或事物好看，与“肚子疼”的语境无关。"}], "explanations": {"恶心": "“恶心”指肚子不舒服想吐，与“肚子疼”相符，“还”后面接的是新的不适。", "高兴": "语义：“高兴”表示愉快，与“肚子疼”的不适状态矛盾，不能接在“还”后面。", "柔软": "搭配：“柔软”指质地，不能用来形容人的身体感觉。", "漂亮": "语义：“漂亮”形容外貌或事物好看，与“肚子疼”的语境无关。"}, "sentence_index": 0, "correct_answer": "恶心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵红玫瑰很恶心，大家都想买。", "explanation": "这里应该用〈漂亮〉。恶心表示厌恶或想吐，形容好看的花要用漂亮。"}, {"text": "今天的天气很恶心，适合出去玩。", "explanation": "这里应该用〈晴朗〉。恶心不能形容天气，晴朗的天气要说晴朗。"}, {"text": "这次晚会很恶心，大家都很高兴。", "explanation": "这里应该用〈精彩〉。恶心表示厌恶，形容好看、热闹的演出要用精彩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90519, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恶心", "is_correct": true, "explanation": "“恶心”表示想吐或反胃，与“吃得太多，肚子很难受”的原因和结果相符。"}, {"text": "洁净", "is_correct": false, "explanation": "语义：“洁净”形容东西或环境干净，不能描述吃多后肚子难受、想吐的身体感觉。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”多用于空气、地面，不能用来形容人的肚子或身体感觉。"}, {"text": "欢快", "is_correct": false, "explanation": "语义：“欢快”表示轻松愉悦，与“肚子很难受”的状态矛盾。"}], "explanations": {"恶心": "“恶心”表示想吐或反胃，与“吃得太多，肚子很难受”的原因和结果相符。", "洁净": "语义：“洁净”形容东西或环境干净，不能描述吃多后肚子难受、想吐的身体感觉。", "潮湿": "搭配：“潮湿”多用于空气、地面，不能用来形容人的肚子或身体感觉。", "欢快": "语义：“欢快”表示轻松愉悦，与“肚子很难受”的状态矛盾。"}, "sentence_index": 6, "correct_answer": "恶心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑得很恶心，没有人能追上他。", "explanation": "这里应该用〈快〉。恶心不能形容速度，跑得快要说快。"}, {"text": "他一想到明天的旅行，就觉得很恶心。", "explanation": "这里应该用〈期待〉。恶心表示厌恶，对快乐的事要说期待。"}, {"text": "妈妈做的菜很恶心，我吃得特别香。", "explanation": "这里应该用〈好吃〉。恶心表示厌恶或想吐，与“吃得特别香”矛盾，要说好吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盘鱼很太恶心了，我没法吃。", "corrected_sentence": "这盘鱼太恶心了，我没法吃。", "error_description": "“很”和“太”不能同时修饰“恶心”，应去掉“很”，说“太恶心了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90519, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "垃圾桶的臭味让我恶心地想吐。", "corrected_sentence": "垃圾桶的臭味让我恶心得想吐。", "error_description": "结构标记用错。表示想吐的程度要用“得”引出补语，说“恶心得想吐”；“恶心”是表示感受的状态，不宜用“地”修饰“想吐”，应改用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
