INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90520, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90520, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "要呕吐的感觉；令人厌恶。", "primary_collocate": null, "pronunciation": "ě xin", "ipa": "ɤ˨˩ ɕin", "syllable_count": 2, "sentences": [{"text": "坐了很久的车，我觉得有点恶心。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝了太多酒，一直恶心想吐。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闻到那个味道，我就恶心。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人说话很恶心，我不想理他。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的菜不新鲜，吃完我很恶心。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的做法真恶心，大家都生气了。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到他随地吐痰，我觉得恶心。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坐船的时候，一直恶心，什么都不想吃。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个电影里的画面太恶心了。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早上起床就恶心，可能是感冒了。", "target_word": "恶心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "身体想吐的感觉，或人和事让人觉得讨厌、反感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2a424d-fb6a-4c27-a32b-e3eed49ee37f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恶心", "is_correct": true, "explanation": "“恶心”指想吐的不适感，坐了很久的车后出现这种感觉，符合句意。"}, {"text": "优秀", "is_correct": false, "explanation": "语义：“优秀”形容人或成绩非常好，不能描述坐车久了以后身体想吐的不适感。"}, {"text": "惶恐", "is_correct": false, "explanation": "语义：“惶恐”表示害怕不安，与坐车久了想吐的身体不适不符。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”多用于物品或环境，不用来形容坐车后的身体感觉。"}], "explanations": {"恶心": "“恶心”指想吐的不适感，坐了很久的车后出现这种感觉，符合句意。", "优秀": "语义：“优秀”形容人或成绩非常好，不能描述坐车久了以后身体想吐的不适感。", "惶恐": "语义：“惶恐”表示害怕不安，与坐车久了想吐的身体不适不符。", "干净": "搭配：“干净”多用于物品或环境，不用来形容坐车后的身体感觉。"}, "sentence_index": 0, "correct_answer": "恶心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的头很恶心，躺了一下午。", "explanation": "这里应该用〈难受〉。恶心指想吐或令人厌恶的感觉，头不舒服但没有想吐时要说难受。"}, {"text": "走了一整天路，我的腿很恶心。", "explanation": "这里应该用〈酸〉。恶心不用来描述肌肉的酸痛，腿累了要说酸。"}, {"text": "这颗牙疼得厉害，我的牙很恶心。", "explanation": "这里应该用〈痛〉。恶心指想吐或令人厌恶的感觉，牙齿的痛感要说痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恶心", "is_correct": true, "explanation": "“恶心”表示看到脏东西后的反感或想吐，与“随地吐痰”的语境相符。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”表示愉快，与看到别人随地吐痰后的反感语境矛盾。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”多形容质地，不能用来形容看到别人行为后的感受。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或颜色，与对别人行为的反应不合。"}], "explanations": {"恶心": "“恶心”表示看到脏东西后的反感或想吐，与“随地吐痰”的语境相符。", "高兴": "语义：“高兴”表示愉快，与看到别人随地吐痰后的反感语境矛盾。", "柔软": "搭配：“柔软”多形容质地，不能用来形容看到别人行为后的感受。", "明亮": "语义：“明亮”形容光线或颜色，与对别人行为的反应不合。"}, "sentence_index": 6, "correct_answer": "恶心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在公园里玩得很恶心。", "explanation": "这里应该用〈开心〉。恶心表示厌恶或想吐，形容愉快的玩耍要用开心。"}, {"text": "我拿到奖学金，心里觉得很恶心。", "explanation": "这里应该用〈高兴〉。恶心表示厌恶或想吐，得到奖学金这样的好事要说高兴。"}, {"text": "今天天气很恶心，我们去公园吧。", "explanation": "这里应该用〈凉快〉。恶心不用来描述天气，天气宜人要说凉快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个笑话很太恶心了，没人笑。", "corrected_sentence": "这个笑话太恶心了，没人笑。", "error_description": "“太”和“很”都表示程度，不能同时修饰“恶心”。应只用“太”，说“太恶心了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这股味道让我恶心地想吐。", "corrected_sentence": "这股味道让我恶心得想吐。", "error_description": "结构标记用错。表示想吐的程度要用“得”引出补语，说“恶心得想吐”；“恶心”是表示感受的状态，不宜用“地”修饰“想吐”，应改用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90521, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90521, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90521, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "和面是往面粉里加水，揉成一团。", "primary_collocate": null, "pronunciation": "huó miàn", "ipa": "xuo˧˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "今天晚上我们自己和面，包饺子。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大盆里和面，面粉飞得到处都是。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和面要用温水，面才会软。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明想学和面，爷爷在旁边教他。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我帮她和面。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次和面，加水加多了。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭馆里的师傅正在后厨和面。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要做面条，先和面再擀面。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每个周末都和面做馒头给孩子吃。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和面的盆要大一点。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "和了面", "label": "体标"}, {"form": "和过面", "label": "体标"}, {"form": "和面机", "label": "复合"}], "register": "中性", "sense_fingerprint": "面粉加水揉成一团", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3663726-c4db-4604-891f-260c0732ed66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90521, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "和面", "is_correct": true, "explanation": "和面：在面粉里加水揉成一团。"}, {"text": "会面", "is_correct": false, "explanation": "huì（第四声）与 huó（第二声）韵母与声调都不同，「会面」意思是见面。"}, {"text": "画面", "is_correct": false, "explanation": "huà（第四声）与 huó（第二声）韵母不同（a 与 o），「画面」指画中的景象。"}, {"text": "豁免", "is_correct": false, "explanation": "huò（第四声）与 huó（第二声）声调不同，miǎn（第三声）与 miàn（第四声）声调也不同，「豁免」意思是免除。"}, {"text": "湖面", "is_correct": false, "explanation": "hú 与 huó 韵母不同（少了 o），声调相同，「湖面」指湖的水面。"}], "explanations": {"和面": "和面：在面粉里加水揉成一团。", "会面": "huì（第四声）与 huó（第二声）韵母与声调都不同，「会面」意思是见面。", "画面": "huà（第四声）与 huó（第二声）韵母不同（a 与 o），「画面」指画中的景象。", "豁免": "huò（第四声）与 huó（第二声）声调不同，miǎn（第三声）与 miàn（第四声）声调也不同，「豁免」意思是免除。", "湖面": "hú 与 huó 韵母不同（少了 o），声调相同，「湖面」指湖的水面。"}, "sentence_index": null, "correct_answer": "和面"}, "level_3": {"options": [{"text": "跑步", "is_correct": false, "explanation": "语义：跑步与“包饺子”的情境不相关，句子不成立。"}, {"text": "和面", "is_correct": true, "explanation": "和面：往面粉里加水揉成面团，是包饺子前的准备。"}, {"text": "修车", "is_correct": false, "explanation": "搭配：“修车”指修理汽车，与“自己……包饺子”同句不搭配。"}, {"text": "搬家", "is_correct": false, "explanation": "语义：搬家与“包饺子”同时进行不合情理。"}], "explanations": {"跑步": "语义：跑步与“包饺子”的情境不相关，句子不成立。", "和面": "和面：往面粉里加水揉成面团，是包饺子前的准备。", "修车": "搭配：“修车”指修理汽车，与“自己……包饺子”同句不搭配。", "搬家": "语义：搬家与“包饺子”同时进行不合情理。"}, "sentence_index": 0, "correct_answer": "和面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把擀好的面皮拿来和面，再擀得很薄。", "explanation": "这里应该用〈擀〉。和面的对象是面粉，要加水揉成面团；已擀好的面皮不能再说和面。"}, {"text": "这盆面要在温暖的地方和面两个小时，馒头才会松软。", "explanation": "这里应该用〈发面〉。和面是加水揉合，让面团在温暖处发酵要说发面。"}, {"text": "他把颜料和面，搅成了红色。", "explanation": "和面的对象只能是面粉，给颜料加水调匀要说〈调〉，不能用和面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理发", "is_correct": false, "explanation": "语义：后厨是做饭的地方，师傅在那里理发不合情理。"}, {"text": "说相声", "is_correct": false, "explanation": "语义：后厨不是说相声的地方，与句中的“正在后厨”矛盾。"}, {"text": "和面", "is_correct": true, "explanation": "和面：往面粉里加水揉成面团，是后厨师傅的日常工作。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”需要水域，后厨不能游泳。"}], "explanations": {"理发": "语义：后厨是做饭的地方，师傅在那里理发不合情理。", "说相声": "语义：后厨不是说相声的地方，与句中的“正在后厨”矛盾。", "和面": "和面：往面粉里加水揉成面团，是后厨师傅的日常工作。", "游泳": "搭配：“游泳”需要水域，后厨不能游泳。"}, "sentence_index": 6, "correct_answer": "和面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在河边和面，弄得满身是泥。", "explanation": "这里应该用〈和泥〉。和面的对象是面粉，用泥土加水拌合要说和泥。"}, {"text": "奶奶把洗好的青菜和面，准备下锅炒。", "explanation": "这里应该用〈炒〉。和面的对象只能是面粉，青菜要用炒，不能说和面。"}, {"text": "工人在砖堆旁和面，准备砌墙。", "explanation": "这里应该用〈和砂浆〉。和面是加水揉合面粉，砌墙用的灰浆要说和砂浆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我帮妈妈了和面，准备做饺子。", "corrected_sentence": "我帮妈妈和了面，准备做饺子。", "error_description": "错误：“了”放在了动词“和”的前面。正确应为“和了面”，“了”放在动词后，表示动作完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈和面，把面和很得软，正好做面条。", "corrected_sentence": "妈妈和面，把面和得很软，正好做面条。", "error_description": "错误：补语“得很软”的次序颠倒，写成了“很得软”。正确应为“把面和得很软”，程度补语“很软”须接在“得”后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90522, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90522, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90522, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在面粉中加水搅拌揉合成面团。", "primary_collocate": null, "pronunciation": "huó miàn", "ipa": "xuo˧˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈在厨房和面，准备包饺子。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做馒头以前，要先和面。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把面粉倒进盆里开始和面。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和面的时候，水不能一次加太多。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天早上都和面做包子。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每次和面都很用力。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和面时，手上沾满了面粉。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和面以后，要让面团休息一会儿。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会和面，做的面条总是太硬。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么和面，大家都很高兴。", "target_word": "和面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "和了面", "label": "体标"}, {"form": "和过面", "label": "体标"}, {"form": "和面机", "label": "复合"}], "register": "中性", "sense_fingerprint": "往面粉里加水，搅拌揉成面团", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3663726-c4db-4604-891f-260c0732ed66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90522, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "和面", "is_correct": true, "explanation": "和面：往面粉里加水，搅拌揉合成面团。"}, {"text": "会面", "is_correct": false, "explanation": "huì（第四声）与 huó（第二声）韵母与声调都不同，「会面」意思是见面。"}, {"text": "画面", "is_correct": false, "explanation": "huà（第四声）与 huó（第二声）韵母不同（a 与 o），「画面」指画中的景象。"}, {"text": "豁免", "is_correct": false, "explanation": "huò（第四声）与 huó（第二声）声调不同，miǎn（第三声）与 miàn（第四声）声调也不同，「豁免」意思是免除。"}, {"text": "湖面", "is_correct": false, "explanation": "hú 与 huó 韵母不同（少了 o），声调相同，「湖面」指湖的水面。"}], "explanations": {"和面": "和面：往面粉里加水，搅拌揉合成面团。", "会面": "huì（第四声）与 huó（第二声）韵母与声调都不同，「会面」意思是见面。", "画面": "huà（第四声）与 huó（第二声）韵母不同（a 与 o），「画面」指画中的景象。", "豁免": "huò（第四声）与 huó（第二声）声调不同，miǎn（第三声）与 miàn（第四声）声调也不同，「豁免」意思是免除。", "湖面": "hú 与 huó 韵母不同（少了 o），声调相同，「湖面」指湖的水面。"}, "sentence_index": null, "correct_answer": "和面"}, "level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：厨房不是睡觉的地方，与后句“准备包饺子”的情境矛盾。"}, {"text": "和面", "is_correct": true, "explanation": "和面：往面粉里加水搅拌揉成面团，与“准备包饺子”的情境相合。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”需要水域，不能说“在厨房游泳”。"}, {"text": "理发", "is_correct": false, "explanation": "语义：在厨房里理发不合常理，与“准备包饺子”的情境不符。"}], "explanations": {"睡觉": "语义：厨房不是睡觉的地方，与后句“准备包饺子”的情境矛盾。", "和面": "和面：往面粉里加水搅拌揉成面团，与“准备包饺子”的情境相合。", "游泳": "搭配：“游泳”需要水域，不能说“在厨房游泳”。", "理发": "语义：在厨房里理发不合常理，与“准备包饺子”的情境不符。"}, "sentence_index": 0, "correct_answer": "和面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把切好的面条拿来和面，准备下锅。", "explanation": "这里应该用〈煮〉。和面的对象是面粉，已切好的面条要说煮，不能用和面。"}, {"text": "面团要盖上湿布，放在温暖的地方和面。", "explanation": "这里应该用〈发面〉。和面是加水揉合成面团，让面团在温暖处发酵要说发面。"}, {"text": "妈妈把鸡蛋和面，准备煮荷包蛋。", "explanation": "这里应该用〈打〉。煮荷包蛋不需要面粉，打鸡蛋不能说和面；和面的对象只能是面粉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跳舞", "is_correct": false, "explanation": "语义：手上沾满面粉时跳舞的情境不合理，与句中描写不符。"}, {"text": "弹钢琴", "is_correct": false, "explanation": "语义：弹钢琴不会使手沾上面粉，与句意不合。"}, {"text": "和面", "is_correct": true, "explanation": "和面：往面粉里加水搅拌揉合，所以手上会沾满面粉。"}, {"text": "打篮球", "is_correct": false, "explanation": "语义：打篮球时手上沾满面粉的描写不合情理。"}], "explanations": {"跳舞": "语义：手上沾满面粉时跳舞的情境不合理，与句中描写不符。", "弹钢琴": "语义：弹钢琴不会使手沾上面粉，与句意不合。", "和面": "和面：往面粉里加水搅拌揉合，所以手上会沾满面粉。", "打篮球": "语义：打篮球时手上沾满面粉的描写不合情理。"}, "sentence_index": 6, "correct_answer": "和面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在地上和面，弄得满手是泥。", "explanation": "这里应该用〈和泥〉。和面的对象是面粉，用泥土加水拌合要说和泥。"}, {"text": "妈妈把西瓜和面，切成了小块。", "explanation": "这里应该用〈切〉。和面的对象只能是面粉，西瓜要用切，不能说和面。"}, {"text": "工人在砖堆旁和面，准备砌墙。", "explanation": "这里应该用〈和砂浆〉。和面是加水揉合面粉，砌墙用的灰浆要说和砂浆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶给厨房和面，准备做包子。", "corrected_sentence": "奶奶在厨房和面，准备做包子。", "error_description": "错误：「给」不能引出处所，应用「在」。「给厨房和面」不通，正确为「奶奶在厨房和面，准备做包子。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很快和面条，准备做饺子。", "corrected_sentence": "她很快和面，准备做饺子。", "error_description": "错误：「和面」的对象只能是面粉，「面条」已是成品，不能说「和面条」。删去「条」即为正确。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
