INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90523, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "从某个时候开始。", "primary_collocate": null, "pronunciation": "dǎ cóng", "ipa": "ta˨˩˦ tsʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "打从去年起，他每天跑步。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从小时候，我就喜欢画画。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从认识她，我就没见她生过气。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从搬到这里，我睡得特别好。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从上个月起，这家店不卖饮料了。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从毕业以后，我们就没见过面。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从那天起，他再也没迟到过。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从春天开始，天天都在下雨。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从来到北京，我每天吃面条。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从放假那天起，弟弟就在玩游戏。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示时间的起点，常与“起”“就”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b382258-1d1c-4078-8cdf-3ee7f594def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打从", "is_correct": true, "explanation": "正确：“打从”引出时间起点，与句中的“起”配合，表示从去年开始。"}, {"text": "直到", "is_correct": false, "explanation": "语义：“直到”表示持续到某时为止，与句中“起”表示的开始正好相反。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”引出目的，句中说的是开始的时间，不是为了什么。"}, {"text": "向", "is_correct": false, "explanation": "配价：“向”后接方向或对象，不能引出“去年起”这样的时间起点。"}], "explanations": {"打从": "正确：“打从”引出时间起点，与句中的“起”配合，表示从去年开始。", "直到": "语义：“直到”表示持续到某时为止，与句中“起”表示的开始正好相反。", "为了": "语义：“为了”引出目的，句中说的是开始的时间，不是为了什么。", "向": "配价：“向”后接方向或对象，不能引出“去年起”这样的时间起点。"}, "sentence_index": 0, "correct_answer": "打从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直工作，打从深夜才回家。", "explanation": "这里应该用〈直到〉。“打从”只表示从某时开始，不能表示持续到深夜为止。"}, {"text": "打从下午三点前，他都在睡觉。", "explanation": "这里应该用〈在…之前〉。“打从”表示从某时开始，不能表示截止到某时之前。"}, {"text": "图书馆打从晚上十点为止。", "explanation": "这里应该用〈到〉。“打从”只表示从某时开始，不能表示截止到某时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打从", "is_correct": true, "explanation": "正确：“打从”引出时间起点，与句中的“起”配合，表示从那天开始。"}, {"text": "朝", "is_correct": false, "explanation": "配价：“朝”后接方向或地点，不能引出“那天起”这样的时间。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象或态度，不能引出时间的起点。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”引出受益的人，句中并没有替谁做事的意思。"}], "explanations": {"打从": "正确：“打从”引出时间起点，与句中的“起”配合，表示从那天开始。", "朝": "配价：“朝”后接方向或地点，不能引出“那天起”这样的时间。", "对": "语义：“对”引出对象或态度，不能引出时间的起点。", "替": "语义：“替”引出受益的人，句中并没有替谁做事的意思。"}, "sentence_index": 6, "correct_answer": "打从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "打从下个星期为止，你都要早点来。", "explanation": "这里应该用〈到〉。“打从”表示从某时开始，不能和表示终点的“为止”连用。"}, {"text": "打从明天以前，你要把作业交上来。", "explanation": "这里应该用〈在…之前〉。“打从”只表示从某时开始，不能表示截止到某时之前。"}, {"text": "他打从三个小时就开始做作业了。", "explanation": "“打从”后面接的是起点时间，“三个小时”是一段时长而不是时间点，这里不能用“打从”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "打从上个星期的起，她每天早起。", "corrected_sentence": "打从上个星期起，她每天早起。", "error_description": "错误：时间词与“起”之间不能加“的”，“上个星期的起”不通顺，应说“打从上个星期起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "打从上个月为止，妹妹就没再咳嗽。", "corrected_sentence": "打从上个月起，妹妹就没再咳嗽。", "error_description": "错误：“打从”引出时间起点，要与“起”配合，不能与表示终点的“为止”连用，应说“打从上个月起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
