INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90524, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "表示经过的路线或出发的地点，相当于“从”。", "primary_collocate": null, "pronunciation": "dǎ cóng", "ipa": "ta˨˩˦ tsʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他每天打从这条路走。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从学校门口走过，我看见了老师。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从山下的小路走过，我看到一座老房子。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打从小路穿过，很快就不见了。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从这里往北走，就能到车站。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从你家门口过的时候，我听到了歌声。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打从桥上走过，风很大。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟打从树上飞了下来。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打从后门悄悄进来。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打从超市旁边走，遇到了同学。", "target_word": "打从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示经过或出发的地点，相当于“从”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b382258-1d1c-4078-8cdf-3ee7f594def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90524, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打从", "is_correct": true, "explanation": "正确：“打从”表示经过的路线，与句中的“走”搭配，说明他沿这条路走。"}, {"text": "替", "is_correct": false, "explanation": "配价：“替”后要接受益的人，不能引出经过的路线。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象，不能说“对这条路走”。"}, {"text": "直到", "is_correct": false, "explanation": "语义：“直到”表示到某时为止，不表示经过的路线。"}], "explanations": {"打从": "正确：“打从”表示经过的路线，与句中的“走”搭配，说明他沿这条路走。", "替": "配价：“替”后要接受益的人，不能引出经过的路线。", "对": "语义：“对”引出对象，不能说“对这条路走”。", "直到": "语义：“直到”表示到某时为止，不表示经过的路线。"}, "sentence_index": 0, "correct_answer": "打从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他打从学校里学习英语。", "explanation": "这里应该用〈在〉。“打从”表示经过某处，不表示在某处进行动作，学习的地点要说“在学校里”。"}, {"text": "这本书打从老师写的。", "explanation": "这里应该用〈由〉。“打从”表示经过或起点，不能引出动作的施事，应说“由老师写的”。"}, {"text": "他打从三个小时就开始跑步了。", "explanation": "这里“打从”表示经过的地点，后面应接地点；“三个小时”是时长，不能作经过的处所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打从", "is_correct": true, "explanation": "正确：“打从”表示经过的路线，与“走过”搭配，说明有人从桥上经过。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，句中说的是经过桥上，不是目的。"}, {"text": "同", "is_correct": false, "explanation": "搭配：“同”后接人或事物，不能说“同桥上走过”。"}, {"text": "按照", "is_correct": false, "explanation": "语义：“按照”表示依据，不能引出经过的地点。"}], "explanations": {"打从": "正确：“打从”表示经过的路线，与“走过”搭配，说明有人从桥上经过。", "为了": "语义：“为了”表示目的，句中说的是经过桥上，不是目的。", "同": "搭配：“同”后接人或事物，不能说“同桥上走过”。", "按照": "语义：“按照”表示依据，不能引出经过的地点。"}, "sentence_index": 6, "correct_answer": "打从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他打从客厅吃了一顿饭。", "explanation": "这里应该用〈在〉。“打从”表示经过某地，后面要接移动的动作，不能接“吃饭”这样的静止动作。"}, {"text": "我们打从河边散步，很快就到了。", "explanation": "这里应该用〈在〉。“打从”表示经过某地，“散步”是在某处活动，不是经过，应说“在河边散步”。"}, {"text": "他打从沙发上睡着了。", "explanation": "这里应该用〈在〉。“打从”表示经过，睡在沙发上是静止的状态，不能用“打从”来引出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天从打从这条路去上班。", "corrected_sentence": "他每天打从这条路去上班。", "error_description": "错误：“打从”已含“从”的意思，前面不能再加“从”，形成重复的介词。正确应说“他每天打从这条路去上班”，删去多余的“从”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸟从打从窗户飞进来。", "corrected_sentence": "小鸟打从窗户飞进来。", "error_description": "错误：“打从”已含“从”的意思，前面不能再加“从”，形成重复的介词。正确应说“小鸟打从窗户飞进来”，不说“从打从窗户”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
