INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90525, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "唔是一个表示答应或想一想的声音。", "primary_collocate": null, "pronunciation": "ńg", "ipa": "ŋ˧˥", "syllable_count": 1, "sentences": [{"text": "“去吗？”“唔，去。”", "target_word": "唔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唔，让我想想再说。", "target_word": "唔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唔，我听到了。", "target_word": "唔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“吃饭了！”“唔，马上来。”", "target_word": "唔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唔，这件事不太容易。", "target_word": "唔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唔，我觉得可以。", "target_word": "唔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“好吗？”他说：“唔。”", "target_word": "唔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唔，明天再决定吧。", "target_word": "唔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唔，我先看看再回答你。", "target_word": "唔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她点点头说：“唔，好的。”", "target_word": "唔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示答应或思考的应答声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2b2c253-1912-4008-90c3-ad21f0ccc4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90525, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唔", "is_correct": true, "explanation": "正确：唔表示答应，与“去”的应答相合。"}, {"text": "呸", "is_correct": false, "explanation": "语义：呸表示唾弃或轻蔑，与答应的语气不合。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：嘘用于让人安静，不表示答应。"}, {"text": "嗟", "is_correct": false, "explanation": "语域：嗟是文言叹词，不用于口语应答。"}], "explanations": {"唔": "正确：唔表示答应，与“去”的应答相合。", "呸": "语义：呸表示唾弃或轻蔑，与答应的语气不合。", "嘘": "语义：嘘用于让人安静，不表示答应。", "嗟": "语域：嗟是文言叹词，不用于口语应答。"}, "sentence_index": 0, "correct_answer": "唔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "唔！我终于放假了！", "explanation": "误用：把“唔”当成表示欣喜的感叹词。“唔”只表示答应或想一想，不用于表达兴奋。"}, {"text": "我把唔写在了纸上。", "explanation": "误用：把叹词“唔”当成可以书写、充当宾语的实词。“唔”只表示答应或想一想，不能作动词的宾语。"}, {"text": "这本书唔很有意思。", "explanation": "误用：把叹词“唔”当成副词放在句子中间修饰形容词。“唔”只表示答应或想一想，要单独用在句首。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90525, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唔", "is_correct": true, "explanation": "正确：唔表示应答，与“好吗？”的问话相合。"}, {"text": "嗤", "is_correct": false, "explanation": "语义：嗤表示轻蔑或嘲笑，与答应不合。"}, {"text": "哎哟", "is_correct": false, "explanation": "语义：哎哟表示疼痛或突然的感觉，与答应不合。"}, {"text": "噫", "is_correct": false, "explanation": "语域：噫是文言叹词，不用于口语应答。"}], "explanations": {"唔": "正确：唔表示应答，与“好吗？”的问话相合。", "嗤": "语义：嗤表示轻蔑或嘲笑，与答应不合。", "哎哟": "语义：哎哟表示疼痛或突然的感觉，与答应不合。", "噫": "语域：噫是文言叹词，不用于口语应答。"}, "sentence_index": 6, "correct_answer": "唔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "唔，小心车！", "explanation": "误用：把“唔”当成表示警告的感叹词。“唔”只表示答应或想一想，不用于提醒别人注意。"}, {"text": "我们唔了一个小时的天。", "explanation": "误用：把叹词“唔”当成动词“聊”来用。“唔”只表示答应或想一想，不能带“了”和宾语。"}, {"text": "他唔地点了点头。", "explanation": "误用：把叹词“唔”当成修饰动作的状语，后面加“地”。“唔”只表示答应或想一想，要单独说出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "唔，我再想想唔。", "corrected_sentence": "唔，我再想想。", "error_description": "错误：“唔”是叹词，只能用在句首作应答或沉吟，放在句末不通。正确应为“唔，我再想想。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“好吗？”他唔说：“好。”", "corrected_sentence": "“好吗？”他说：“好。”", "error_description": "错误：叹词“唔”不能放在“说”前面修饰动词，应删去。正确应为“他说：‘好。’”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
