INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90527, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手紧紧拿住，不让它跑。", "primary_collocate": null, "pronunciation": "zhuā zhù", "ipa": "ʈʂu̯a˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他一把抓住了我的手。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩紧紧抓住妈妈的衣服。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我伸手抓住了桌子上的杯子。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车开得很快，请抓住扶手。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她抓住绳子，慢慢往上爬。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，他抓住帽子不放。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗要跑了，我马上抓住了它的绳子。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他滑了一下，赶紧抓住旁边的树枝。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子抓住我的手指，不让我走。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别松手，一定要抓住栏杆。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抓住了", "label": "完成体"}, {"form": "抓住过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "抓住：用手紧紧拿住，不让它跑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0a5c81-35f2-4930-926c-6a53b5a7efb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90527, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抓住", "is_correct": true, "explanation": "正确：「抓住」表示用手紧紧拿住，与句意相符。"}, {"text": "扛", "is_correct": false, "explanation": "搭配：「扛」接的是重物或扛在肩上的东西，不能说扛「我的手」。"}, {"text": "剪", "is_correct": false, "explanation": "语义：「剪」是剪断，与「一把」紧紧握住的动作相反，句子不通。"}, {"text": "扔", "is_correct": false, "explanation": "配价：「扔」的受事是东西，不能用「扔了我的手」表示抓握。"}], "explanations": {"抓住": "正确：「抓住」表示用手紧紧拿住，与句意相符。", "扛": "搭配：「扛」接的是重物或扛在肩上的东西，不能说扛「我的手」。", "剪": "语义：「剪」是剪断，与「一把」紧紧握住的动作相反，句子不通。", "扔": "配价：「扔」的受事是东西，不能用「扔了我的手」表示抓握。"}, "sentence_index": 0, "correct_answer": "抓住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用石头抓住了桌上的纸。", "explanation": "这里应该用〈压住〉。压是用重物按住，抓住是用手紧紧拿住，石头不能“抓”纸。"}, {"text": "妈妈用毛巾抓住了哭泣的孩子，轻轻拍着他的背。", "explanation": "这里应该用〈裹住〉。裹是用布把人包起来，抓住是用手紧紧拿住，毛巾不能“抓”人。"}, {"text": "请用拐杖抓住老人，别让他摔倒。", "explanation": "这里应该用〈扶住〉。扶是用手或工具支撑，防止摔倒；拐杖是用来支撑的，不能用来「抓住」人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90527, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抓住", "is_correct": true, "explanation": "正确：「抓住」表示用手紧紧拿住，与「防止小狗跑掉」的句意相符。"}, {"text": "喂", "is_correct": false, "explanation": "配价：「喂」的对象是人或动物，「绳子」不能作为喂的对象。"}, {"text": "写", "is_correct": false, "explanation": "搭配：「写」接的是文字类对象，不能说写「绳子」。"}, {"text": "吞", "is_correct": false, "explanation": "语义：「吞」是咽下，与「马上抓住绳子防止小狗跑掉」的情境完全不合。"}], "explanations": {"抓住": "正确：「抓住」表示用手紧紧拿住，与「防止小狗跑掉」的句意相符。", "喂": "配价：「喂」的对象是人或动物，「绳子」不能作为喂的对象。", "写": "搭配：「写」接的是文字类对象，不能说写「绳子」。", "吞": "语义：「吞」是咽下，与「马上抓住绳子防止小狗跑掉」的情境完全不合。"}, "sentence_index": 6, "correct_answer": "抓住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用碗抓住了那只飞走的蝴蝶。", "explanation": "这里应该用〈罩住〉。罩是把东西盖在上面，抓住要求用手或工具握紧，碗不能“抓”蝴蝶。"}, {"text": "他抓住了嘴，不敢出声。", "explanation": "这里应该用〈捂住〉。捂是用手盖住，表示遮挡；抓住是用力握住，不能用来说「抓住了嘴」。"}, {"text": "妈妈用被子抓住了睡着的孩子。", "explanation": "这里应该用〈盖住〉。盖是覆盖，抓住是用手握紧，不能用来形容用被子遮盖孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一把抓住了了我的袖子。", "corrected_sentence": "她一把抓住了我的袖子。", "error_description": "错误：「抓住了了」，「了」重复；正确：「抓住了」。「了」只用一次，接在复合动词「抓住」之后，表示动作已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90527, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈马上抓住过了它的绳子。", "corrected_sentence": "妈妈马上抓住了它的绳子。", "error_description": "错误：「抓住过了」，「过」与「了」不能同时用在同一动词后；正确：「抓住了」，表示动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
