INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90529, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90529, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "执照是政府发给的、允许你做某件事的证。", "primary_collocate": null, "pronunciation": "zhí zhào", "ipa": "ʈʂɻ̩˧˥ ʈʂɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他开饭店以前，先去办了执照。", "target_word": "执照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有执照，你不能在这里开店。", "target_word": "执照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把执照挂在了店门口的墙上。", "target_word": "执照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开出租车的人都必须有执照。", "target_word": "执照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的执照丢了，要去重新办一张。", "target_word": "执照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的执照过期了。", "target_word": "执照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着执照去银行开了户。", "target_word": "执照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员说我的材料不全，不能发执照。", "target_word": "执照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想开一家小花店，正在办执照。", "target_word": "执照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察检查了司机的执照。", "target_word": "执照", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "营业执照", "label": "复合词"}, {"form": "驾驶执照", "label": "复合词"}], "register": "中性", "sense_fingerprint": "政府发的、允许做某事的证件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36662012-8007-41fe-a78e-aaa6e4d441d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90529, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "执照", "is_correct": true, "explanation": "“办执照”是固定搭配，指办理政府准许开店的证件，句意通顺。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜不能被“办”，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是可以去办理的事物，句意不通。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“办”不能接疾病作宾语，不能说“办感冒”。"}], "explanations": {"执照": "“办执照”是固定搭配，指办理政府准许开店的证件，句意通顺。", "白菜": "语义：白菜不能被“办”，句意不通。", "窗户": "语义：窗户不是可以去办理的事物，句意不通。", "感冒": "搭配：“办”不能接疾病作宾语，不能说“办感冒”。"}, "sentence_index": 0, "correct_answer": "执照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿到了英语执照。", "explanation": "这里应该用〈证书〉。学习成绩或培训结业用证书，执照指政府准许从事某种活动的证件。"}, {"text": "他坐飞机出国，在海关给工作人员看了执照。", "explanation": "这里应该用〈护照〉。出入海关要出示护照，执照是政府准许从事某种活动的证件。"}, {"text": "他在比赛里赢了冠军，拿到了执照。", "explanation": "这里应该用〈奖杯〉。比赛获胜得到的是奖杯或奖牌，执照是政府准许从事某种活动的证件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90529, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "执照", "is_correct": true, "explanation": "“拿着”后接具体证件，句意通顺，去银行开户需要出示证件。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜不能用来去银行开户，句意不通。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚与银行开户无关，句意不通。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“拿着”后接具体物品，“感情”不能被拿着。"}], "explanations": {"执照": "“拿着”后接具体证件，句意通顺，去银行开户需要出示证件。", "西瓜": "语义：西瓜不能用来去银行开户，句意不通。", "扫帚": "语义：扫帚与银行开户无关，句意不通。", "感情": "搭配：“拿着”后接具体物品，“感情”不能被拿着。"}, "sentence_index": 6, "correct_answer": "执照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在超市买了东西，店员给了他一张执照。", "explanation": "这里应该用〈收据〉。店员给的是购物收据，执照是政府准许做某事的证件。"}, {"text": "他们签了一份执照。", "explanation": "这里应该用〈合同〉。合同是双方签订的协议，执照是政府发的证件。"}, {"text": "进入机场前要出示执照。", "explanation": "这里应该用〈身份证〉。进机场要证明身份，执照是准许做某事的证件，不能用来证明身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90529, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他办好了一条执照。", "corrected_sentence": "他办好了一张执照。", "error_description": "错误：执照是证件，量词应用“张”，不能用“条”（“条”用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90529, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于拿了到执照。", "corrected_sentence": "他终于拿到了执照。", "error_description": "错误：结果补语“到”应紧接动词“拿”，“了”放在“拿到”之后，应为“拿到了”，不能说成“拿了到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90531, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90531, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90531, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "后事是一个人走了以后，家人要办的事。", "primary_collocate": null, "pronunciation": "hòu shì", "ipa": "xoʊ˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷走了，家人一起办他的后事。", "target_word": "后事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病前就把后事安排好了。", "target_word": "后事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，我的后事一切从简。", "target_word": "后事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办完后事，大家都很累。", "target_word": "后事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走得很突然，没来得及交代后事。", "target_word": "后事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈哭着和亲戚商量后事。", "target_word": "后事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都来帮忙处理后事。", "target_word": "后事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后事办得很简单，没有请很多人。", "target_word": "后事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他没几天了，家人开始准备后事。", "target_word": "后事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的后事由学校负责办理。", "target_word": "后事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人去世后家人办理的丧葬等事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b382258-1d1c-4078-8cdf-3ee7f594def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90531, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后事", "is_correct": true, "explanation": "后事指人去世后家人要办的丧葬等事，与“爷爷走了”相符。"}, {"text": "婚事", "is_correct": false, "explanation": "语义：爷爷已经去世，家人不会为他办婚事。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“办”不接作业，不能说“办他的作业”。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“办”不接玩具，“办他的玩具”不成立。"}], "explanations": {"后事": "后事指人去世后家人要办的丧葬等事，与“爷爷走了”相符。", "婚事": "语义：爷爷已经去世，家人不会为他办婚事。", "作业": "搭配：“办”不接作业，不能说“办他的作业”。", "玩具": "搭配：“办”不接玩具，“办他的玩具”不成立。"}, "sentence_index": 0, "correct_answer": "后事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次决定的后事很严重。", "explanation": "这里应该用〈后果〉。“后事”指人去世后家人办理的丧葬事务，说决定带来的结果要用“后果”。"}, {"text": "他留下的后事都交给了博物馆。", "explanation": "这里应该用〈遗物〉。遗物是人去世后留下的物品，可以交给博物馆；“后事”指丧葬等事务，不能指东西。"}, {"text": "他留下一笔后事，让子女平分了。", "explanation": "这里应该用〈遗产〉。钱财要说“遗产”，“后事”是丧葬等事务，不能说“留下一笔后事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90531, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后事", "is_correct": true, "explanation": "后事指丧葬等事务，“处理”和“朋友们都来帮忙”与之搭配。"}, {"text": "笑容", "is_correct": false, "explanation": "搭配：“处理”不接表情，不说“处理笑容”。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不能被处理，与“朋友们来帮忙”不相关。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“处理”不接脚步，不能这样说。"}], "explanations": {"后事": "后事指丧葬等事务，“处理”和“朋友们都来帮忙”与之搭配。", "笑容": "搭配：“处理”不接表情，不说“处理笑容”。", "阳光": "语义：阳光不能被处理，与“朋友们来帮忙”不相关。", "脚步": "搭配：“处理”不接脚步，不能这样说。"}, "sentence_index": 6, "correct_answer": "后事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷留下一份后事，把房子留给了我。", "explanation": "这里应该用〈遗嘱〉。遗嘱是书面文件，“后事”是事情，不能说“留下一份后事”。"}, {"text": "公司的后事部门负责采购办公用品。", "explanation": "这里应该用〈后勤〉。后勤部门负责生活保障，“后事”指丧葬等事务，不能用作部门名。"}, {"text": "演员们在后事等着上场。", "explanation": "这里应该用〈后台〉。“后台”是地方，“后事”是丧葬等事务，不能表示场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们已经办了完他的后事了。", "corrected_sentence": "他们已经办完他的后事了。", "error_description": "“办了完”错误，应说“办完”。结果补语“完”要紧跟动词“办”，中间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们终于办完了他的后事们。", "corrected_sentence": "我们终于办完了他的后事。", "error_description": "“后事们”错误：“后事”是抽象名词，不能加“们”表示复数，应说“他的后事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
