INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90533, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在电视或广播里让大家看到、听到。", "primary_collocate": null, "pronunciation": "bō chū", "ipa": "pwɔ˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "她的访问昨晚在电视上播出了。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌第一次播出，就很受欢迎。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的广播站每天中午播出音乐。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动画片下午四点播出，孩子们都等着看。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事会在广播里播出。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节目播出以后，他接到很多电话。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台明天播出一部新的纪录片。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年晚会将在晚上七点播出。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段话没有播出，因为太长了。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听到电台播出了我最喜欢的那首歌。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "播出了", "label": "完成体"}, {"form": "播出过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "在电视或广播里让观众、听众看到听到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b382258-1d1c-4078-8cdf-3ee7f594def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "播出", "is_correct": true, "explanation": "正确：“播出”表示在电视上让观众看到，与句中的“在电视上”搭配。"}, {"text": "观看", "is_correct": false, "explanation": "语义：“观看”的主体是观众，访问本身不能“观看”。"}, {"text": "出售", "is_correct": false, "explanation": "语义：访问不能被“出售”，句中说的是在电视上的播放。"}, {"text": "拍卖", "is_correct": false, "explanation": "语义：访问不能被“拍卖”，句中说的是在电视上的播放。"}], "explanations": {"播出": "正确：“播出”表示在电视上让观众看到，与句中的“在电视上”搭配。", "观看": "语义：“观看”的主体是观众，访问本身不能“观看”。", "出售": "语义：访问不能被“出售”，句中说的是在电视上的播放。", "拍卖": "语义：访问不能被“拍卖”，句中说的是在电视上的播放。"}, "sentence_index": 0, "correct_answer": "播出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "剧院晚上播出一场话剧。", "explanation": "这里应该用〈上演〉。“播出”针对电视、广播，剧院里的演出要说上演。"}, {"text": "园丁春天在花园里播出花籽。", "explanation": "这里应该用〈播种〉。“播出”指发出节目，把花籽种进土里要说播种。"}, {"text": "工厂今年播出了一款新产品。", "explanation": "这里应该用〈推出〉。“播出”的对象是节目，不能用于产品，推出新产品要说推出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "播出", "is_correct": true, "explanation": "正确：“播出”表示电视台发出节目，与句中的“电视台”和“纪录片”搭配。"}, {"text": "装订", "is_correct": false, "explanation": "语义：“装订”针对纸张书册，纪录片不能被装订。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：“修补”用于破损的东西，不能说“修补纪录片”。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：“切割”的对象是具体的物体，纪录片不能被切割。"}], "explanations": {"播出": "正确：“播出”表示电视台发出节目，与句中的“电视台”和“纪录片”搭配。", "装订": "语义：“装订”针对纸张书册，纪录片不能被装订。", "修补": "搭配：“修补”用于破损的东西，不能说“修补纪录片”。", "切割": "搭配：“切割”的对象是具体的物体，纪录片不能被切割。"}, "sentence_index": 6, "correct_answer": "播出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在录音棚播出了一首歌。", "explanation": "这里应该用〈录〉。“播出”是让观众或听众听到，录音室里的录制要说录。"}, {"text": "谣言在网上播出。", "explanation": "这里应该用〈散播〉。“播出”指通过广播、电视发出节目，谣言的传播要说散播。"}, {"text": "这棵树每天都在播出。", "explanation": "这里应该用〈开花〉。“播出”只能指媒体发出节目，植物不能播出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这档访谈节目明天下午将在电视上播出了。", "corrected_sentence": "这档访谈节目明天下午将在电视上播出。", "error_description": "错误：“将”和“明天”表示还没发生，句末不能再用表示完成的“了”，应说“将在电视上播出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套电视剧下周一开始播出过。", "corrected_sentence": "这套电视剧下周一开始播出。", "error_description": "错误：“过”表示已经有过的经历，与“下周一”的将来时间矛盾。应去掉“过”，说“下周一开始播出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
