INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过广播、电视等发出节目。", "primary_collocate": null, "pronunciation": "bō chū", "ipa": "pwɔ˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "这个节目晚上八点播出。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电影下个月在电视上播出。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻今天早上已经播出了。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电视剧播出后，很多人都喜欢。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播里正在播出一首老歌。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的节目每周五播出一次。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天播出的节目，我还没看过。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广告因为有问题，没有播出。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台每天早上播出天气预报。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那集节目播出时，我正在做饭。", "target_word": "播出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "播出了", "label": "完成体"}, {"form": "播出过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "电视台、电台把节目发送出去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b382258-1d1c-4078-8cdf-3ee7f594def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "播出", "is_correct": true, "explanation": "正确：“播出”指电视台发出节目，与句中的“节目”和“晚上八点”搭配。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是人的动作，节目不能游泳，与“晚上八点”的节目时间无关。"}, {"text": "出售", "is_correct": false, "explanation": "语义：节目不能被“出售”，句中说的是播放的时间。"}, {"text": "印刷", "is_correct": false, "explanation": "语义：“印刷”针对纸张等材料，节目不能被印刷。"}], "explanations": {"播出": "正确：“播出”指电视台发出节目，与句中的“节目”和“晚上八点”搭配。", "游泳": "语义：“游泳”是人的动作，节目不能游泳，与“晚上八点”的节目时间无关。", "出售": "语义：节目不能被“出售”，句中说的是播放的时间。", "印刷": "语义：“印刷”针对纸张等材料，节目不能被印刷。"}, "sentence_index": 0, "correct_answer": "播出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电影院这个星期播出这部电影。", "explanation": "这里应该用〈放映〉。“播出”用于电视、广播的节目，电影院里的电影要说放映。"}, {"text": "剧团下周在剧场播出一场新戏。", "explanation": "这里应该用〈演出〉。“播出”指通过广播、电视发出节目，剧场里的表演要说演出。"}, {"text": "农民春天在田里播出玉米种子。", "explanation": "这里应该用〈播种〉。“播出”指发出节目，把种子种进土里要说播种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "播出", "is_correct": true, "explanation": "正确：“播出”指发出节目，与句中的“节目”搭配，表示昨天播出的节目。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对损坏的器物，节目不能被修理。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物等，不能说“洗节目”。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”针对布料，节目不能被缝。"}], "explanations": {"播出": "正确：“播出”指发出节目，与句中的“节目”搭配，表示昨天播出的节目。", "修理": "语义：“修理”针对损坏的器物，节目不能被修理。", "洗": "搭配：“洗”的对象是衣物等，不能说“洗节目”。", "缝": "搭配：“缝”针对布料，节目不能被缝。"}, "sentence_index": 6, "correct_answer": "播出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商店昨天播出了一批新的衣服。", "explanation": "这里应该用〈上架〉。“播出”的对象是节目，不能用于商品，新衣服上架要说上架。"}, {"text": "出版社去年播出了这本书。", "explanation": "这里应该用〈出版〉。“播出”用于广播、电视的节目，书籍要说出版。"}, {"text": "歌手今晚在体育馆播出一场演唱会。", "explanation": "这里应该用〈举办〉。“播出”指通过广播、电视发出节目，在现场举行演唱会要说举办或演出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部纪录片周六晚上电视上播出。", "corrected_sentence": "这部纪录片周六晚上在电视上播出。", "error_description": "错误：“播出”表示在某个地方发出节目，地点前要加“在”。正确应说“在电视上播出”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部动画片下周六播出过。", "corrected_sentence": "这部动画片下周六播出。", "error_description": "错误：“过”表示已经有过的经历，与“下周六”的将来时间矛盾。应去掉“过”，说“下周六播出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
