INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90535, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "场区是一个大场地里分出来的一块地方。", "primary_collocate": null, "pronunciation": "chǎng qū", "ipa": "ʈʂʰɑŋ˨˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "运动会的场地分成了四个场区。", "target_word": "场区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把车停在红色的场区里。", "target_word": "场区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左边的场区有很多椅子。", "target_word": "场区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在东边的场区玩游戏。", "target_word": "场区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个场区只有工作人员能进。", "target_word": "场区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先去北边的场区看看吧。", "target_word": "场区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排球落在对方的场区就得分。", "target_word": "场区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个场区门口都有一个牌子。", "target_word": "场区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，球员不能离开自己的场区。", "target_word": "场区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在最后一个场区找到了朋友。", "target_word": "场区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "場區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大场地里分出来的一块地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1bdeefd-92f9-4e14-bb18-a5d8568bc61c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90535, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场区", "is_correct": true, "explanation": "正确：“分成了四个”后接“场区”，指场地中划分出的区域。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“眼镜”通常以“副”计量，不能说“分成了四个眼镜”。"}, {"text": "奶茶", "is_correct": false, "explanation": "语义：“奶茶”与运动会场地的划分无关，句子不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：场地不能被分成四个闹钟，句子读起来不通。"}], "explanations": {"场区": "正确：“分成了四个”后接“场区”，指场地中划分出的区域。", "眼镜": "搭配：“眼镜”通常以“副”计量，不能说“分成了四个眼镜”。", "奶茶": "语义：“奶茶”与运动会场地的划分无关，句子不通。", "闹钟": "语义：场地不能被分成四个闹钟，句子读起来不通。"}, "sentence_index": 0, "correct_answer": "场区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盘饺子的场区很好吃。", "explanation": "这里应该用〈味道〉。“场区”指大场地中分出来的一块地方，不能用来说饺子好吃。"}, {"text": "这把伞的场区是蓝色的，很好看。", "explanation": "这里应该用〈颜色〉。“场区”指大场地中分出来的一块地方，不能用来说伞的颜色。"}, {"text": "妈妈把这个场区切开，分给了大家。", "explanation": "这里应该用〈蛋糕〉。“场区”指大场地中分出来的一块地方，不能用来指可以切开分的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场区", "is_correct": true, "explanation": "正确：“对方的”后接“场区”，指排球落地得分的比赛区域。"}, {"text": "书包", "is_correct": false, "explanation": "语义：排球落在书包上不能得分，“书包”与比赛规则无关。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”不是比赛场地，与排球得分的情境无关。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“对方的”后不能接“窗户”指比赛区域，“窗户”也不是场地。"}], "explanations": {"场区": "正确：“对方的”后接“场区”，指排球落地得分的比赛区域。", "书包": "语义：排球落在书包上不能得分，“书包”与比赛规则无关。", "冰箱": "语义：“冰箱”不是比赛场地，与排球得分的情境无关。", "窗户": "搭配：“对方的”后不能接“窗户”指比赛区域，“窗户”也不是场地。"}, "sentence_index": 6, "correct_answer": "场区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的场区太长了，听了半天没结束。", "explanation": "这里应该用〈时长〉。“场区”指大场地中分出来的一块地方，不能用来说歌曲长短。"}, {"text": "妈妈的场区很温柔。", "explanation": "这里应该用〈性格〉。“场区”指大场地中分出来的一块地方，不能用来形容人的性格。"}, {"text": "我每天早上喝一杯场区。", "explanation": "这里应该用〈牛奶〉。“场区”指大场地中分出来的一块地方，不能用来指可以喝的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "裁判在一张场区里吹哨。", "corrected_sentence": "裁判在一个场区里吹哨。", "error_description": "量词错误：“场区”应用量词“个”。“张”用于平面的东西，不能说“一张场区”，应说“一个场区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在一条场区里玩耍。", "corrected_sentence": "我们在一个场区里玩耍。", "error_description": "量词错误：“场区”应用量词“个”。“条”用于细长的东西，不能说“一条场区”，应说“一个场区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
