INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90538, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示一定、必定、必须。", "primary_collocate": null, "pronunciation": "bì", "ipa": "pi˥˩", "syllable_count": 1, "sentences": [{"text": "过马路时，必先看红绿灯。", "target_word": "必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "上车以后，必先系好安全带。", "target_word": "必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "进别人家门，必先敲门。", "target_word": "必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考试那天，学生必带身份证。", "target_word": "必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门以前，必先关好窗户。", "target_word": "必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "喝药以前，必先看说明书。", "target_word": "必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在图书馆里，大家必保持安静。", "target_word": "必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做饭以前，必先洗手。", "target_word": "必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开车的人必遵守交通规则。", "target_word": "必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乘飞机，必提前到机场。", "target_word": "必", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "必须", "label": "复合词"}, {"form": "必要", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "必：副词，表示规定或要求一定要这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126c1563-16f3-4d23-b8d9-2411ca5ce2db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90538, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "必", "is_correct": true, "explanation": "正确答案：必（bì，第四声），意思是一定要。"}, {"text": "比", "is_correct": false, "explanation": "bǐ（第三声）与 bì（第四声）声调不同，意思是比较。"}, {"text": "鼻", "is_correct": false, "explanation": "bí（第二声）与 bì（第四声）声调不同，意思是鼻子。"}, {"text": "逼", "is_correct": false, "explanation": "bī（第一声）与 bì（第四声）声调不同，意思是逼迫。"}, {"text": "布", "is_correct": false, "explanation": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是布匹。"}], "explanations": {"必": "正确答案：必（bì，第四声），意思是一定要。", "比": "bǐ（第三声）与 bì（第四声）声调不同，意思是比较。", "鼻": "bí（第二声）与 bì（第四声）声调不同，意思是鼻子。", "逼": "bī（第一声）与 bì（第四声）声调不同，意思是逼迫。", "布": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是布匹。"}, "sentence_index": null, "correct_answer": "必"}, "level_3": {"options": [{"text": "必", "is_correct": true, "explanation": "“必”表示规定一定要这样做，与“过马路时先看红绿灯”的要求相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“过马路时”这条必须遵守的规定相悖。"}, {"text": "几乎", "is_correct": false, "explanation": "搭配：“几乎”表示接近，不能用来说明一条规定性的先后顺序。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从未这样做，与规定“要先看红绿灯”的要求相反。"}], "explanations": {"必": "“必”表示规定一定要这样做，与“过马路时先看红绿灯”的要求相符。", "偶尔": "语义：“偶尔”表示不常发生，与“过马路时”这条必须遵守的规定相悖。", "几乎": "搭配：“几乎”表示接近，不能用来说明一条规定性的先后顺序。", "从不": "语义：“从不”表示从未这样做，与规定“要先看红绿灯”的要求相反。"}, "sentence_index": 0, "correct_answer": "必"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的天气很难说，明天必下大雨。", "explanation": "这里是把“必”当作“也许”的不确定义来用。“必”表示一定，与“很难说”矛盾；推测不定时应用〈也许〉。"}, {"text": "考试前请必检查答题卡。", "explanation": "这里应该用〈务必〉。“请”字开头的叮嘱要说“请务必……”；“必”单用一般用来陈述规定，不和“请”连用。"}, {"text": "考试那天，学生可以不带身份证，必带身份证。", "explanation": "这里是把“必”的必须义用在允许的语境里。“必”表示必须，与“可以不带”的允许矛盾；允许应用〈可以〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90538, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "必", "is_correct": true, "explanation": "正确答案：必（bì，第四声），意思是一定要。"}, {"text": "笔", "is_correct": false, "explanation": "bǐ（第三声）与 bì（第四声）声调不同，意思是笔。"}, {"text": "步", "is_correct": false, "explanation": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是脚步。"}, {"text": "不", "is_correct": false, "explanation": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是不。"}, {"text": "部", "is_correct": false, "explanation": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是部分、部门。"}], "explanations": {"必": "正确答案：必（bì，第四声），意思是一定要。", "笔": "bǐ（第三声）与 bì（第四声）声调不同，意思是笔。", "步": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是脚步。", "不": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是不。", "部": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是部分、部门。"}, "sentence_index": null, "correct_answer": "必"}, "level_3": {"options": [{"text": "必", "is_correct": true, "explanation": "“必”表示规定一定要保持，与“图书馆里”的公共要求相符。"}, {"text": "曾", "is_correct": false, "explanation": "语义：“曾”表示过去发生过，不能用来说明图书馆的规定，“大家曾保持安静”与规定语境不符。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词，不能直接修饰“保持”这样的动作。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”表示程度最高，不能直接修饰“保持”，“最保持安静”不通。"}], "explanations": {"必": "“必”表示规定一定要保持，与“图书馆里”的公共要求相符。", "曾": "语义：“曾”表示过去发生过，不能用来说明图书馆的规定，“大家曾保持安静”与规定语境不符。", "很": "搭配：“很”修饰形容词，不能直接修饰“保持”这样的动作。", "最": "搭配：“最”表示程度最高，不能直接修饰“保持”，“最保持安静”不通。"}, "sentence_index": 6, "correct_answer": "必"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你想几点到都行，必提前到机场。", "explanation": "这里是把“必”的必须义用在允许的语境里。“必”表示必须，与“几点到都行”的允许矛盾；允许应用〈可以〉。"}, {"text": "乘飞机，偶尔必提前到机场。", "explanation": "这里是把“必”用于偶然的情形。“必”表示一定或必须，与“偶尔”的不定频率矛盾；表示偶然应用〈有时〉。"}, {"text": "乘飞机，他说不定必提前到机场。", "explanation": "这里是把“必”用于推测不定的语境。“说不定”表示不确定，与“必”的一定义矛盾；不确定应用〈也许〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "进教室以前，大家关必手机。", "corrected_sentence": "进教室以前，大家必关手机。", "error_description": "“必”是副词，应放在动词前，说“大家必关手机”；“关必手机”把“必”放在动词后，语序是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "进医院以前，大家先必洗手。", "corrected_sentence": "进医院以前，大家必先洗手。", "error_description": "“必”是副词，应放在“先”之前，说“大家必先洗手”；“先必”的语序是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
