INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90539, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "墓地是埋葬去世的人的地方。", "primary_collocate": null, "pronunciation": "mù dì", "ipa": "mu˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这座山上有一块很大的墓地。", "target_word": "墓地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争结束后，他们建了一片新墓地。", "target_word": "墓地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "清明节，爸爸带着花去墓地看妈妈。", "target_word": "墓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墓地周围种着很多松树。", "target_word": "墓地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里以前是田地，现在是墓地。", "target_word": "墓地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墓地的门关了，我们进不去。", "target_word": "墓地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在墓地里为死去的朋友唱歌。", "target_word": "墓地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑以后，墓地里一个人也没有。", "target_word": "墓地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人在墓地工作了二十年。", "target_word": "墓地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在墓地旁边的小路上走了很久。", "target_word": "墓地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "公共墓地", "label": "复合"}], "register": "中性", "sense_fingerprint": "墓地：埋葬去世的人的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52af20df-6e56-40f6-a8c1-0c1dd987e45e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90539, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "墓地", "is_correct": true, "explanation": "墓地：埋葬去世的人的地方，是本题的正确答案。"}, {"text": "木底", "is_correct": false, "explanation": "mù dǐ（第三声）与 mù dì（第四声）只差第二字声调，意思是木底（鞋）。"}, {"text": "木笛", "is_correct": false, "explanation": "mù dí（第二声）与 mù dì 只差第二字声调，意思是木头做的笛子。"}, {"text": "牧笛", "is_correct": false, "explanation": "mù dí（第二声）与 mù dì 只差第二字声调，意思是牧童吹的笛子。"}], "explanations": {"墓地": "墓地：埋葬去世的人的地方，是本题的正确答案。", "木底": "mù dǐ（第三声）与 mù dì（第四声）只差第二字声调，意思是木底（鞋）。", "木笛": "mù dí（第二声）与 mù dì 只差第二字声调，意思是木头做的笛子。", "牧笛": "mù dí（第二声）与 mù dì 只差第二字声调，意思是牧童吹的笛子。"}, "sentence_index": null, "correct_answer": "墓地"}, "level_3": {"options": [{"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不是一大片地方，与句意不符。"}, {"text": "图书馆", "is_correct": false, "explanation": "搭配：量词“块”指一片地，图书馆是建筑，应说“座”，不说“一块图书馆”。"}, {"text": "墓地", "is_correct": true, "explanation": "墓地：埋葬去世的人的地方，与“很大的”“这座山上”的语境相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的房间，不会建在山上，与语境矛盾。"}], "explanations": {"沙发": "语义：沙发是家具，不是一大片地方，与句意不符。", "图书馆": "搭配：量词“块”指一片地，图书馆是建筑，应说“座”，不说“一块图书馆”。", "墓地": "墓地：埋葬去世的人的地方，与“很大的”“这座山上”的语境相符。", "厨房": "语义：厨房是做饭的房间，不会建在山上，与语境矛盾。"}, "sentence_index": 0, "correct_answer": "墓地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的墓地写得很长，大家念了半个小时。", "explanation": "这里应该用〈墓志铭〉。墓志铭是刻在碑上的文字，可以写得很长；墓地是一片土地，不能说写得多长。"}, {"text": "他把墓地竖在门口，让大家都能看见。", "explanation": "这里应该用〈墓碑〉。墓碑是竖立的石碑；墓地是一片土地，不能竖起来。"}, {"text": "他把墓地装进包里，带回了家。", "explanation": "这里应该用〈礼物〉。礼物可以装进包里带走；墓地是一片土地，不能装进包里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90539, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场是供人玩耍的场所，与“为死去的朋友唱歌”的情境不符。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场是买卖东西的地方，与祭奠朋友的情境不符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“在……里”要接能容纳人的场所，空气不能作为唱歌的场所。"}, {"text": "墓地", "is_correct": true, "explanation": "墓地：埋葬去世的人的地方，与“为死去的朋友唱歌”的情境相符。"}], "explanations": {"游乐场": "语义：游乐场是供人玩耍的场所，与“为死去的朋友唱歌”的情境不符。", "菜市场": "语义：菜市场是买卖东西的地方，与祭奠朋友的情境不符。", "空气": "搭配：“在……里”要接能容纳人的场所，空气不能作为唱歌的场所。", "墓地": "墓地：埋葬去世的人的地方，与“为死去的朋友唱歌”的情境相符。"}, "sentence_index": 6, "correct_answer": "墓地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把墓地搬到后院，准备在那里种菜。", "explanation": "这里应该用〈菜地〉。墓地是埋葬死者的地方，不能搬动，也不能用来种菜；种菜要说菜地。"}, {"text": "爷爷的墓地挂在客厅的墙上。", "explanation": "这里应该用〈遗像〉。遗像是挂起来供人纪念的照片，墓地是一片土地，不能挂在客厅里。"}, {"text": "墓地的房间打扫得很干净，客人住得很舒服。", "explanation": "这里应该用〈宾馆〉。宾馆有房间供客人住宿，墓地是安葬死者的地方，没有房间让客人住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山上有一条墓地。", "corrected_sentence": "山上有一块墓地。", "error_description": "量词错误：墓地不能用“条”，“条”用于细长的东西；“块”和“片”都可以。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天黑以后，墓地里一个人也不有。", "corrected_sentence": "天黑以后，墓地里一个人也没有。", "error_description": "否定词错误：「有」的否定只能用「没」，不能说「不有」，应说「一个人也没有」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90541, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90541, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90541, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "明明知道，还是这样做。", "primary_collocate": null, "pronunciation": "gù yì", "ipa": "ku˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "他明明知道路滑，还故意跑得很快。", "target_word": "故意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道你是故意不接我的电话。", "target_word": "故意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她故意把门关得很响，让大家都听见。", "target_word": "故意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是不会，是故意说错的。", "target_word": "故意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟故意藏起我的书，想看我着急。", "target_word": "故意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是不是故意让我等这么久？", "target_word": "故意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师知道他故意迟到，但没有说什么。", "target_word": "故意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，我不是故意踩你的脚。", "target_word": "故意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他故意不看我，好像不认识我一样。", "target_word": "故意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们故意大声说话，想让妈妈注意他们。", "target_word": "故意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "故意地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "明知如此，仍然这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '741a067b-35ee-42ee-a9a5-e70920a0d4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90541, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "故意", "is_correct": true, "explanation": "正确。故意（gù yì）：明知而有意去做。"}, {"text": "古意", "is_correct": false, "explanation": "gǔyì 与 gùyì 声调不同（gǔ 与 gù），古意指古朴的意味。"}, {"text": "故技", "is_correct": false, "explanation": "gùjì 与 gùyì 第二音节声母不同（jì 与 yì），故技指老办法、旧手段。"}, {"text": "妒意", "is_correct": false, "explanation": "dùyì 与 gùyì 第一音节声母不同（dù 与 gù），妒意指嫉妒的情绪。"}], "explanations": {"故意": "正确。故意（gù yì）：明知而有意去做。", "古意": "gǔyì 与 gùyì 声调不同（gǔ 与 gù），古意指古朴的意味。", "故技": "gùjì 与 gùyì 第二音节声母不同（jì 与 yì），故技指老办法、旧手段。", "妒意": "dùyì 与 gùyì 第一音节声母不同（dù 与 gù），妒意指嫉妒的情绪。"}, "sentence_index": null, "correct_answer": "故意"}, "level_3": {"options": [{"text": "故意", "is_correct": true, "explanation": "正确。“还”与“明明知道路滑”连用，表示明知不对仍这样做，只有“故意”符合。"}, {"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示与预料相符，与“明明知道路滑，还”的转折意思不合。"}, {"text": "其实", "is_correct": false, "explanation": "语义：“其实”引出实际情况，与“还”后面的主动行为不合，句子说不通。"}, {"text": "幸好", "is_correct": false, "explanation": "搭配：“幸好”引出已发生的好结果，不能用在“还”之后描述鲁莽的行为。"}], "explanations": {"故意": "正确。“还”与“明明知道路滑”连用，表示明知不对仍这样做，只有“故意”符合。", "果然": "语义：“果然”表示与预料相符，与“明明知道路滑，还”的转折意思不合。", "其实": "语义：“其实”引出实际情况，与“还”后面的主动行为不合，句子说不通。", "幸好": "搭配：“幸好”引出已发生的好结果，不能用在“还”之后描述鲁莽的行为。"}, "sentence_index": 0, "correct_answer": "故意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我故意把钥匙落在了办公室，完全没注意到。", "explanation": "这里应该用〈不小心〉。故意表示明知而有意去做，与“完全没注意到”矛盾；无意中做的事应说“不小心”。"}, {"text": "听到这个消息，我故意感到很难过。", "explanation": "这里应该用〈假装〉。故意指有意去做，“感到难过”是不由自主的内心感受，不能有意而为；想表现出难过的样子才说“假装”。"}, {"text": "昨天故意下雨，我们只好取消了野餐。", "explanation": "这里应该用〈偏偏〉。偏偏表示事情恰好不如人意，是自然发生的；故意指有意去做，下雨是自然现象，不能有意而为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90541, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "故意", "is_correct": true, "explanation": "正确。故意（gù yì）：明知而有意去做。"}, {"text": "句意", "is_correct": false, "explanation": "jùyì 与 gùyì 第一音节声母不同（jù 与 gù），句意指句子表达的意思。"}, {"text": "去意", "is_correct": false, "explanation": "qùyì 与 gùyì 第一音节声母不同（qù 与 gù），去意指离开的打算。"}, {"text": "怒意", "is_correct": false, "explanation": "nùyì 与 gùyì 第一音节声母不同（nù 与 gù），怒意指愤怒的情绪。"}], "explanations": {"故意": "正确。故意（gù yì）：明知而有意去做。", "句意": "jùyì 与 gùyì 第一音节声母不同（jù 与 gù），句意指句子表达的意思。", "去意": "qùyì 与 gùyì 第一音节声母不同（qù 与 gù），去意指离开的打算。", "怒意": "nùyì 与 gùyì 第一音节声母不同（nù 与 gù），怒意指愤怒的情绪。"}, "sentence_index": null, "correct_answer": "故意"}, "level_3": {"options": [{"text": "故意", "is_correct": true, "explanation": "正确。“知道他”之后接“迟到”，说明他是有意而为，只有“故意”符合。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”表示急忙去做某事，与“迟到”语义矛盾，“赶紧迟到”不通。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，老师事先“知道”，就不能用“竟然”。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：“恰好”表示碰巧，与“知道”所表示的事先了解相矛盾。"}], "explanations": {"故意": "正确。“知道他”之后接“迟到”，说明他是有意而为，只有“故意”符合。", "赶紧": "搭配：“赶紧”表示急忙去做某事，与“迟到”语义矛盾，“赶紧迟到”不通。", "竟然": "语义：“竟然”表示出乎意料，老师事先“知道”，就不能用“竟然”。", "恰好": "语义：“恰好”表示碰巧，与“知道”所表示的事先了解相矛盾。"}, "sentence_index": 6, "correct_answer": "故意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们俩故意在同一天过生日，真是奇怪。", "explanation": "这里应该用〈碰巧〉。生日由出生日期决定，不能有意选择，两个人同一天生日只能说“碰巧”。"}, {"text": "我故意在街上碰见了老同学，真是没想到。", "explanation": "这里应该用〈偶然〉。故意表示有意去做，与“真是没想到”的意外相矛盾。"}, {"text": "他的头发故意白了一大片。", "explanation": "这里应该用〈自然〉。故意指有意去做，头发变白是自然发生的变化，不能有意而为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他故意得躲在门后面，想吓我一跳。", "corrected_sentence": "他故意地躲在门后面，想吓我一跳。", "error_description": "「故意」作状语修饰动词「躲」时，后面用结构助词「地」，不能用「得」。「得」用在动词后面引出补语。正确为「故意地躲在门后面」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他故意了撞我一下，然后笑了。", "corrected_sentence": "他故意撞了我一下，然后笑了。", "error_description": "「了」应放在动词「撞」之后，表示动作完成。「故意了撞」把「了」放在了「故意」之后，是错误的；正确为「故意撞了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
