INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90544, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为喜事或纪念日举行活动，表示高兴或纪念。", "primary_collocate": null, "pronunciation": "qìng zhù", "ipa": "tɕʰiŋ˥˩ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "学校举行大会，庆祝建校一百年。", "target_word": "庆祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国人民一起庆祝国庆节。", "target_word": "庆祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司开了一个晚会，庆祝新产品成功。", "target_word": "庆祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里放烟花，庆祝新年到来。", "target_word": "庆祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们走上街头，庆祝球队夺冠。", "target_word": "庆祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们举行活动，庆祝中秋节。", "target_word": "庆祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家在广场上跳舞，庆祝丰收。", "target_word": "庆祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们每年都会庆祝结婚纪念日。", "target_word": "庆祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里挂起红灯笼，庆祝春节。", "target_word": "庆祝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了庆祝成立十周年，公司送给每个人一份礼物。", "target_word": "庆祝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "庆祝了", "label": "完成体"}, {"form": "庆祝过", "label": "经历体"}, {"form": "庆祝着", "label": "持续体"}, {"form": "庆祝活动", "label": "复合词"}, {"form": "慶祝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "庆祝：为喜事或纪念日举行集体活动或仪式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20866e08-b43e-403c-ad2b-6b6e0b8a5d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90544, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "庆祝", "is_correct": true, "explanation": "正确。「庆祝」表示学校为建校一百年举行大会欢庆，与句意相符。"}, {"text": "哀悼", "is_correct": false, "explanation": "语义：「哀悼」表示悼念逝者，与建校的喜事不合。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：「忘记」表示不记得，与学校为此举行大会的做法相矛盾。"}, {"text": "取消", "is_correct": false, "explanation": "搭配：「取消」的对象应是活动，不能说「取消建校一百年」。"}], "explanations": {"庆祝": "正确。「庆祝」表示学校为建校一百年举行大会欢庆，与句意相符。", "哀悼": "语义：「哀悼」表示悼念逝者，与建校的喜事不合。", "忘记": "语义：「忘记」表示不记得，与学校为此举行大会的做法相矛盾。", "取消": "搭配：「取消」的对象应是活动，不能说「取消建校一百年」。"}, "sentence_index": 0, "correct_answer": "庆祝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人们在墓前庆祝亲人。", "explanation": "这里应该用〈怀念〉。「庆祝」用于喜事或纪念日，对逝去的亲人应表示怀念。"}, {"text": "全国人民庆祝逝者。", "explanation": "这里应该用〈哀悼〉。「庆祝」用于喜事，不能用于逝者。"}, {"text": "城市里庆祝失火。", "explanation": "「庆祝」只用于喜事或纪念日，失火是不幸的事，不能用「庆祝」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庆祝", "is_correct": true, "explanation": "正确。「庆祝」表示大家在广场跳舞欢庆丰收，与句意相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：「嘲笑」表示取笑，与跳舞欢庆的气氛相反，不能用于丰收。"}, {"text": "抗议", "is_correct": false, "explanation": "搭配：「抗议」的对象不能是丰收，不能说「抗议丰收」。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：「放弃」表示舍弃，与广场上庆祝丰收的场景相矛盾。"}], "explanations": {"庆祝": "正确。「庆祝」表示大家在广场跳舞欢庆丰收，与句意相符。", "嘲笑": "语义：「嘲笑」表示取笑，与跳舞欢庆的气氛相反，不能用于丰收。", "抗议": "搭配：「抗议」的对象不能是丰收，不能说「抗议丰收」。", "放弃": "语义：「放弃」表示舍弃，与广场上庆祝丰收的场景相矛盾。"}, "sentence_index": 6, "correct_answer": "庆祝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去车站庆祝要离开的朋友。", "explanation": "这里应该用〈送行〉。「庆祝」用于喜事，不能用于送别朋友。"}, {"text": "领导去医院庆祝病人。", "explanation": "这里应该用〈慰问〉。「庆祝」只用于喜事，探望病人应表示关心。"}, {"text": "市民庆祝这场地震。", "explanation": "这里应该用〈悼念〉。「庆祝」只用于喜事，地震是灾难，不能用「庆祝」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校昨天庆祝着建校一百年。", "corrected_sentence": "学校昨天庆祝了建校一百年。", "error_description": "错误：「着」。「庆祝」是已完成的活动，过去时应用「了」，不用「着」。正确：「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司庆祝了过建厂五十年。", "corrected_sentence": "公司庆祝过建厂五十年。", "error_description": "错误：「了过」。「庆祝」后用「过」表示经历，不能再加「了」。正确：「过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90546, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忠心", "is_correct": true, "explanation": "正确：忠心指忠诚，与“二心”（即本义的外心）相反，是反义词。"}, {"text": "木头", "is_correct": false, "explanation": "木头是实物名词，与外心没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "天气是自然现象的名词，与外心没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是建筑部件，与外心没有反义关系。"}], "correct_answer": "忠心", "explanations": {"忠心": "正确：忠心指忠诚，与“二心”（即本义的外心）相反，是反义词。", "木头": "木头是实物名词，与外心没有反义关系。", "天气": "天气是自然现象的名词，与外心没有反义关系。", "窗户": "窗户是建筑部件，与外心没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
