INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90546, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对自己人不忠诚、怀有二心的心思。", "primary_collocate": null, "pronunciation": "wài xīn", "ipa": "wai˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "他对公司有了外心，经常偷偷看别家的招聘。", "target_word": "外心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家发现他有外心，就不再信任他了。", "target_word": "外心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大臣表面忠诚，其实早有外心。", "target_word": "外心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对丈夫没有外心，一直很专一。", "target_word": "外心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军怀疑他有外心，没让他带兵。", "target_word": "外心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，员工一旦有了外心，就会偷偷把客户资料交给别家公司。", "target_word": "外心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是有外心，就请直接告诉我。", "target_word": "外心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对朋友从来没有过外心。", "target_word": "外心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你有外心，这是真的吗？", "target_word": "外心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对球队产生外心的球员，不会再努力训练。", "target_word": "外心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "对自己人不忠诚、怀有二心的心思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0164a193-a1b9-4b34-a43a-61ec32a530f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90546, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外心", "is_correct": true, "explanation": "正确答案：外心，指对自己人不忠诚、怀有二心的心思。"}, {"text": "外星", "is_correct": false, "explanation": "xīng 与 xīn 韵母不同（ng 与 n），意思是外星，指地球以外的星体。"}, {"text": "外形", "is_correct": false, "explanation": "xíng（第二声）与 xīn（第一声）韵母与声调都不同，意思是外形，指事物的外部形状。"}, {"text": "外姓", "is_correct": false, "explanation": "xìng（第四声、后鼻音 ng）与 xīn（第一声、前鼻音 n）读音不同，意思是外姓，指不同姓氏的人。"}], "explanations": {"外心": "正确答案：外心，指对自己人不忠诚、怀有二心的心思。", "外星": "xīng 与 xīn 韵母不同（ng 与 n），意思是外星，指地球以外的星体。", "外形": "xíng（第二声）与 xīn（第一声）韵母与声调都不同，意思是外形，指事物的外部形状。", "外姓": "xìng（第四声、后鼻音 ng）与 xīn（第一声、前鼻音 n）读音不同，意思是外姓，指不同姓氏的人。"}, "sentence_index": null, "correct_answer": "外心"}, "level_3": {"options": [{"text": "外心", "is_correct": true, "explanation": "正确：外心指对自己人不忠诚、怀有二心，与“偷偷看别家的招聘”相合。"}, {"text": "好心", "is_correct": false, "explanation": "语义：好心指善意，与“偷偷看别家的招聘”的意思矛盾。"}, {"text": "童心", "is_correct": false, "explanation": "语义：“童心”指天真的心性，与“对公司有了外心”无关，不能填入。"}, {"text": "爱心", "is_correct": false, "explanation": "语义：爱心指关爱他人，与“偷偷看别家的招聘”的意思矛盾。"}], "explanations": {"外心": "正确：外心指对自己人不忠诚、怀有二心，与“偷偷看别家的招聘”相合。", "好心": "语义：好心指善意，与“偷偷看别家的招聘”的意思矛盾。", "童心": "语义：“童心”指天真的心性，与“对公司有了外心”无关，不能填入。", "爱心": "语义：爱心指关爱他人，与“偷偷看别家的招聘”的意思矛盾。"}, "sentence_index": 0, "correct_answer": "外心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他学习很有外心，每天都坚持复习。", "explanation": "这里应该用〈恒心〉。外心指对自己人不忠诚，不能用来形容学习的坚持。"}, {"text": "他对病人很有外心，总是耐心照顾。", "explanation": "这里应该用〈爱心〉。外心指对自己人不忠诚，不能用来说对病人的关心。"}, {"text": "她对新同学很有外心，常常主动帮助他们。", "explanation": "这里应该用〈热心〉。外心指对自己人不忠诚，不能用来形容乐于助人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外心", "is_correct": true, "explanation": "正确：这里指对自己人怀有二心，符合语境。"}, {"text": "外出", "is_correct": false, "explanation": "语法：“外出”是动词，不能放在“有”后面作宾语。"}, {"text": "外面", "is_correct": false, "explanation": "语法：“外面”是方位词，“你要是有外面”说不通。"}, {"text": "小心", "is_correct": false, "explanation": "语法：“小心”是形容词或动词，不能说“有小心”。"}], "explanations": {"外心": "正确：这里指对自己人怀有二心，符合语境。", "外出": "语法：“外出”是动词，不能放在“有”后面作宾语。", "外面": "语法：“外面”是方位词，“你要是有外面”说不通。", "小心": "语法：“小心”是形容词或动词，不能说“有小心”。"}, "sentence_index": 6, "correct_answer": "外心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下了很大的外心，一定要学好中文。", "explanation": "这里应该用〈决心〉。外心指对自己人不忠诚，不能说下外心来表示决定。"}, {"text": "今天我的外心特别好，一直在笑。", "explanation": "这里应该用〈心情〉。外心指对自己人不忠诚，不能用来说心情的好坏。"}, {"text": "他对这次比赛充满外心。", "explanation": "这里应该用〈信心〉。外心指对自己人不忠诚，不能用来表示对比赛有把握。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位将领对朝廷有了一条外心，皇上很快就察觉了。", "corrected_sentence": "这位将领对朝廷有了外心，皇上很快就察觉了。", "error_description": "错误：“外心”前加了量词“条”。“条”用于细长的物体，不能用来量心思，这里不需要量词。错误形式：一条外心；正确形式：外心。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对父母从来没有了外心。", "corrected_sentence": "他对父母从来没有过外心。", "error_description": "错误：“了”与“过”用错。“从来没有”表示从未有过经历，应用“过”，不能用“了”。错误形式：从来没有了外心；正确形式：从来没有过外心。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
