INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90549, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "外送是把买好的东西送到你家门口。", "primary_collocate": null, "pronunciation": "wài sòng", "ipa": "uai̯˥˩ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这家家具店可以外送到你家。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你买的大米，超市可以外送。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买了冰箱以后，商店会外送。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市说，满一百块就可以外送。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个花店的花可以外送到家门口。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了很多水果，请帮我外送。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家药店也外送药品。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店把新买的沙发外送到了我家。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东西太重了，我想让店里外送。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买好以后，店员问我要不要外送。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外送了", "label": "体标（了）"}, {"form": "外送过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "商店把顾客买好的商品送到顾客家门口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3040b130-1c83-4aba-a0d1-f87d0f162c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90549, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外送", "is_correct": true, "explanation": "正确。“外送”指商家把买好的东西送到顾客家门口，符合“这家家具店可以……到你家”的句意。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”指对房屋进行施工，家具店不能把“装修”送到你家。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：家具店不负责上门打扫，“打扫到你家”与家具店的经营内容不符。"}, {"text": "挑选", "is_correct": false, "explanation": "配价：“挑选”后面接的是被选的物品，不能接“到你家”这样的地点。"}], "explanations": {"外送": "正确。“外送”指商家把买好的东西送到顾客家门口，符合“这家家具店可以……到你家”的句意。", "装修": "搭配：“装修”指对房屋进行施工，家具店不能把“装修”送到你家。", "打扫": "语义：家具店不负责上门打扫，“打扫到你家”与家具店的经营内容不符。", "挑选": "配价：“挑选”后面接的是被选的物品，不能接“到你家”这样的地点。"}, "sentence_index": 0, "correct_answer": "外送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这本书外送给了朋友。", "explanation": "这里应该用〈送〉。外送专指商家把顾客买的东西送到家门口，朋友之间互相赠书不用“外送”。"}, {"text": "公司决定把小王外送到国外工作。", "explanation": "这里应该用〈外派〉。外送只用于商品和饭菜，不能用于人。"}, {"text": "我把邮件外送给了老板。", "explanation": "这里应该用〈发送〉。外送指配送货物或饭菜，电子邮件不属于这类对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90549, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外送", "is_correct": true, "explanation": "正确。“外送”指商家把商品送到顾客指定的地方，符合“这家药店也……药品”的句意。"}, {"text": "打印", "is_correct": false, "explanation": "语义：药店不能“打印”药品，句子语义不通。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”搭配植物，不能说“种植药品”。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，后面不能带“药品”作宾语。"}], "explanations": {"外送": "正确。“外送”指商家把商品送到顾客指定的地方，符合“这家药店也……药品”的句意。", "打印": "语义：药店不能“打印”药品，句子语义不通。", "种植": "搭配：“种植”搭配植物，不能说“种植药品”。", "游泳": "配价：“游泳”是不及物动词，后面不能带“药品”作宾语。"}, "sentence_index": 6, "correct_answer": "外送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妈妈每个月都把生活费外送到老家。", "explanation": "这里应该用〈寄〉。外送只用于商品和饭菜，寄钱回家不能说“外送”。"}, {"text": "他把小狗外送到朋友家寄养。", "explanation": "这里应该用〈托付〉。外送指商家把买的东西送到顾客家门口，不能用来指把动物交给朋友照看。"}, {"text": "同学们把作业外送给了老师。", "explanation": "这里应该用〈交〉。外送是商家送货上门，同学交作业应说“交”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90549, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店家已经把我买的东西外送家了。", "corrected_sentence": "店家已经把我买的东西外送到家了。", "error_description": "错误在于漏掉补语“到”。“外送”后要用“到家”表示送达的地点，应说“外送到家了”，不能说“外送家了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90549, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在网上买的菜已经外送到家过。", "corrected_sentence": "我在网上买的菜已经外送到家了。", "error_description": "错误在于体标用错。“已经”表示已完成，应用“了”，“过”表示经历，不能用于此句，应改为“外送到家了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
