INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90550, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "商家把饭菜等送到顾客指定的地点。", "primary_collocate": null, "pronunciation": "wài sòng", "ipa": "uai̯˥˩ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这家饭馆晚上也外送。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我点的饭菜，店家二十分钟就外送到了公司。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这份饭菜外送到三楼办公室。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家火锅店不外送，只能在店里吃。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，很多餐厅都不外送。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说饭菜会外送到你指定的地方。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的面条外送得很快。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店家已经把热汤外送到学校门口了。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们店中午十二点以后不外送。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的地址在哪儿？我们外送到那儿。", "target_word": "外送", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外送了", "label": "体标（了）"}, {"form": "外送过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "餐馆等商家把饭菜送到顾客指定的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3040b130-1c83-4aba-a0d1-f87d0f162c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外送", "is_correct": true, "explanation": "正确。“外送”指商家把饭菜送到顾客指定的地方，符合“这家饭馆晚上也……”的句意。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：饭馆是机构，不会“失眠”，句子语义不通。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：饭馆不会“哭泣”，句子语义不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：饭馆不能“结婚”，句子语义不通。"}], "explanations": {"外送": "正确。“外送”指商家把饭菜送到顾客指定的地方，符合“这家饭馆晚上也……”的句意。", "失眠": "语义：饭馆是机构，不会“失眠”，句子语义不通。", "哭泣": "语义：饭馆不会“哭泣”，句子语义不通。", "结婚": "语义：饭馆不能“结婚”，句子语义不通。"}, "sentence_index": 0, "correct_answer": "外送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服务员把饭菜外送到了我们的包间里。", "explanation": "这里应该用〈端〉。外送是商家把饭菜送到店外顾客指定的地址，店内上菜要说“端”。"}, {"text": "他把孩子外送到奶奶家住了一个月。", "explanation": "这里应该用〈托付〉。外送是商家配送饭菜或货物的服务，不能用来指把孩子交给别人照顾。"}, {"text": "我们把生日礼物外送给了妈妈。", "explanation": "这里应该用〈送〉。外送是商家的配送服务，家人之间赠送礼物不能说外送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外送", "is_correct": true, "explanation": "正确。“外送得很快”描述商家送餐的速度，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：面条不会唱歌，“唱得很快”句子语义不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：面条不能散步，“散步得很快”句子语义不通。"}, {"text": "发表", "is_correct": false, "explanation": "配价：“发表”需要文章、论文等被发表的内容，“面条”不能充当其主语。"}], "explanations": {"外送": "正确。“外送得很快”描述商家送餐的速度，符合句意。", "唱": "语义：面条不会唱歌，“唱得很快”句子语义不通。", "散步": "语义：面条不能散步，“散步得很快”句子语义不通。", "发表": "配价：“发表”需要文章、论文等被发表的内容，“面条”不能充当其主语。"}, "sentence_index": 6, "correct_answer": "外送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每个月都把零花钱外送给爸爸。", "explanation": "这里应该用〈交〉。外送指商家配送饭菜或货物，把零花钱交给爸爸不能说外送。"}, {"text": "他把兔子外送到朋友家寄养。", "explanation": "这里应该用〈托付〉。外送指商家配送饭菜或货物，不能用来指把动物交给朋友照看。"}, {"text": "小明把试卷外送到了班主任办公室。", "explanation": "这里应该用〈交〉。外送是商家送货上门，交试卷应说“交”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店家很快就把我订的饭外送了到公寓楼下。", "corrected_sentence": "店家很快就把我订的饭外送到公寓楼下。", "error_description": "“了”放在动词“外送”和补语“到公寓楼下”之间是错误的。应说“外送到公寓楼下”，不能说“外送了到公寓楼下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的饭外送地特别快，我很满意。", "corrected_sentence": "这家店的饭外送得特别快，我很满意。", "error_description": "补语标记用错。“地”用于状语，修饰动词前；“外送”后引出补语“特别快”要用“得”。应说“外送得特别快”，不能说“外送地特别快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
