INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90553, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打电话是用手机或电话和远处的人说话。", "primary_collocate": null, "pronunciation": "dǎ diàn huà", "ipa": "ta˨˩ tjɛn˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "我每天晚上给妈妈打电话。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在路上一边走一边打电话。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没有电了，不能打电话。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想打电话问问朋友在哪儿。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天早上我会给你打电话。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在外面打电话，声音很小。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先打电话告诉老师。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在国外，我们常常打电话。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天给他打电话了，可是他没接。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的时候不要打电话。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了电话", "label": "体标"}, {"form": "打过电话", "label": "体标"}, {"form": "打着电话", "label": "体标"}], "register": "口语", "sense_fingerprint": "用手机或电话和不在身边的人说话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2a424d-fb6a-4c27-a32b-e3eed49ee37f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90553, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打电话", "is_correct": true, "explanation": "“打电话”指用电话和远处的人说话，与“每天晚上给妈妈”相符。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”是不及物动作，常说“陪妈妈散步”，不能说“给妈妈散步”。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”不能带“给妈妈”这样的间接对象，“给妈妈睡觉”不成立。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能发给某人，与句意不合。"}], "explanations": {"打电话": "“打电话”指用电话和远处的人说话，与“每天晚上给妈妈”相符。", "散步": "搭配：“散步”是不及物动作，常说“陪妈妈散步”，不能说“给妈妈散步”。", "睡觉": "配价：“睡觉”不能带“给妈妈”这样的间接对象，“给妈妈睡觉”不成立。", "下雨": "语义：“下雨”是天气现象，不能发给某人，与句意不合。"}, "sentence_index": 0, "correct_answer": "打电话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他坐在打字机前打电话，写完了一封信。", "explanation": "这里应该用〈敲字〉。打电话是用电话通话，坐在打字机前输入文字要说敲字。"}, {"text": "他当面跟我打电话，我们坐在一起。", "explanation": "这里应该用〈说话〉。两人面对面时要说话，不能用打电话，打电话必须隔着电话。"}, {"text": "窗户突然打电话给我，吓了我一跳。", "explanation": "这里应该用〈响〉。窗户不会打电话，窗户突然发出声音要说响；打电话的主语必须是能使用电话的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90553, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打电话", "is_correct": true, "explanation": "“打电话”是先用电话联系，再告诉老师，符合句意。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“告诉老师”的联系目的不相关，先唱歌再告诉老师不合逻辑。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与“告诉老师”没有关联，“先游泳再告诉老师”语义不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”是私人活动，与“先告诉老师”没有逻辑联系，句意不通。"}], "explanations": {"打电话": "“打电话”是先用电话联系，再告诉老师，符合句意。", "唱歌": "语义：“唱歌”与“告诉老师”的联系目的不相关，先唱歌再告诉老师不合逻辑。", "游泳": "语义：“游泳”与“告诉老师”没有关联，“先游泳再告诉老师”语义不通。", "洗澡": "语义：“洗澡”是私人活动，与“先告诉老师”没有逻辑联系，句意不通。"}, "sentence_index": 6, "correct_answer": "打电话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天我们常去湖里打电话。", "explanation": "这里应该用〈游泳〉。打电话是用电话通话，去湖里活动要说游泳。"}, {"text": "他用相机打电话，拍了很多风景。", "explanation": "这里应该用〈照相〉。相机用来拍照，不能用来打电话。"}, {"text": "她用铅笔打电话，写了一整页字。", "explanation": "这里应该用〈写字〉。打电话需要用电话，用铅笔写字要说写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90553, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每个星期把奶奶打电话。", "corrected_sentence": "我每个星期给奶奶打电话。", "error_description": "介词用错。“打电话”的受话人须用“给”或“跟”引出，不能用“把”字句处置；“把奶奶打电话”不成立，应说“给奶奶打电话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90553, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天打电话着，但是没有人接。", "corrected_sentence": "他昨天打电话了，但是没有人接。", "error_description": "动态助词用错。“着”表示动作持续或伴随状态，须插在离合词中间（如“打着电话”），不能附加在“打电话”之后；对昨天一次已完成的通话应说“打电话了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
