INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90554, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使用电话与他人通话。", "primary_collocate": null, "pronunciation": "dǎ diàn huà", "ipa": "ta˨˩ tjɛn˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "我在办公室打电话的时候，他进来了。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要打电话给客人确认时间。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在车站打电话找朋友。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子想打电话给爸爸。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在打电话，请你等一下。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以用我的手机打电话。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给医院打电话问明天能不能去。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天他打电话打了一个小时。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有事的话，你就打电话找我。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约好了，到了就打电话。", "target_word": "打电话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了电话", "label": "体标"}, {"form": "打过电话", "label": "体标"}, {"form": "打着电话", "label": "体标"}], "register": "口语", "sense_fingerprint": "使用电话和别人通话，联系或询问事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c2a424d-fb6a-4c27-a32b-e3eed49ee37f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90554, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打电话", "is_correct": true, "explanation": "“打电话”指用电话通话，在办公室通话时他进来，符合句意。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”需要水池或水域，与“办公室”的场景不符。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：“游览”通常搭配景点，不能说“在办公室游览”。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”需要浴室，在办公室洗澡与句中的场景不符。"}], "explanations": {"打电话": "“打电话”指用电话通话，在办公室通话时他进来，符合句意。", "游泳": "语义：“游泳”需要水池或水域，与“办公室”的场景不符。", "游览": "搭配：“游览”通常搭配景点，不能说“在办公室游览”。", "洗澡": "语义：“洗澡”需要浴室，在办公室洗澡与句中的场景不符。"}, "sentence_index": 0, "correct_answer": "打电话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们面对面坐在饭桌旁打电话，你一句我一句，大家都很开心。", "explanation": "这里应该用〈聊天〉。面对面说话不用打电话，同坐一桌说话要说聊天。"}, {"text": "他每天早上打电话看新闻。", "explanation": "这里应该用〈上网〉。打电话是用电话通话，看新闻要说上网。"}, {"text": "这台旧电视突然打电话给我，把我吓了一跳。", "explanation": "这里应该用〈响〉。电视不能打电话，电视突然发出声音要说响；打电话只用于能使用电话的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打电话", "is_correct": true, "explanation": "“打电话”用电话联系医院，与后面“问明天能不能去”相符。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与“问明天能不能去”的交际目的不符，给医院跳舞不合逻辑。"}, {"text": "上班", "is_correct": false, "explanation": "配价：“上班”是不及物动词，不能接“问明天能不能去”，“给医院上班”与句意不合。"}, {"text": "洗车", "is_correct": false, "explanation": "搭配：“洗车”的对象是车，不能用“给医院”和“问”组成这样的句子。"}], "explanations": {"打电话": "“打电话”用电话联系医院，与后面“问明天能不能去”相符。", "跳舞": "语义：“跳舞”与“问明天能不能去”的交际目的不符，给医院跳舞不合逻辑。", "上班": "配价：“上班”是不及物动词，不能接“问明天能不能去”，“给医院上班”与句意不合。", "洗车": "搭配：“洗车”的对象是车，不能用“给医院”和“问”组成这样的句子。"}, "sentence_index": 6, "correct_answer": "打电话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "见面时，我们互相打电话。", "explanation": "这里应该用〈握手〉。见面时互相握手，不能用打电话。"}, {"text": "离开时他朝我打电话。", "explanation": "这里应该用〈挥手〉。朝人告别是挥手，不能用打电话。"}, {"text": "这只小猫坐在窗台上打电话，喵喵叫。", "explanation": "这里应该用〈叫唤〉。小猫不能打电话，猫发出声音要说叫唤；打电话需要能使用电话的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前打着电话给那家店。", "corrected_sentence": "我以前打过电话给那家店。", "error_description": "体标用错。“着”表示动作正在进行，与“以前”表示的曾经经历不符；表示曾经做过应说“打过电话”，不能说“打着电话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我刚才打电话老师了。", "corrected_sentence": "我刚才打电话给老师了。", "error_description": "缺少介词。“打电话”后要用“给”引出接电话的人，应说“打电话给老师”，不能说“打电话老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948a665a-8759-4e46-b926-7cb71e511925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
