INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90555, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大叔是对比爸爸年纪小一点的男人的亲切叫法。", "primary_collocate": null, "pronunciation": "dà shū", "ipa": "ta˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "那位大叔对我们很好。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大叔，请问去车站怎么走？", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居大叔常常送我们水果。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叫他大叔，他笑着答应了。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大叔开车送我回家。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔壁的大叔会修自行车。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大叔给孩子们讲了一个故事。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大叔在公园里下棋。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比我爸爸小，所以我叫他大叔。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大叔笑着说：“慢点儿吃。”", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "大叔：亲切地称呼比父亲年纪小的男性长辈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3040b130-1c83-4aba-a0d1-f87d0f162c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90555, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大叔", "is_correct": true, "explanation": "正确答案。大叔读作 dà shū，指比爸爸年纪小一点的男性。"}, {"text": "大树", "is_correct": false, "explanation": "dà shù（第四声）与 dà shū（第一声）的第二音节声调不同，意思是大树。"}, {"text": "大暑", "is_correct": false, "explanation": "shǔ（第三声）与 shū（第一声）声调不同，意思是二十四节气之一的大暑。"}, {"text": "大数", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，意思是很大的数目。"}, {"text": "大鼠", "is_correct": false, "explanation": "shǔ（第三声）与 shū（第一声）声调不同，意思是大型老鼠。"}], "explanations": {"大叔": "正确答案。大叔读作 dà shū，指比爸爸年纪小一点的男性。", "大树": "dà shù（第四声）与 dà shū（第一声）的第二音节声调不同，意思是大树。", "大暑": "shǔ（第三声）与 shū（第一声）声调不同，意思是二十四节气之一的大暑。", "大数": "shù（第四声）与 shū（第一声）声调不同，意思是很大的数目。", "大鼠": "shǔ（第三声）与 shū（第一声）声调不同，意思是大型老鼠。"}, "sentence_index": null, "correct_answer": "大叔"}, "level_3": {"options": [{"text": "大叔", "is_correct": true, "explanation": "正确。“那位”用于指人，“大叔”指比爸爸年纪小的男子，符合句意。"}, {"text": "小狗", "is_correct": false, "explanation": "搭配：“位”只用来数人，不能说“那位小狗”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是无生命的物体，不能“对我们很好”。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是物品，不会对人好，句子语义不通。"}], "explanations": {"大叔": "正确。“那位”用于指人，“大叔”指比爸爸年纪小的男子，符合句意。", "小狗": "搭配：“位”只用来数人，不能说“那位小狗”。", "房子": "语义：房子是无生命的物体，不能“对我们很好”。", "钢笔": "语义：钢笔是物品，不会对人好，句子语义不通。"}, "sentence_index": 0, "correct_answer": "大叔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位大叔已经八十岁了，身体还很好。", "explanation": "这里应该用〈大爷〉。大叔指比爸爸年纪小的男性，八十岁的老人不能称为“大叔”。"}, {"text": "我姐姐很漂亮，大家都叫她大叔。", "explanation": "这里混淆了〈大叔〉与〈大姐〉。大叔指比爸爸年纪小的男性，称呼女性应用“大姐”。"}, {"text": "哥哥才二十岁，弟弟却叫他大叔。", "explanation": "这里应该用〈哥哥〉。大叔指比爸爸年纪小一点的成年男子，弟弟称呼自己二十岁的哥哥不能用“大叔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90555, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大叔", "is_correct": true, "explanation": "正确答案。大叔读作 dà shū，指比爸爸年纪小一点的男性。"}, {"text": "大师", "is_correct": false, "explanation": "dà shī 与 dà shū 声调相同，只有韵母不同（i 与 u），意思是某方面造诣很深的人。"}, {"text": "大使", "is_correct": false, "explanation": "dà shǐ 的韵母（i）和声调（第三声）都与 shū 不同，意思是国家派往外国的外交代表。"}, {"text": "大事", "is_correct": false, "explanation": "dà shì 的韵母（i）和声调（第四声）都与 shū 不同，意思是重要的事情。"}], "explanations": {"大叔": "正确答案。大叔读作 dà shū，指比爸爸年纪小一点的男性。", "大师": "dà shī 与 dà shū 声调相同，只有韵母不同（i 与 u），意思是某方面造诣很深的人。", "大使": "dà shǐ 的韵母（i）和声调（第三声）都与 shū 不同，意思是国家派往外国的外交代表。", "大事": "dà shì 的韵母（i）和声调（第四声）都与 shū 不同，意思是重要的事情。"}, "sentence_index": null, "correct_answer": "大叔"}, "level_3": {"options": [{"text": "大叔", "is_correct": true, "explanation": "正确。“讲故事”的施事应是会说话的人，“大叔”符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“讲故事”要求有说话能力的施事，石头不能做主语。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有生命，不能给孩子们讲故事。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能讲故事，句子语义不通。"}], "explanations": {"大叔": "正确。“讲故事”的施事应是会说话的人，“大叔”符合句意。", "石头": "配价：“讲故事”要求有说话能力的施事，石头不能做主语。", "桌子": "语义：桌子没有生命，不能给孩子们讲故事。", "汽车": "语义：汽车不能讲故事，句子语义不通。"}, "sentence_index": 6, "correct_answer": "大叔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位大叔是我爸爸的哥哥，他每天早上都去打太极。", "explanation": "这里应该用〈大伯〉。大叔指比爸爸年纪小的男性，比爸爸年长的哥哥不能称“大叔”。"}, {"text": "那个十岁的大叔每天都去上学。", "explanation": "这里应该用〈小男孩〉。大叔指成年的、比爸爸年纪小的男性，不能用于十岁的孩子。"}, {"text": "我在会议上对公司董事长说：“大叔，这份报告请您过目。”", "explanation": "这里应该用〈先生〉。大叔是随意亲切的口语称呼，不能用于称呼职位高的领导。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小区里有一只大叔喜欢和孩子们聊天。", "corrected_sentence": "小区里有一位大叔喜欢和孩子们聊天。", "error_description": "“大叔”指人，量词应用“位”。“只”用于动物等，不能用来数人。正确说法是：小区里有一位大叔喜欢和孩子们聊天。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一张大叔每天在公园里教我们跳舞。", "corrected_sentence": "一位大叔每天在公园里教我们跳舞。", "error_description": "“大叔”指人，应用量词“位”或“个”，“张”用于平面的东西，不能用来数人。正确说法是：一位大叔每天在公园里教我们跳舞。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
