INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90556, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对中年男子的称呼。", "primary_collocate": null, "pronunciation": "dà shū", "ipa": "ta˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "一位大叔坐在路边看报纸。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个大叔在店里买了一瓶水。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大叔，您的东西掉了。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车上有个大叔给老人让座。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "穿西装的大叔走进了办公室。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个大叔看起来四十多岁。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卖菜的大叔每天很早就来。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个大叔在街上问路。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位大叔带着孩子去了公园。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大叔们在树下聊天。", "target_word": "大叔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "大叔：称呼不认识的中年男子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3040b130-1c83-4aba-a0d1-f87d0f162c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90556, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大叔", "is_correct": true, "explanation": "正确答案。大叔读作 dà shū，指对不认识的中年男子的称呼。"}, {"text": "大树", "is_correct": false, "explanation": "dà shù（第四声）与 dà shū（第一声）的第二音节声调不同，意思是大树。"}, {"text": "大暑", "is_correct": false, "explanation": "shǔ（第三声）与 shū（第一声）声调不同，意思是二十四节气之一的大暑。"}, {"text": "大数", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，意思是很大的数目。"}, {"text": "大鼠", "is_correct": false, "explanation": "shǔ（第三声）与 shū（第一声）声调不同，意思是大型老鼠。"}], "explanations": {"大叔": "正确答案。大叔读作 dà shū，指对不认识的中年男子的称呼。", "大树": "dà shù（第四声）与 dà shū（第一声）的第二音节声调不同，意思是大树。", "大暑": "shǔ（第三声）与 shū（第一声）声调不同，意思是二十四节气之一的大暑。", "大数": "shù（第四声）与 shū（第一声）声调不同，意思是很大的数目。", "大鼠": "shǔ（第三声）与 shū（第一声）声调不同，意思是大型老鼠。"}, "sentence_index": null, "correct_answer": "大叔"}, "level_3": {"options": [{"text": "大叔", "is_correct": true, "explanation": "正确。“一位”用于指人，“大叔”指中年男子，能够坐在路边看报纸。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“位”只用来数人，不能说“一位小猫”。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像不会坐，也不会看报纸，句子语义不通。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“位”只用来数人，“椅子”不能用“位”来数；而且椅子也不会看报纸。"}], "explanations": {"大叔": "正确。“一位”用于指人，“大叔”指中年男子，能够坐在路边看报纸。", "小猫": "搭配：“位”只用来数人，不能说“一位小猫”。", "雕像": "语义：雕像不会坐，也不会看报纸，句子语义不通。", "椅子": "搭配：“位”只用来数人，“椅子”不能用“位”来数；而且椅子也不会看报纸。"}, "sentence_index": 0, "correct_answer": "大叔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一个十八岁的大叔在门口等我。", "explanation": "这里应该用〈小伙子〉。大叔指中年男子，十八岁的年轻人不能称为“大叔”。"}, {"text": "那位女士很和气，大家都叫她大叔。", "explanation": "这里应该用〈大姐〉。大叔指中年男子，称呼女性不能用“大叔”。"}, {"text": "这位老人家八十多岁了，大家都叫他大叔。", "explanation": "这里应该用〈大爷〉。大叔指中年男子，八十多岁的老人不能称为“大叔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90556, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大叔", "is_correct": true, "explanation": "正确答案。大叔读作 dà shū，指对不认识的中年男子的称呼。"}, {"text": "大师", "is_correct": false, "explanation": "dà shī 与 dà shū 声调相同，只有韵母不同（i 与 u），意思是某方面造诣很深的人。"}, {"text": "大使", "is_correct": false, "explanation": "dà shǐ 的韵母（i）和声调（第三声）都与 shū 不同，意思是国家派往外国的外交代表。"}, {"text": "大事", "is_correct": false, "explanation": "dà shì 的韵母（i）和声调（第四声）都与 shū 不同，意思是重要的事情。"}], "explanations": {"大叔": "正确答案。大叔读作 dà shū，指对不认识的中年男子的称呼。", "大师": "dà shī 与 dà shū 声调相同，只有韵母不同（i 与 u），意思是某方面造诣很深的人。", "大使": "dà shǐ 的韵母（i）和声调（第三声）都与 shū 不同，意思是国家派往外国的外交代表。", "大事": "dà shì 的韵母（i）和声调（第四声）都与 shū 不同，意思是重要的事情。"}, "sentence_index": null, "correct_answer": "大叔"}, "level_3": {"options": [{"text": "大叔", "is_correct": true, "explanation": "正确。“卖菜的”修饰指人的名词，“大叔”符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：“卖菜的”必须修饰人，太阳不卖菜，句子语义不通。"}, {"text": "火车", "is_correct": false, "explanation": "配价：“卖菜的”要求能够卖菜的人，火车不能充当这一角色。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“卖菜”的对象是菜，报纸不能卖菜，“卖菜的报纸”不搭配。"}], "explanations": {"大叔": "正确。“卖菜的”修饰指人的名词，“大叔”符合句意。", "太阳": "语义：“卖菜的”必须修饰人，太阳不卖菜，句子语义不通。", "火车": "配价：“卖菜的”要求能够卖菜的人，火车不能充当这一角色。", "报纸": "搭配：“卖菜”的对象是菜，报纸不能卖菜，“卖菜的报纸”不搭配。"}, "sentence_index": 6, "correct_answer": "大叔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位阿姨在卖水果，我叫她大叔。", "explanation": "这里应该用〈阿姨〉。大叔是称呼中年男子的，不能用来称呼女性。"}, {"text": "这个孩子还在上幼儿园，我叫他大叔。", "explanation": "这里应该用〈小朋友〉。大叔指中年男子，不能用来称呼幼儿园的孩子。"}, {"text": "尊敬的各位嘉宾，请大叔上台致辞。", "explanation": "这里应该用〈先生〉。大叔是随意亲切的口语称呼，不能用于正式场合的致辞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站门口有一条大叔在卖报纸。", "corrected_sentence": "车站门口有一位大叔在卖报纸。", "error_description": "“大叔”指人，量词应用“位”或“个”；“条”用于细长的物品，不能用来数人。正确说法是：车站门口有一位大叔在卖报纸。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "菜市场里有一座大叔在卖西瓜。", "corrected_sentence": "菜市场里有一个大叔在卖西瓜。", "error_description": "“大叔”指人，应用量词“个”或“位”；“座”用于山、楼房等大型物体，不能用来数人。正确说法是：菜市场里有一个大叔在卖西瓜。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
