INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90559, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "教堂是信教的人去的大房子，他们在里面唱歌，说心里话。", "primary_collocate": null, "pronunciation": "jiào táng", "ipa": "tɕjaʊ˥˩ tʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "城里有一座很大的教堂。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期天，他们去教堂唱歌。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教堂里很安静。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在教堂里说出了心里话。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座教堂又高又大。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教堂旁边有一家小商店。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每个星期都去教堂。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在教堂里听人唱歌。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教堂的门开着，我走了进去。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个教堂是新盖的。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "大教堂", "label": "复合"}], "register": "中性", "sense_fingerprint": "信教的人去唱歌、说心里话的大房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b382258-1d1c-4078-8cdf-3ee7f594def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90559, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教堂", "is_correct": true, "explanation": "教堂是大型建筑，量词用“座”，句中“城里”“很大”也都相符。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：量词“座”用于大型建筑，不能用于课本，“一座很大的课本”不成立。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：汽车的量词是“辆”，不说“一座汽车”。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是饮品，不是可以矗立在城里的大型建筑。"}], "explanations": {"教堂": "教堂是大型建筑，量词用“座”，句中“城里”“很大”也都相符。", "课本": "搭配：量词“座”用于大型建筑，不能用于课本，“一座很大的课本”不成立。", "汽车": "搭配：汽车的量词是“辆”，不说“一座汽车”。", "牛奶": "语义：牛奶是饮品，不是可以矗立在城里的大型建筑。"}, "sentence_index": 0, "correct_answer": "教堂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教堂里的僧人每天早上念经。", "explanation": "这里应该用〈寺庙〉。僧人念经是佛教的活动，要说“寺庙”；教堂是基督教徒做礼拜的地方。"}, {"text": "道士每天清晨在教堂里打坐修行。", "explanation": "这里应该用〈道观〉。道士打坐修行的场所是道观，教堂是基督教徒做礼拜的地方，不用于道教活动。"}, {"text": "同学们每天在教堂里上课。", "explanation": "这里应该用〈教室〉。上课要在教室进行，教堂是基督教徒做礼拜的建筑，不用于授课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教堂", "is_correct": true, "explanation": "教堂是可以“去”的地方，与“每个星期都去”搭配。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是地方，“老人每个星期都去作业”说不通。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子不是可以前往的场所，与“去”的对象不符。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“去”后接地点或活动，不能说“去早餐”。"}], "explanations": {"教堂": "教堂是可以“去”的地方，与“每个星期都去”搭配。", "作业": "语义：作业不是地方，“老人每个星期都去作业”说不通。", "鞋子": "语义：鞋子不是可以前往的场所，与“去”的对象不符。", "早餐": "搭配：“去”后接地点或活动，不能说“去早餐”。"}, "sentence_index": 6, "correct_answer": "教堂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "穆斯林每个星期五都去教堂礼拜。", "explanation": "这里应该用〈清真寺〉。穆斯林礼拜的场所是清真寺，教堂是基督教徒的礼拜场所。"}, {"text": "村里的人每年春节都去教堂祭祖。", "explanation": "这里应该用〈祠堂〉。祭祖要去祠堂，教堂是基督教徒做礼拜的地方。"}, {"text": "学校的运动会在教堂里举行。", "explanation": "这里应该用〈操场〉。运动会要在操场或体育场举行，教堂是信徒做礼拜的场所，不用于体育活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们今天参观了一只古老的教堂。", "corrected_sentence": "我们今天参观了一座古老的教堂。", "error_description": "“一只古老的教堂”错误，应说“一座古老的教堂”。教堂是大型建筑，量词用“座”；“只”多用于动物或成对器物中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90559, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每个星期六都教堂唱歌。", "corrected_sentence": "我们每个星期六都在教堂唱歌。", "error_description": "表示地点的“在教堂”少了介词“在”，应说“在教堂唱歌”，不能说“教堂唱歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
