INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90560, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "基督教徒举行宗教仪式的建筑物。", "primary_collocate": null, "pronunciation": "jiào táng", "ipa": "tɕjaʊ˥˩ tʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "基督教徒在教堂里做礼拜。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教堂里正在举行婚礼。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座教堂有三百年的历史。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教堂的屋顶上有一个十字架。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神父在教堂里为大家祈祷。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圣诞节那天，很多人去教堂。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教堂的钟声每天早上响起。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在教堂结婚。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座教堂是用石头盖的。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教堂里有人在读圣经。", "target_word": "教堂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "大教堂", "label": "复合"}], "register": "中性", "sense_fingerprint": "基督教徒举行宗教仪式的建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b382258-1d1c-4078-8cdf-3ee7f594def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教堂", "is_correct": true, "explanation": "教堂是基督教徒做礼拜的场所，与“基督教徒”“做礼拜”搭配。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：做礼拜是宗教活动，不在厨房进行，与“基督教徒”也不相关。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：游泳池是游泳的场所，与“做礼拜”无关。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆是吃饭的地方，与“做礼拜”无关。"}], "explanations": {"教堂": "教堂是基督教徒做礼拜的场所，与“基督教徒”“做礼拜”搭配。", "厨房": "语义：做礼拜是宗教活动，不在厨房进行，与“基督教徒”也不相关。", "游泳池": "语义：游泳池是游泳的场所，与“做礼拜”无关。", "饭馆": "语义：饭馆是吃饭的地方，与“做礼拜”无关。"}, "sentence_index": 0, "correct_answer": "教堂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教堂的香火很旺，很多人来烧香。", "explanation": "这里应该用〈寺庙〉。烧香拜佛是寺庙的活动，教堂是基督教徒做礼拜的地方。"}, {"text": "穆斯林每天五次在教堂礼拜。", "explanation": "这里应该用〈清真寺〉。穆斯林每天礼拜五次要去清真寺；教堂是基督教徒的场所。"}, {"text": "学生们每天在教堂里上课。", "explanation": "这里应该用〈教室〉。上课要在教室进行，教堂是基督教徒做礼拜的建筑，不用于授课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教堂", "is_correct": true, "explanation": "教堂能发出钟声，“教堂的钟声每天早上响起”合乎句意。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不会发出钟声，“电脑的钟声”与句意不符。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：汽车发出的是喇叭声，不说“汽车的钟声”。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会响起钟声，与“响起”不符。"}], "explanations": {"教堂": "教堂能发出钟声，“教堂的钟声每天早上响起”合乎句意。", "电脑": "语义：电脑不会发出钟声，“电脑的钟声”与句意不符。", "汽车": "搭配：汽车发出的是喇叭声，不说“汽车的钟声”。", "椅子": "语义：椅子不会响起钟声，与“响起”不符。"}, "sentence_index": 6, "correct_answer": "教堂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每年清明，家人都到教堂祭拜祖先。", "explanation": "这里应该用〈祠堂〉。祭拜祖先要去祠堂，教堂是基督教徒的礼拜场所。"}, {"text": "学校的体育课每天都在教堂里上。", "explanation": "这里应该用〈操场〉。体育课要在操场或体育馆进行，教堂是信徒做礼拜的场所，不用于体育活动。"}, {"text": "道士在教堂里念经。", "explanation": "这里应该用〈道观〉。道士念经的场所是道观，教堂是基督教的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在一只教堂里结婚。", "corrected_sentence": "他们在一座教堂里结婚。", "error_description": "“一只教堂”错误，应说“一座教堂”。教堂是大型建筑，量词要用“座”，“只”用于动物或成对器物中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每个星期天都教堂做礼拜。", "corrected_sentence": "他们每个星期天都在教堂做礼拜。", "error_description": "“都教堂做礼拜”错误，应说“都在教堂做礼拜”。表示动作发生的地点要用介词“在”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1b5b181-31e3-4972-a94a-997b685b7f39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
