INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90561, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大管是一种木头做的、声音很低的乐器。", "primary_collocate": null, "pronunciation": "dà guǎn", "ipa": "ta˥˩ kwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "大管是用木头做的乐器。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学大管，可是不知道去哪儿买。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首曲子里，大管的声音最低。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在管弦乐队吹大管。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大管吹得好的人不太多。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐厅里放着一支大管。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用大管吹了一首很慢的歌。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听，大管正吹着一首慢歌。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我怎么拿大管。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大管比小号的声音低很多。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}], "register": "中性", "sense_fingerprint": "木头做的、声音很低的乐器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36662012-8007-41fe-a78e-aaa6e4d441d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90561, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大管", "is_correct": true, "explanation": "正确。大管（dà guǎn）是用木头做的、声音很低的乐器。"}, {"text": "大观", "is_correct": false, "explanation": "guān（第一声）与 guǎn（第三声）只差声调，大观指壮观的景象。"}, {"text": "大罐", "is_correct": false, "explanation": "guàn（第四声）与 guǎn（第三声）只差声调，大罐指大型的罐子。"}, {"text": "大款", "is_correct": false, "explanation": "kuǎn 与 guǎn 只差声母（k 与 g），大款指有钱人。"}, {"text": "代管", "is_correct": false, "explanation": "dài（第四声）与 dà 读音相近，代管指代为管理，并非乐器。"}], "explanations": {"大管": "正确。大管（dà guǎn）是用木头做的、声音很低的乐器。", "大观": "guān（第一声）与 guǎn（第三声）只差声调，大观指壮观的景象。", "大罐": "guàn（第四声）与 guǎn（第三声）只差声调，大罐指大型的罐子。", "大款": "kuǎn 与 guǎn 只差声母（k 与 g），大款指有钱人。", "代管": "dài（第四声）与 dà 读音相近，代管指代为管理，并非乐器。"}, "sentence_index": null, "correct_answer": "大管"}, "level_3": {"options": [{"text": "大管", "is_correct": true, "explanation": "正确。大管是用木头做的乐器。"}, {"text": "小号", "is_correct": false, "explanation": "语义：小号是用金属做的铜管乐器，不是用木头做的。"}, {"text": "三角铁", "is_correct": false, "explanation": "语义：三角铁是金属打击乐器，不是用木头做的。"}, {"text": "锣", "is_correct": false, "explanation": "搭配：“用木头做的”一般不与“锣”搭配，锣多由金属制成。"}], "explanations": {"大管": "正确。大管是用木头做的乐器。", "小号": "语义：小号是用金属做的铜管乐器，不是用木头做的。", "三角铁": "语义：三角铁是金属打击乐器，不是用木头做的。", "锣": "搭配：“用木头做的”一般不与“锣”搭配，锣多由金属制成。"}, "sentence_index": 0, "correct_answer": "大管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我哥哥想买一本大管。", "explanation": "这里应该用〈支〉。“本”用于书册，大管是吹奏乐器，要用“支”。"}, {"text": "音乐厅里放着一座大管。", "explanation": "这里应该用〈支〉。“座”用于大型固定物，大管要用“支”。"}, {"text": "他家买了一台大管。", "explanation": "这里应该用〈支〉。“台”用于钢琴、机器等，大管是吹奏乐器，要用“支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90561, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大管", "is_correct": true, "explanation": "正确。大管是乐器，可以用“吹”来演奏。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：钢琴用“弹”，不用“吹”。"}, {"text": "指挥", "is_correct": false, "explanation": "语义：指挥是人，不是乐器，不能用来吹奏。"}, {"text": "小提琴", "is_correct": false, "explanation": "搭配：小提琴用“拉”，不用“吹”。"}], "explanations": {"大管": "正确。大管是乐器，可以用“吹”来演奏。", "钢琴": "搭配：钢琴用“弹”，不用“吹”。", "指挥": "语义：指挥是人，不是乐器，不能用来吹奏。", "小提琴": "搭配：小提琴用“拉”，不用“吹”。"}, "sentence_index": 6, "correct_answer": "大管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师递给我一粒大管。", "explanation": "这里应该用〈支〉。“粒”用于颗粒状的小东西，大管要用“支”。"}, {"text": "他每天背着一颗大管上学。", "explanation": "这里应该用〈支〉。“颗”用于小而圆的东西，大管要用“支”。"}, {"text": "妈妈的抽屉里有一张大管。", "explanation": "这里应该用〈支〉。“张”用于平面物，大管要用“支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90561, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的邻居有一本大管。", "corrected_sentence": "我的邻居有一支大管。", "error_description": "“大管”是吹奏乐器，量词应用“支”，“本”用于书册。应改为“一支大管”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90561, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把那块大管放进了琴盒。", "corrected_sentence": "她把那支大管放进了琴盒。", "error_description": "“大管”是吹奏乐器，量词应用“支”，“块”用于块状物。应改为“那支大管”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
