INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90562, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管乐器，木管乐器中音最低的一种，即巴松。", "primary_collocate": null, "pronunciation": "dà guǎn", "ipa": "ta˥˩ kwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "大管是木管乐器里声音最低的一种。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在乐队里吹大管。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支大管的声音又低又沉。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小学习大管，现在是音乐老师。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大管和长笛一起演奏了这首曲子。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐队里有两个人吹大管。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在音乐会上听到了大管的声音。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他背着一支大管走进了学校。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大管的声音很低，听起来很温暖。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让他把大管放在椅子旁边。", "target_word": "大管", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}], "register": "中性", "sense_fingerprint": "木管乐器中音最低的管乐器，即巴松", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36662012-8007-41fe-a78e-aaa6e4d441d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90562, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大管", "is_correct": true, "explanation": "正确。大管（dà guǎn）指木管乐器中音最低的管乐器，即巴松。"}, {"text": "大官", "is_correct": false, "explanation": "dà guān（第一声）与 dà guǎn（第三声）只差第二个音节的声调，大官意为地位高的官员。"}, {"text": "大罐", "is_correct": false, "explanation": "guàn（第四声）与 guǎn（第三声）只差声调，大罐指大型的罐子。"}, {"text": "大款", "is_correct": false, "explanation": "kuǎn 与 guǎn 只差声母（k 与 g），大款指有钱人。"}, {"text": "代管", "is_correct": false, "explanation": "dài 与 dà 只差韵母（ai 与 a），代管指代为管理，并非乐器。"}], "explanations": {"大管": "正确。大管（dà guǎn）指木管乐器中音最低的管乐器，即巴松。", "大官": "dà guān（第一声）与 dà guǎn（第三声）只差第二个音节的声调，大官意为地位高的官员。", "大罐": "guàn（第四声）与 guǎn（第三声）只差声调，大罐指大型的罐子。", "大款": "kuǎn 与 guǎn 只差声母（k 与 g），大款指有钱人。", "代管": "dài 与 dà 只差韵母（ai 与 a），代管指代为管理，并非乐器。"}, "sentence_index": null, "correct_answer": "大管"}, "level_3": {"options": [{"text": "大管", "is_correct": true, "explanation": "正确。大管是木管乐器，且是其中声音最低的一种。"}, {"text": "小号", "is_correct": false, "explanation": "语义：小号属于铜管乐器，不是木管乐器。"}, {"text": "长笛", "is_correct": false, "explanation": "语义：长笛是木管乐器，但音域偏高，不是最低的一种。"}, {"text": "低音提琴", "is_correct": false, "explanation": "搭配：低音提琴是弦乐器，不能说成“木管乐器里”的一种。"}], "explanations": {"大管": "正确。大管是木管乐器，且是其中声音最低的一种。", "小号": "语义：小号属于铜管乐器，不是木管乐器。", "长笛": "语义：长笛是木管乐器，但音域偏高，不是最低的一种。", "低音提琴": "搭配：低音提琴是弦乐器，不能说成“木管乐器里”的一种。"}, "sentence_index": 0, "correct_answer": "大管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一只大管，放在家里。", "explanation": "这里应该用〈支〉。大管是吹奏乐器，量词用“支”；“只”多用于动物。"}, {"text": "我们学校有一辆大管。", "explanation": "这里应该用〈支〉。“辆”用于车辆，大管要用“支”。"}, {"text": "妈妈给我买了一座大管。", "explanation": "这里应该用〈支〉。“座”用于山、桥等大型固定物，大管要用“支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大管", "is_correct": true, "explanation": "正确。“听到了……的声音”中可以填大管，指这种乐器发出的声音。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位是座椅，不会发出声音，不能说“座位的声音”。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是印刷品，不发出声音，不能说“乐谱的声音”。"}, {"text": "掌声", "is_correct": false, "explanation": "搭配：“掌声”本身就是声音，后面不能再加“的声音”。"}], "explanations": {"大管": "正确。“听到了……的声音”中可以填大管，指这种乐器发出的声音。", "座位": "语义：座位是座椅，不会发出声音，不能说“座位的声音”。", "乐谱": "语义：乐谱是印刷品，不发出声音，不能说“乐谱的声音”。", "掌声": "搭配：“掌声”本身就是声音，后面不能再加“的声音”。"}, "sentence_index": 6, "correct_answer": "大管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师递给我一粒大管。", "explanation": "这里应该用〈支〉。“粒”用于颗粒状的小东西，大管要用“支”。"}, {"text": "他每天背着一颗大管上学。", "explanation": "这里应该用〈支〉。“颗”用于小而圆的东西，大管要用“支”。"}, {"text": "这块大管很重。", "explanation": "这里应该用〈支〉。“块”用于块状物，吹奏乐器要用“支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹想买一只大管，所以去了乐器店。", "corrected_sentence": "妹妹想买一支大管，所以去了乐器店。", "error_description": "“大管”是吹奏乐器，量词应用“支”，“只”多用于动物。应改为“一支大管”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他带了一块大管去学校。", "corrected_sentence": "他带了一支大管去学校。", "error_description": "“大管”是吹奏乐器，量词应用“支”，“块”用于块状物。应改为“一支大管”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
