INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90563, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "歌曲是可以唱出来的好听的歌。", "primary_collocate": null, "pronunciation": "gē qǔ", "ipa": "kɤ˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "这首歌曲非常好听。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢听中文歌曲。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会唱很多英文歌曲。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上下载了几首歌曲。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些歌曲都是我朋友唱的。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们唱一首中国歌曲。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的歌曲是这一首。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的时候，我常常听歌曲。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌曲的名字叫什么？", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们正在学唱新歌曲。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "首", "label": "量词"}, {"form": "流行歌曲", "label": "复合"}], "register": "中性", "sense_fingerprint": "人们平时喜欢听、喜欢唱的好听的歌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53db9dd3-8e45-4d0b-b8b6-d4711d195280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90563, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌曲", "is_correct": true, "explanation": "歌曲：可以唱、可以听的歌，与“好听”相符，符合句意。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：量词“首”用于歌曲、诗词，不能用于乐器。"}, {"text": "照片", "is_correct": false, "explanation": "语义：照片是看的，不能“好听”，应说“好看”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能“好听”，也不能用“首”计量。"}], "explanations": {"歌曲": "歌曲：可以唱、可以听的歌，与“好听”相符，符合句意。", "乐器": "搭配：量词“首”用于歌曲、诗词，不能用于乐器。", "照片": "语义：照片是看的，不能“好听”，应说“好看”。", "房子": "语义：房子不能“好听”，也不能用“首”计量。"}, "sentence_index": 0, "correct_answer": "歌曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很喜欢喝歌曲。", "explanation": "这里应该用〈听〉。歌曲是用来听、唱的，“喝”的对象应是饮品，不能用于歌曲。"}, {"text": "他在网上下载了几幅歌曲。", "explanation": "这里应该用〈首〉。歌曲用“首”计量，“幅”用于画、照片等平面作品。"}, {"text": "我们班唱了几把歌曲。", "explanation": "这里应该用〈首〉。“把”用于有柄或有把手的器具，歌曲要用“首”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90563, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌曲", "is_correct": true, "explanation": "歌曲：人们喜欢听的歌，与“最喜欢的”相符，符合句意。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：量词“首”不用于电影，应说“这一部”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色没有“首”这个量词，不能说“这一首”。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：朋友是人，不能是“这一首”。"}], "explanations": {"歌曲": "歌曲：人们喜欢听的歌，与“最喜欢的”相符，符合句意。", "电影": "搭配：量词“首”不用于电影，应说“这一部”。", "颜色": "搭配：颜色没有“首”这个量词，不能说“这一首”。", "朋友": "语义：朋友是人，不能是“这一首”。"}, "sentence_index": 6, "correct_answer": "歌曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们正在学唱一座新歌曲。", "explanation": "这里应该用〈首〉。“座”用于山、桥、房屋等大型物体，歌曲要用“首”。"}, {"text": "孩子们正在学唱一位新歌曲。", "explanation": "这里应该用〈首〉。“位”用于人，歌曲不能用“位”计量。"}, {"text": "孩子们正在学唱一只新歌曲。", "explanation": "这里应该用〈首〉。“只”多用于动物或成对物品中的一个，歌曲要用“首”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈昨天教我唱一篇新歌曲。", "corrected_sentence": "妈妈昨天教我唱一首新歌曲。", "error_description": "量词错误：歌曲的量词是“首”，“篇”用于文章，应说“一首新歌曲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90563, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们昨天学会了一幅新歌曲。", "corrected_sentence": "孩子们昨天学会了一首新歌曲。", "error_description": "量词错误：歌曲的量词是“首”，“幅”用于画等平面作品，应说“一首新歌曲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
