INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90564, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "配有曲调、可供演唱的作品。", "primary_collocate": null, "pronunciation": "gē qǔ", "ipa": "kɤ˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "他创作了很多优美的歌曲。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作曲家写过一百多首歌曲。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上，演员们演唱了几首经典歌曲。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张专辑里有十二首歌曲。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌曲由他作词、作曲。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中，她选择了一首传统歌曲。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌曲的旋律让人一听就记住了。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把这首歌曲翻译成了英文。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些歌曲在年轻人中很受欢迎。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会上唱的歌曲，我大部分都听过。", "target_word": "歌曲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "首", "label": "量词"}, {"form": "流行歌曲", "label": "复合"}], "register": "书面", "sense_fingerprint": "由人创作的、有歌词和曲调的音乐作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53db9dd3-8e45-4d0b-b8b6-d4711d195280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌曲", "is_correct": true, "explanation": "歌曲：由人创作的音乐作品，“创作”与“优美”相符，符合句意。"}, {"text": "食物", "is_correct": false, "explanation": "搭配：“创作”的对象是作品，不能创作食物。"}, {"text": "植物", "is_correct": false, "explanation": "搭配：植物是生长出来的，不能说“创作”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人能创作的作品。"}], "explanations": {"歌曲": "歌曲：由人创作的音乐作品，“创作”与“优美”相符，符合句意。", "食物": "搭配：“创作”的对象是作品，不能创作食物。", "植物": "搭配：植物是生长出来的，不能说“创作”。", "天气": "语义：天气不是人能创作的作品。"}, "sentence_index": 0, "correct_answer": "歌曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌曲很押韵，适合在晚会上朗诵。", "explanation": "这里应该用〈诗〉。歌曲是配有曲调、可供演唱的作品，不能用“朗诵”，朗诵的对象是诗文。"}, {"text": "她写了一篇新歌曲。", "explanation": "这里应该用〈首〉。“篇”用于文章，歌曲用“首”计量。"}, {"text": "这张专辑里有十二位歌曲。", "explanation": "这里应该用〈首〉。“位”用于人，歌曲不能用“位”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌曲", "is_correct": true, "explanation": "歌曲：有旋律的音乐作品，“这首歌曲的旋律”说得通，符合句意。"}, {"text": "建筑", "is_correct": false, "explanation": "语义：建筑没有旋律，不能让人“一听就记住”。"}, {"text": "香水", "is_correct": false, "explanation": "语义：香水是用来闻的，没有旋律。"}, {"text": "菜", "is_correct": false, "explanation": "搭配：量词“首”不用于菜，不能说“这首菜”。"}], "explanations": {"歌曲": "歌曲：有旋律的音乐作品，“这首歌曲的旋律”说得通，符合句意。", "建筑": "语义：建筑没有旋律，不能让人“一听就记住”。", "香水": "语义：香水是用来闻的，没有旋律。", "菜": "搭配：量词“首”不用于菜，不能说“这首菜”。"}, "sentence_index": 6, "correct_answer": "歌曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "音乐会上唱了几座歌曲，我大部分都听过。", "explanation": "这里应该用〈首〉。“座”用于山、桥、建筑等，歌曲要用“首”。"}, {"text": "音乐会上唱了几只歌曲，我大部分都听过。", "explanation": "这里应该用〈首〉。“只”多用于动物，歌曲不用“只”计量。"}, {"text": "音乐会上唱了几片歌曲，我大部分都听过。", "explanation": "这里应该用〈首〉。“片”用于叶子、云彩等成片的东西，歌曲要用“首”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位作曲家去年发表了一幅新歌曲。", "corrected_sentence": "这位作曲家去年发表了一首新歌曲。", "error_description": "量词错误：作为作品的歌曲用“首”计量，“幅”用于画作，应说“一首新歌曲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位作曲家写过首这歌曲。", "corrected_sentence": "这位作曲家写过这首歌曲。", "error_description": "语序错误：指示代词“这”须位于量词“首”之前，应说“这首歌曲”，不能说“首这歌曲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
