INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90565, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经过比赛或努力而得到（冠军、奖牌等）。", "primary_collocate": null, "pronunciation": "duó dé", "ipa": "twɔ˧˥ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "中国队夺得了这次比赛的冠军。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他夺得了第一名。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李在比赛中夺得金牌。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班夺得了跑步比赛的第一名。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她努力学习，夺得了奖学金。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过三年的努力，他夺得了冠军。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队第一次夺得世界杯。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他夺得过两次游泳冠军。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁夺得了今天比赛的第一名？", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在画画比赛中夺得了一等奖。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夺得了", "label": "完成体"}, {"form": "夺得过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "经过比赛或努力而得到（冠军、奖牌等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36662012-8007-41fe-a78e-aaa6e4d441d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90565, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夺得", "is_correct": true, "explanation": "正确。夺得表示经过比赛而得到，可以与“冠军”搭配。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：修建用于建筑、道路，不能说“修建冠军”。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：踢是用脚做的动作，“冠军”不能被踢。"}, {"text": "发明", "is_correct": false, "explanation": "语义：发明是创造新事物，与“比赛的冠军”的获得无关。"}], "explanations": {"夺得": "正确。夺得表示经过比赛而得到，可以与“冠军”搭配。", "修建": "搭配：修建用于建筑、道路，不能说“修建冠军”。", "踢": "搭配：踢是用脚做的动作，“冠军”不能被踢。", "发明": "语义：发明是创造新事物，与“比赛的冠军”的获得无关。"}, "sentence_index": 0, "correct_answer": "夺得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈生日那天，我夺得了一份礼物。", "explanation": "这里应该用〈收到〉。夺得含有争夺、比赛的意思，生日礼物是别人送的，不需要争夺，应用“收到”。"}, {"text": "他的努力夺得了大家的尊重。", "explanation": "这里应该用〈赢得〉。夺得多用于冠军、奖牌等具体的胜利物，抽象的尊重要用“赢得”。"}, {"text": "这次考试我夺得了很大的进步。", "explanation": "这里应该用〈取得〉。进步不是争来的，夺得含有争夺之意，应用“取得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90565, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夺得", "is_correct": true, "explanation": "正确。夺得表示经过比赛而得到世界杯，与前文的“第一次”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：世界杯是奖杯，不能说“吃世界杯”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”用于歌曲，不能说“唱世界杯”。"}, {"text": "缝补", "is_correct": false, "explanation": "语义：奖杯不需要缝补，与“第一次”获得奖杯的语境不符。"}], "explanations": {"夺得": "正确。夺得表示经过比赛而得到世界杯，与前文的“第一次”相符。", "吃": "搭配：世界杯是奖杯，不能说“吃世界杯”。", "唱": "搭配：“唱”用于歌曲，不能说“唱世界杯”。", "缝补": "语义：奖杯不需要缝补，与“第一次”获得奖杯的语境不符。"}, "sentence_index": 6, "correct_answer": "夺得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天按时交作业，终于夺得了老师的表扬。", "explanation": "这里应该用〈获得〉。夺得含有争夺之意，按时交作业得到表扬不需要争夺，应用“获得”。"}, {"text": "他在网上夺得了这条新闻。", "explanation": "这里应该用〈获取〉。夺得指经过比赛或争夺而得到，获取信息不含争夺之意，应用“获取”。"}, {"text": "我夺得了很多快乐。", "explanation": "这里应该用〈收获〉。快乐和成果是收获来的，夺得含有争夺之意，应用“收获”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们班夺得到了一枚金牌。", "corrected_sentence": "他们班夺得了一枚金牌。", "error_description": "“夺得”已是完整的词，后面不能再接“到”，“夺得到”是重复的得到之意，应为“夺得了”。错误在于在“夺得”后多加了“到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在比赛中夺得了着一面锦旗。", "corrected_sentence": "她在比赛中夺得了一面锦旗。", "error_description": "「夺得」后的「了」表示完成，「着」表示持续，二者不能连用，「了着」不成立。应删去「着」，改为「她在比赛中夺得了一面锦旗。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
