INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90566, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经过争夺而得到。", "primary_collocate": null, "pronunciation": "duó dé", "ipa": "twɔ˧˥ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "两个队争了很久，最后红队夺得了球。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一场大战，他们夺得了这座城。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两支军队都想夺得这块土地。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一阵争抢，他夺得了那个篮球。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后，他们夺得了山上的阵地。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人夺得过这座城两次。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队夺得了最后一分。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子抢玩具，最后哥哥夺得了它。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁能夺得这口井，谁就有水喝。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们夺得了敌人的大炮，高兴极了。", "target_word": "夺得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夺得了", "label": "完成体"}, {"form": "夺得过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "经过争夺而得到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36662012-8007-41fe-a78e-aaa6e4d441d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夺得", "is_correct": true, "explanation": "正确。夺得与前文“争了很久”相呼应，表示经过争夺而得到。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理用于机器、物品，不能说“修理比赛中的球”。"}, {"text": "制造", "is_correct": false, "explanation": "语义：制造是做出新东西，与“争了很久”的争夺情节不符。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁是毁坏，与“争了很久，最后……”的争夺结果不符。"}], "explanations": {"夺得": "正确。夺得与前文“争了很久”相呼应，表示经过争夺而得到。", "修理": "搭配：修理用于机器、物品，不能说“修理比赛中的球”。", "制造": "语义：制造是做出新东西，与“争了很久”的争夺情节不符。", "烧毁": "语义：烧毁是毁坏，与“争了很久，最后……”的争夺结果不符。"}, "sentence_index": 0, "correct_answer": "夺得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的努力夺得了大家的信任。", "explanation": "这里应该用〈赢得〉。夺得含有争夺之意，信任是慢慢赢得的，应用“赢得”。"}, {"text": "他夺得了很多知识。", "explanation": "这里应该用〈获取〉。夺得多用于争来的胜利物，知识要用“获取”。"}, {"text": "他夺得了这次考试的成功。", "explanation": "这里应该用〈取得〉。成功要用“取得”，夺得多用于具体的胜利物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夺得", "is_correct": true, "explanation": "正确。夺得与“最后一分”搭配，表示经过争夺而得到。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”用于歌曲，不能说“唱最后一分”。"}, {"text": "撕掉", "is_correct": false, "explanation": "语义：撕掉是毁坏，与争得分数的意思不符。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：分数不能缝补，“缝补最后一分”不成立。"}], "explanations": {"夺得": "正确。夺得与“最后一分”搭配，表示经过争夺而得到。", "唱": "搭配：“唱”用于歌曲，不能说“唱最后一分”。", "撕掉": "语义：撕掉是毁坏，与争得分数的意思不符。", "缝补": "搭配：分数不能缝补，“缝补最后一分”不成立。"}, "sentence_index": 6, "correct_answer": "夺得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她夺得了一封信。", "explanation": "这里应该用〈收到〉。夺得含有争夺之意，寄来的信不需要争夺，应用“收到”。"}, {"text": "他的热心夺得了大家的支持。", "explanation": "这里应该用〈获得〉。支持是获得的，夺得含有争夺之意，应用“获得”。"}, {"text": "这些年他夺得了很多快乐。", "explanation": "这里应该用〈收获〉。快乐是收获来的，夺得多用于争来的胜利物，应用“收获”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "红军夺得到了一座城。", "corrected_sentence": "红军夺得了一座城。", "error_description": "“夺得”已是完整的词，后面不能再接“到”，“夺得到”是重复的得到之意，应为“夺得了”。错误在于在“夺得”后多加了“到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支军队夺得了过两座城。", "corrected_sentence": "这支军队夺得过两座城。", "error_description": "“夺得”后的“过”表示经历，不能再加“了”。应改为“夺得过两座城”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223b71ff-cdef-4f6b-abb8-ba2071b71cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
