INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90569, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "营是很多人住在一起的地方，比如帐篷搭成的小村子。", "primary_collocate": null, "pronunciation": "yíng", "ipa": "iŋ˧˥", "syllable_count": 1, "sentences": [{"text": "山下的营里住着很多人。", "target_word": "营", "complexity_tier": "T3", "furigana": "shān xià de yíng lǐ zhù zhe hěn duō rén", "sentence_source": "generated"}, {"text": "我们的营在河边，很安静。", "target_word": "营", "complexity_tier": "T3", "furigana": "wǒ men de yíng zài hé biān, hěn ān jìng", "sentence_source": "generated"}, {"text": "天黑了，大家都回到了营里。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "营里有很多帐篷。", "target_word": "营", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在营里玩游戏。", "target_word": "营", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜里营里很安静，只听见风声。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个营不大，只住了二十个人。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在湖边的营里住了三天。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "营中的人每天早上一起做饭。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，营里的路变得很难走。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "营地", "label": "复合"}, {"form": "个", "label": "量词"}, {"form": "營", "label": "繁体"}], "register": "中性", "sense_fingerprint": "营：很多人住在一起的帐篷营地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4d7aeb-bdb3-4b50-b630-bfe4d39c60e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90569, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "营", "is_correct": true, "explanation": "营（yíng，第二声）：很多人住在一起的地方，如帐篷营地。"}, {"text": "影", "is_correct": false, "explanation": "影（yǐng，第三声）与营（yíng，第二声）声调不同，意思是影子。"}, {"text": "硬", "is_correct": false, "explanation": "硬（yìng，第四声）与营声调不同，意思是坚硬。"}, {"text": "应", "is_correct": false, "explanation": "应（yīng，第一声）与营声调不同，意思是应该或应答。"}, {"text": "银", "is_correct": false, "explanation": "银（yín）与营声调相同，韵尾不同（n 与 ng），意思是银子。"}, {"text": "英", "is_correct": false, "explanation": "英（yīng，第一声）与营声调不同，意思是英勇。"}], "explanations": {"营": "营（yíng，第二声）：很多人住在一起的地方，如帐篷营地。", "影": "影（yǐng，第三声）与营（yíng，第二声）声调不同，意思是影子。", "硬": "硬（yìng，第四声）与营声调不同，意思是坚硬。", "应": "应（yīng，第一声）与营声调不同，意思是应该或应答。", "银": "银（yín）与营声调相同，韵尾不同（n 与 ng），意思是银子。", "英": "英（yīng，第一声）与营声调不同，意思是英勇。"}, "sentence_index": null, "correct_answer": "营"}, "level_3": {"options": [{"text": "营", "is_correct": true, "explanation": "正确：营指很多人住在一起的营地，与“住着很多人”相符。"}, {"text": "水", "is_correct": false, "explanation": "语义：水里不能住很多人，与“住着很多人”冲突。"}, {"text": "草", "is_correct": false, "explanation": "语义：草丛不是能住很多人的地方，与“住着很多人”冲突。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是能住人的地方，与“住着很多人”冲突。"}], "explanations": {"营": "正确：营指很多人住在一起的营地，与“住着很多人”相符。", "水": "语义：水里不能住很多人，与“住着很多人”冲突。", "草": "语义：草丛不是能住很多人的地方，与“住着很多人”冲突。", "雨": "语义：雨不是能住人的地方，与“住着很多人”冲突。"}, "sentence_index": 0, "correct_answer": "营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家小店每天营到晚上十点。", "explanation": "这里的“营”指营业、做生意，与“很多人住在一起的地方”不同，应说“营业”。"}, {"text": "他营了一个小摊子，每天卖菜。", "explanation": "这里的“营”指经营、做买卖，与“很多人住在一起的地方”不同，应说“经营”。"}, {"text": "营放学了，孩子们回家了。", "explanation": "这里应该用〈学校〉。放学是学校的事，营地不会放学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90569, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "营", "is_correct": true, "explanation": "营（yíng，第二声）：很多人住在一起的地方，如帐篷营地。"}, {"text": "灵", "is_correct": false, "explanation": "灵（líng）与营声母不同（l 与 y），声调相同，意思是灵活。"}, {"text": "映", "is_correct": false, "explanation": "映（yìng，第四声）与营声调不同，意思是照射。"}, {"text": "印", "is_correct": false, "explanation": "印（yìn）与营韵尾不同（n 与 ng），声调也不同，意思是印章。"}, {"text": "因", "is_correct": false, "explanation": "因（yīn）与营韵尾不同，声调也不同，意思是因为。"}], "explanations": {"营": "营（yíng，第二声）：很多人住在一起的地方，如帐篷营地。", "灵": "灵（líng）与营声母不同（l 与 y），声调相同，意思是灵活。", "映": "映（yìng，第四声）与营声调不同，意思是照射。", "印": "印（yìn）与营韵尾不同（n 与 ng），声调也不同，意思是印章。", "因": "因（yīn）与营韵尾不同，声调也不同，意思是因为。"}, "sentence_index": null, "correct_answer": "营"}, "level_3": {"options": [{"text": "营", "is_correct": true, "explanation": "正确：营是能住二十个人的营地，与“只住了二十个人”相符。"}, {"text": "碗", "is_correct": false, "explanation": "语义：碗是装饭的东西，不能住人，与“只住了二十个人”冲突。"}, {"text": "池", "is_correct": false, "explanation": "语义：水池不能住人，与“只住了二十个人”冲突。"}, {"text": "杯", "is_correct": false, "explanation": "语义：杯子不能住人，与“只住了二十个人”冲突。"}], "explanations": {"营": "正确：营是能住二十个人的营地，与“只住了二十个人”相符。", "碗": "语义：碗是装饭的东西，不能住人，与“只住了二十个人”冲突。", "池": "语义：水池不能住人，与“只住了二十个人”冲突。", "杯": "语义：杯子不能住人，与“只住了二十个人”冲突。"}, "sentence_index": 6, "correct_answer": "营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈昨天去营修了自行车。", "explanation": "这里应该用〈修车铺〉。修自行车要去修车铺，营地不修车。"}, {"text": "我每周去营借书。", "explanation": "这里应该用〈图书馆〉。借书要去图书馆，营地不办借书。"}, {"text": "他昨天去营拔了一颗牙。", "explanation": "这里应该用〈牙医诊所〉。拔牙要去牙医诊所，营地不做牙科治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90569, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖边的一只营里住着一群孩子。", "corrected_sentence": "湖边的一个营里住着一群孩子。", "error_description": "错误形式是“一只营”，正确形式是“一个营”。“营”是地方，量词应用“个”，“只”多用于动物等，不用于营地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90569, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "营山脚下，很安静。", "corrected_sentence": "营在山脚下，很安静。", "error_description": "错误在于漏掉了“在”。表示位置时应说“营在山脚下”，不能说“营山脚下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
