INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90570, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队驻扎的地方。", "primary_collocate": null, "pronunciation": "yíng", "ipa": "iŋ˧˥", "syllable_count": 1, "sentences": [{"text": "士兵们每天早上在营里训练。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "士兵们列队走出了营。", "target_word": "营", "complexity_tier": "T3", "furigana": "shì bīng men liè duì zǒu chū le yíng", "sentence_source": "generated"}, {"text": "战士们昨天晚上回到了营里。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌人离我们的营只有五里路。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "将军走进营，看了看士兵们。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个营里住着五百名战士。", "target_word": "营", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜里，营外很黑，营里却亮着灯。", "target_word": "营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在营里当了三年兵。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天亮以前，部队已经离开了营。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哨兵守在营外，不让陌生人进去。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "军营", "label": "复合"}, {"form": "兵营", "label": "复合"}, {"form": "个", "label": "量词"}, {"form": "營", "label": "繁体"}], "register": "中性", "sense_fingerprint": "营：军队驻扎的营地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4d7aeb-bdb3-4b50-b630-bfe4d39c60e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90570, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "营", "is_correct": true, "explanation": "营（yíng，第二声）：军队驻扎的地方。"}, {"text": "影", "is_correct": false, "explanation": "影（yǐng，第三声）与营（yíng，第二声）声调不同，意思是影子。"}, {"text": "硬", "is_correct": false, "explanation": "硬（yìng，第四声）与营声调不同，意思是坚硬。"}, {"text": "应", "is_correct": false, "explanation": "应（yīng，第一声）与营声调不同，意思是应该或应答。"}, {"text": "银", "is_correct": false, "explanation": "银（yín）与营声调相同，韵尾不同（n 与 ng），意思是银子。"}, {"text": "英", "is_correct": false, "explanation": "英（yīng，第一声）与营声调不同，意思是英勇。"}], "explanations": {"营": "营（yíng，第二声）：军队驻扎的地方。", "影": "影（yǐng，第三声）与营（yíng，第二声）声调不同，意思是影子。", "硬": "硬（yìng，第四声）与营声调不同，意思是坚硬。", "应": "应（yīng，第一声）与营声调不同，意思是应该或应答。", "银": "银（yín）与营声调相同，韵尾不同（n 与 ng），意思是银子。", "英": "英（yīng，第一声）与营声调不同，意思是英勇。"}, "sentence_index": null, "correct_answer": "营"}, "level_3": {"options": [{"text": "营", "is_correct": true, "explanation": "正确：营是军队驻扎的地方，“在营里训练”与句意相符。"}, {"text": "书", "is_correct": false, "explanation": "语义：书里不能进行部队训练，与“训练”冲突。"}, {"text": "店", "is_correct": false, "explanation": "语义：店铺不是士兵每天训练的地方，与“训练”冲突。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“在……里训练”要求场所词，“饭”不能作训练的场所。"}], "explanations": {"营": "正确：营是军队驻扎的地方，“在营里训练”与句意相符。", "书": "语义：书里不能进行部队训练，与“训练”冲突。", "店": "语义：店铺不是士兵每天训练的地方，与“训练”冲突。", "饭": "搭配：“在……里训练”要求场所词，“饭”不能作训练的场所。"}, "sentence_index": 0, "correct_answer": "营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "营下班了，医生们回家了。", "explanation": "这里应该用〈医院〉。下班是医院等单位的说法，军营不会下班。"}, {"text": "我每周去营借书。", "explanation": "这里应该用〈图书馆〉。借书要去图书馆，军营不办借书。"}, {"text": "我去营买了一斤苹果。", "explanation": "这里应该用〈水果店〉。买水果要去水果店，军营不卖水果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90570, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "营", "is_correct": true, "explanation": "营（yíng，第二声）：军队驻扎的地方。"}, {"text": "灵", "is_correct": false, "explanation": "灵（líng）与营声母不同（l 与 y），声调相同，意思是灵活。"}, {"text": "映", "is_correct": false, "explanation": "映（yìng，第四声）与营声调不同，意思是照射。"}, {"text": "印", "is_correct": false, "explanation": "印（yìn）与营韵尾不同（n 与 ng），声调也不同，意思是印章。"}, {"text": "因", "is_correct": false, "explanation": "因（yīn）与营韵尾不同，声调也不同，意思是因为。"}], "explanations": {"营": "营（yíng，第二声）：军队驻扎的地方。", "灵": "灵（líng）与营声母不同（l 与 y），声调相同，意思是灵活。", "映": "映（yìng，第四声）与营声调不同，意思是照射。", "印": "印（yìn）与营韵尾不同（n 与 ng），声调也不同，意思是印章。", "因": "因（yīn）与营韵尾不同，声调也不同，意思是因为。"}, "sentence_index": null, "correct_answer": "营"}, "level_3": {"options": [{"text": "营", "is_correct": true, "explanation": "正确：营是驻扎部队的地方，“营外很黑，营里却亮着灯”前后呼应。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是光源，“灯外很黑”与后面的“亮着灯”矛盾。"}, {"text": "桌", "is_correct": false, "explanation": "语义：桌子不是能形成夜里“外面”和“里面”的地方，句子不通。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不是可以“在外”“在里”的空间，“饭里却亮着灯”说不通。"}], "explanations": {"营": "正确：营是驻扎部队的地方，“营外很黑，营里却亮着灯”前后呼应。", "灯": "语义：灯是光源，“灯外很黑”与后面的“亮着灯”矛盾。", "桌": "语义：桌子不是能形成夜里“外面”和“里面”的地方，句子不通。", "饭": "语义：饭不是可以“在外”“在里”的空间，“饭里却亮着灯”说不通。"}, "sentence_index": 6, "correct_answer": "营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去营取钱。", "explanation": "这里应该用〈银行〉。取钱要去银行，军营不办存取款。"}, {"text": "我把营放在桌子上。", "explanation": "这里应该用〈书〉。营是地方，不能放在桌上，要说“书”这类物品。"}, {"text": "营里结满了苹果。", "explanation": "这里应该用〈果园〉。结满果实是果园或树木的事，营不会结苹果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山脚下有一只营，住着很多士兵。", "corrected_sentence": "山脚下有一个营，住着很多士兵。", "error_description": "错误形式是“一只营”，正确形式是“一个营”。“营”是驻扎的地方，量词用“个”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵们营里休息。", "corrected_sentence": "士兵们在营里休息。", "error_description": "错误在于漏掉了“在”。表示地点时应说“在营里休息”，不能说“营里休息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
