INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90571, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "宣扬是把一个好消息或想法讲给很多人听。", "primary_collocate": null, "pronunciation": "xuān yáng", "ipa": "ɕɥɛn˥ jɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "她到处宣扬朋友考上大学的好消息。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他高兴地向全班宣扬自己的好主意。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明向同学们宣扬骑车上学的好处。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈逢人就宣扬女儿拿了第一名。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总向邻居宣扬这家店的饭菜好吃。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有好办法，就应该多向大家宣扬。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这个好想法宣扬给更多的人。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在朋友圈里宣扬着自己的新计划。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李宣扬过这种学习方法，很多人都用。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在宣扬公司要发奖金的好消息。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宣扬了", "label": "体标"}, {"form": "宣扬着", "label": "体标"}, {"form": "宣扬过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "把好消息或好想法讲给许多人听", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0164a193-a1b9-4b34-a43a-61ec32a530f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90571, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宣扬", "is_correct": true, "explanation": "宣扬：把好消息讲给很多人听，与“到处”和“好消息”相合。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”是不让人知道，与“到处”让大家都知道的意思相反。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象是物品，不能说收藏消息。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”是记不住，与“到处”告诉大家的动作不相合。"}], "explanations": {"宣扬": "宣扬：把好消息讲给很多人听，与“到处”和“好消息”相合。", "隐瞒": "语义：“隐瞒”是不让人知道，与“到处”让大家都知道的意思相反。", "收藏": "搭配：“收藏”的对象是物品，不能说收藏消息。", "忘记": "语义：“忘记”是记不住，与“到处”告诉大家的动作不相合。"}, "sentence_index": 0, "correct_answer": "宣扬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把门宣扬上了，屋里很安静。", "explanation": "这里应该用〈关〉。宣扬是把消息或想法讲给很多人听，不能用于关门这个动作。"}, {"text": "他向我宣扬工作太累。", "explanation": "这里应该用〈抱怨〉。宣扬用于好消息或好想法，向人诉苦要用抱怨。"}, {"text": "学校宣扬明天要考试的事。", "explanation": "这里应该用〈通知〉。宣扬用于好消息或好想法，考试这类让人不快的事务要用通知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90571, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宣扬", "is_correct": true, "explanation": "宣扬：把好想法讲给众人听，与“给更多的人”的意思相合。"}, {"text": "保存", "is_correct": false, "explanation": "语义：“保存”是留着不动，与“给更多的人”传递想法的意思相反。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”是不让人看见，与“给更多的人”的意思相矛盾。"}, {"text": "张贴", "is_correct": false, "explanation": "搭配：“张贴”的对象是告示、海报，不能说张贴想法。"}], "explanations": {"宣扬": "宣扬：把好想法讲给众人听，与“给更多的人”的意思相合。", "保存": "语义：“保存”是留着不动，与“给更多的人”传递想法的意思相反。", "隐藏": "语义：“隐藏”是不让人看见，与“给更多的人”的意思相矛盾。", "张贴": "搭配：“张贴”的对象是告示、海报，不能说张贴想法。"}, "sentence_index": 6, "correct_answer": "宣扬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上宣扬半小时步，身体很好。", "explanation": "这里应该用〈跑〉。宣扬是把好消息或想法讲给大家听，不能表示锻炼的动作。"}, {"text": "我在厨房里宣扬了一锅汤，味道很好。", "explanation": "这里应该用〈煮〉。宣扬是向众人广泛传播好消息或想法，烧汤要用煮。"}, {"text": "我向老师宣扬这道题怎么做。", "explanation": "这里应该用〈请教〉。宣扬用于好消息或好想法，向老师问问题要说请教。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她兴奋地把同学宣扬自己的新想法。", "corrected_sentence": "她兴奋地向同学宣扬自己的新想法。", "error_description": "错误：介词用错。“宣扬”的听众要用“向”引出，不能用“把”。错误形式：把同学宣扬；正确形式：向同学宣扬。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想把这个好消息宣扬身边的朋友。", "corrected_sentence": "我想把这个好消息宣扬给身边的朋友。", "error_description": "错误：漏掉了介词“给”，正确形式是“宣扬给身边的朋友”，表示把消息传递给某人时需要“给”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
