INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90572, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "广泛宣传，使大家知道。", "primary_collocate": null, "pronunciation": "xuān yáng", "ipa": "ɕɥɛn˥ jɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "学校用海报宣扬环保的好处。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师一直宣扬读书的重要性。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想宣扬本地的传统文化。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司通过电视广告宣扬新产品。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者在街上宣扬节约用水。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸大力宣扬了这位英雄的事迹。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目宣扬着健康的生活方式。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把团结友爱的精神宣扬出去。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府正在宣扬新的交通规则。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书宣扬过勤劳节俭的美德。", "target_word": "宣扬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宣扬了", "label": "体标"}, {"form": "宣扬着", "label": "体标"}, {"form": "宣扬过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "广泛宣传某种思想、精神或产品，使大众知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0164a193-a1b9-4b34-a43a-61ec32a530f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90572, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宣扬", "is_correct": true, "explanation": "宣扬：广泛宣传，使大家知道，与“用海报”的宣传方式相合。"}, {"text": "否定", "is_correct": false, "explanation": "语义：“否定”是不承认其价值，与用海报宣扬好处的做法相反。"}, {"text": "印刷", "is_correct": false, "explanation": "搭配：“印刷”的对象是书报等出版物，说印刷好处不通。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”是不让人知道，与用海报向大家宣传的做法相矛盾。"}], "explanations": {"宣扬": "宣扬：广泛宣传，使大家知道，与“用海报”的宣传方式相合。", "否定": "语义：“否定”是不承认其价值，与用海报宣扬好处的做法相反。", "印刷": "搭配：“印刷”的对象是书报等出版物，说印刷好处不通。", "隐瞒": "语义：“隐瞒”是不让人知道，与用海报向大家宣传的做法相矛盾。"}, "sentence_index": 0, "correct_answer": "宣扬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他低头不语，只是默默地宣扬着对家乡的思念。", "explanation": "这里应该用〈怀念〉。宣扬是广泛宣传、让大家知道，默默藏在心里的思念要用怀念。"}, {"text": "他向她宣扬了自己的心意。", "explanation": "这里应该用〈表白〉。宣扬是面向大众的广泛宣传，个人对某人的心意只能说表白，不能拿来宣扬。"}, {"text": "他饿了，就宣扬了一碗米饭。", "explanation": "这里应该用〈吃〉。宣扬是广泛宣传、使大家知道，不能表示吃东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宣扬", "is_correct": true, "explanation": "宣扬：广泛宣传，使大家知道，与“着健康的生活方式”的推广意思相合。"}, {"text": "否认", "is_correct": false, "explanation": "语义：“否认”是不承认，与节目推广健康生活方式的内容相反。"}, {"text": "批判", "is_correct": false, "explanation": "语义：“批判”是否定、指出错误，与褒扬健康生活方式的语境不合。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”是不予重视，与节目宣扬健康生活方式的内容相反。"}], "explanations": {"宣扬": "宣扬：广泛宣传，使大家知道，与“着健康的生活方式”的推广意思相合。", "否认": "语义：“否认”是不承认，与节目推广健康生活方式的内容相反。", "批判": "语义：“批判”是否定、指出错误，与褒扬健康生活方式的语境不合。", "忽视": "语义：“忽视”是不予重视，与节目宣扬健康生活方式的内容相反。"}, "sentence_index": 6, "correct_answer": "宣扬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师宣扬他的作业写得很潦草。", "explanation": "这里应该用〈批评〉。宣扬用于推广好的东西，指出别人的缺点要用批评。"}, {"text": "妈妈宣扬我别忘了带伞。", "explanation": "这里应该用〈提醒〉。宣扬是面向大众的广泛传播，对个人的叮嘱用提醒。"}, {"text": "我向老师宣扬这道题怎么做。", "explanation": "这里应该用〈请教〉。宣扬用于思想、精神或产品的推广，向老师问问题要说请教。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影宣扬得勇敢的精神。", "corrected_sentence": "这部电影宣扬着勇敢的精神。", "error_description": "错误：动态助词“着”误写成了“得”。“宣扬得”后面不能直接接宾语“勇敢的精神”，正确形式是“宣扬着”，表示动作的持续状态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事宣扬很广。", "corrected_sentence": "这件事宣扬得很广。", "error_description": "错误：程度补语前漏掉了“得”，正确形式是“宣扬得很广”，“宣扬”与补语“很广”之间需要“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90573, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90573, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90573, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "穿漂亮的衣服给大家看的人；也指让画家画的人。", "primary_collocate": null, "pronunciation": "mó tè", "ipa": "mu̯ɔ˧˥ tʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "美术课上，老师请了一位模特。", "target_word": "模特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画画的时候，模特一动也不动。", "target_word": "模特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他妈妈年轻时做过模特。", "target_word": "模特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位模特常常上电视。", "target_word": "模特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李是一家服装店的模特。", "target_word": "模特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了画好这张画，他请朋友当模特。", "target_word": "模特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模特们在台上走来走去，展示新衣服。", "target_word": "模特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想不想当一名模特？", "target_word": "模特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女孩长得漂亮，可以去做模特。", "target_word": "模特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的模特今天要拍新照片。", "target_word": "模特", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "模特儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "穿衣服给人看的人，或让画家画的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b68f76f-19ce-4182-879c-f07998280520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90573, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模特", "is_correct": true, "explanation": "正确：「模特」指让画家画的人，与「美术课上」的语境相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：美术课上请厨师，与绘画语境无关。"}, {"text": "司机", "is_correct": false, "explanation": "语义：美术课不会请司机，句子不合情理。"}, {"text": "护士", "is_correct": false, "explanation": "搭配：「请了一位护士」在美术课上没有对应的角色，与语境不搭配。"}], "explanations": {"模特": "正确：「模特」指让画家画的人，与「美术课上」的语境相符。", "厨师": "语义：美术课上请厨师，与绘画语境无关。", "司机": "语义：美术课不会请司机，句子不合情理。", "护士": "搭配：「请了一位护士」在美术课上没有对应的角色，与语境不搭配。"}, "sentence_index": 0, "correct_answer": "模特"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个做法的模特值得推广到别的项目。", "explanation": "这里应该用〈模式〉。模特指人，不指可以推广的做法；可推广的做法要说「模式」。"}, {"text": "这辆汽车的模特是用塑料做的，很漂亮。", "explanation": "这里应该用〈模型〉。按比例做成的小汽车叫「模型」，模特是穿衣服给人看或让人画的人。"}, {"text": "他是我们班的模特，大家都向他学习。", "explanation": "这里应该用〈模范〉。模特不表示值得学习的榜样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90573, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模特", "is_correct": true, "explanation": "正确：「模特」指在台上走来走去展示服装的人，与语境相符。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民不会在台上走来走去展示服装，与语境不符。"}, {"text": "警察", "is_correct": false, "explanation": "语义：警察在台上走来走去，不符合展示服装的场景。"}, {"text": "渔民", "is_correct": false, "explanation": "搭配：「渔民们」与「在台上走来走去」不搭配。"}], "explanations": {"模特": "正确：「模特」指在台上走来走去展示服装的人，与语境相符。", "农民": "语义：农民不会在台上走来走去展示服装，与语境不符。", "警察": "语义：警察在台上走来走去，不符合展示服装的场景。", "渔民": "搭配：「渔民们」与「在台上走来走去」不搭配。"}, "sentence_index": 6, "correct_answer": "模特"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个文件的模特可以直接拿来用，很方便。", "explanation": "这里应该用〈模板〉。模特是指人的名词，不指可以直接套用的格式；可套用的格式要说「模板」。"}, {"text": "工厂按照这块模特生产了一千件衣服。", "explanation": "这里应该用〈样板〉。工厂照着生产的标准样品叫「样板」，模特是穿衣服给人看的人，不能照着它生产。"}, {"text": "她是我们年级的模特，同学们都向她学习。", "explanation": "这里应该用〈榜样〉。模特指走秀或让画家画的人，不表示值得学习的榜样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐年轻时做过模特，做得很好过。", "corrected_sentence": "我姐姐年轻时做过模特，做得很好。", "error_description": "错误：句末多出体标「过」。「做得很好」是状态补语，句末不能再加「过」，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "表弟想当一只模特，每天都练走路。", "corrected_sentence": "表弟想当一名模特，每天都练走路。", "error_description": "错误：量词用错。「模特」指人，应用「名」，写作「一名模特」，不能用「只」（「只」多用于动物或物品）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弯", "is_correct": true, "explanation": "正确：“弯”与“直”在“不弯曲”义上互为反义。"}, {"text": "慢", "is_correct": false, "explanation": "与“直”无反义关系，“慢”说速度快慢。"}, {"text": "宽", "is_correct": false, "explanation": "与“直”无反义关系，“宽”说宽度。"}, {"text": "白", "is_correct": false, "explanation": "与“直”无反义关系，“白”说颜色。"}], "correct_answer": "弯", "explanations": {"弯": "正确：“弯”与“直”在“不弯曲”义上互为反义。", "慢": "与“直”无反义关系，“慢”说速度快慢。", "宽": "与“直”无反义关系，“宽”说宽度。", "白": "与“直”无反义关系，“白”说颜色。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弯", "is_correct": true, "explanation": "正确：“弯”与“直”在“不弯曲”义上互为反义。"}, {"text": "深", "is_correct": false, "explanation": "与“直”无反义关系，“深”说深浅。"}, {"text": "粗", "is_correct": false, "explanation": "与“直”无反义关系，“粗”说粗细。"}, {"text": "短", "is_correct": false, "explanation": "与“直”无反义关系，“短”说长度，与“长”相对。"}], "correct_answer": "弯", "explanations": {"弯": "正确：“弯”与“直”在“不弯曲”义上互为反义。", "深": "与“直”无反义关系，“深”说深浅。", "粗": "与“直”无反义关系，“粗”说粗细。", "短": "与“直”无反义关系，“短”说长度，与“长”相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "直是不弯，一条线从头到尾都是平平的。", "primary_collocate": null, "pronunciation": "zhí", "ipa": "ʈʂʅ˧˥", "syllable_count": 1, "sentences": [{"text": "这条路又长又直。", "target_word": "直", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他站得很直，像一棵小树。", "target_word": "直", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这棵树长得很直，可以做房子的柱子。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你坐直，不要靠在桌子上。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的头发很直，不用烫就很好看。", "target_word": "直", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条河不直，弯来弯去，很长。", "target_word": "直", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "马路修得很直，开车一点也不累。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟用尺子画了一条直的线。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，这些树长得真直啊。", "target_word": "直", "complexity_tier": "T3", "furigana": "nǐ kàn, zhèxiē shù zhǎng de zhēn zhí a.", "sentence_source": "generated"}, {"text": "这根铁管不直，要把它弄直才能用。", "target_word": "直", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "直直的", "label": "重叠"}, {"form": "笔直", "label": "复合"}], "register": "中性", "sense_fingerprint": "道路、树木、身体等从头到尾不弯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '388a63b1-0373-4e8f-9a4b-1f114645e9ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：直（zhí）指线条或物体不弯曲，成直线。"}, {"text": "只", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是仅、只。"}, {"text": "十", "is_correct": false, "explanation": "shí 与 zhí 声母不同（sh 与 zh），意思是数字十。"}, {"text": "迟", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch 与 zh），意思是慢、晚。"}, {"text": "质", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是性质、品质。"}], "explanations": {"直": "正确：直（zhí）指线条或物体不弯曲，成直线。", "只": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是仅、只。", "十": "shí 与 zhí 声母不同（sh 与 zh），意思是数字十。", "迟": "chí 与 zhí 声母不同（ch 与 zh），意思是慢、晚。", "质": "zhì（第四声）与 zhí（第二声）声调不同，意思是性质、品质。"}, "sentence_index": null, "correct_answer": "直"}, "level_3": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：“又长又直”说路线平直，符合“直”的不弯曲义。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说上下的高度，不用来说路线的平直。"}, {"text": "粗", "is_correct": false, "explanation": "搭配：“粗”说物体的粗细，不用来形容路。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线明暗，与路线是否笔直无关。"}], "explanations": {"直": "正确：“又长又直”说路线平直，符合“直”的不弯曲义。", "高": "搭配：“高”说上下的高度，不用来说路线的平直。", "粗": "搭配：“粗”说物体的粗细，不用来形容路。", "亮": "语义：“亮”说光线明暗，与路线是否笔直无关。"}, "sentence_index": 0, "correct_answer": "直"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听到这个消息后，心情很直，一句话也没说。", "explanation": "这里应该用〈平静〉。“直”说线条或物体不弯，形容心情安定要用“平静”。"}, {"text": "这块地很直，很适合种菜。", "explanation": "这里应该用〈平〉。直说线条或物体不弯，平说表面没有起伏，形容地面要用“平”。"}, {"text": "这块饼干很直，咬起来很脆。", "explanation": "这里应该用〈方〉。饼干的形状说“方”，“直”只说线条或物体不弯，不能用来形容饼干。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：直（zhí）指线条或物体不弯曲，成直线。"}, {"text": "纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是纸张。"}, {"text": "知", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是知道。"}, {"text": "池", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch 与 zh），意思是水池。"}, {"text": "治", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是治理、医治。"}], "explanations": {"直": "正确：直（zhí）指线条或物体不弯曲，成直线。", "纸": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是纸张。", "知": "zhī（第一声）与 zhí（第二声）声调不同，意思是知道。", "池": "chí 与 zhí 声母不同（ch 与 zh），意思是水池。", "治": "zhì（第四声）与 zhí（第二声）声调不同，意思是治理、医治。"}, "sentence_index": null, "correct_answer": "直"}, "level_3": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：“马路修得很直”说路面笔直，开车才不累。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说高低，不用来描述修路的结果。"}, {"text": "深", "is_correct": false, "explanation": "搭配：“深”说深浅，马路不能修得深。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”说分量，与路的形状无关，也与“开车不累”矛盾。"}], "explanations": {"直": "正确：“马路修得很直”说路面笔直，开车才不累。", "矮": "搭配：“矮”说高低，不用来描述修路的结果。", "深": "搭配：“深”说深浅，马路不能修得深。", "重": "语义：“重”说分量，与路的形状无关，也与“开车不累”矛盾。"}, "sentence_index": 6, "correct_answer": "直"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子很直，装得很满。", "explanation": "这里应该用〈方〉。箱子的形状说“方”，“直”只说线条或物体不弯，不能形容箱子。"}, {"text": "这块肉很直，切起来很方便。", "explanation": "这里应该用〈厚〉。肉的厚薄要用“厚”，“直”只说线条或物体不弯，不能用来形容肉。"}, {"text": "这条河的波浪很直，很好看。", "explanation": "这里应该用〈起伏〉。波浪是起伏的，“直”只说线条不弯，形容波浪要说“起伏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写字时坐很直，腰也不弯。", "corrected_sentence": "他写字时坐得很直，腰也不弯。", "error_description": "错误：“坐很直”；正确：“坐得很直”。动词后面接形容词作补语时要用“得”，漏掉“得”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路修得直很，走起来很方便。", "corrected_sentence": "这条路修得很直，走起来很方便。", "error_description": "错误：“直很”语序颠倒；正确：“很直”。“很”修饰形容词，要放在形容词前面，不能放在后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弯", "is_correct": true, "explanation": "正确：“弯”与“直”在“不弯曲”义上互为反义。"}, {"text": "低", "is_correct": false, "explanation": "与“直”无反义关系，“低”与“高”相对，不是“直”的反义。"}, {"text": "圆", "is_correct": false, "explanation": "与“直”无反义关系，“圆”说形状，不是“直”的对立面。"}, {"text": "宽", "is_correct": false, "explanation": "与“直”无反义关系，“宽”说宽度。"}], "correct_answer": "弯", "explanations": {"弯": "正确：“弯”与“直”在“不弯曲”义上互为反义。", "低": "与“直”无反义关系，“低”与“高”相对，不是“直”的反义。", "圆": "与“直”无反义关系，“圆”说形状，不是“直”的对立面。", "宽": "与“直”无反义关系，“宽”说宽度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弯", "is_correct": true, "explanation": "正确：“弯”与“直”在“不弯曲”义上互为反义。"}, {"text": "慢", "is_correct": false, "explanation": "与“直”无反义关系，“慢”说速度。"}, {"text": "粗", "is_correct": false, "explanation": "与“直”无反义关系，“粗”说粗细。"}, {"text": "深", "is_correct": false, "explanation": "与“直”无反义关系，“深”说深浅。"}], "correct_answer": "弯", "explanations": {"弯": "正确：“弯”与“直”在“不弯曲”义上互为反义。", "慢": "与“直”无反义关系，“慢”说速度。", "粗": "与“直”无反义关系，“粗”说粗细。", "深": "与“直”无反义关系，“深”说深浅。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不弯曲；成直线的。", "primary_collocate": null, "pronunciation": "zhí", "ipa": "ʈʂʅ˧˥", "syllable_count": 1, "sentences": [{"text": "这条路很直，走十分钟就到学校了。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把背挺得直一点。", "target_word": "直", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿又长又直，很适合跳舞。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旗杆立在操场中间，又高又直。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "画这条线的时候，手要稳，线才会直。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条小河一点也不直，转了好几个弯。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把这根弯铁丝拉直，再放进盒子里。", "target_word": "直", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段铁路很直，火车可以开得很快。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走路时背很直，一看就是军人。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把尺子的边很直，可以用来画线。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "直直的", "label": "重叠"}, {"form": "笔直", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体或线条不弯曲，呈直线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '388a63b1-0373-4e8f-9a4b-1f114645e9ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：直（zhí）指不弯曲，成直线。"}, {"text": "指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是手指。"}, {"text": "石", "is_correct": false, "explanation": "shí 与 zhí 声母不同（sh 与 zh），意思是石头。"}, {"text": "持", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch 与 zh），意思是坚持、保持。"}, {"text": "志", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是志向。"}], "explanations": {"直": "正确：直（zhí）指不弯曲，成直线。", "指": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是手指。", "石": "shí 与 zhí 声母不同（sh 与 zh），意思是石头。", "持": "chí 与 zhí 声母不同（ch 与 zh），意思是坚持、保持。", "志": "zhì（第四声）与 zhí（第二声）声调不同，意思是志向。"}, "sentence_index": null, "correct_answer": "直"}, "level_3": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：“这条路很直”说路线平直，与“走十分钟就到学校”相符。"}, {"text": "粗", "is_correct": false, "explanation": "搭配：“粗”说粗细，不用来形容路的走法。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，与路的长短和平直无关。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说高低，不用来说路线本身。"}], "explanations": {"直": "正确：“这条路很直”说路线平直，与“走十分钟就到学校”相符。", "粗": "搭配：“粗”说粗细，不用来形容路的走法。", "甜": "语义：“甜”说味道，与路的长短和平直无关。", "矮": "搭配：“矮”说高低，不用来说路线本身。"}, "sentence_index": 0, "correct_answer": "直"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片操场很直，适合跑步。", "explanation": "这里应该用〈平〉。直说线条不弯，平说表面没有起伏，形容操场要用“平”。"}, {"text": "这个西瓜很直，又大又甜。", "explanation": "这里应该用〈圆〉。西瓜是圆的，“直”只说线条或物体不弯，不能用来形容西瓜。"}, {"text": "这个池塘很直，很漂亮。", "explanation": "这里应该用〈平静〉。池塘的水面说“平静”，“直”只说线条或物体不弯，不能形容池塘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：直（zhí）指不弯曲，成直线。"}, {"text": "止", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是停止。"}, {"text": "时", "is_correct": false, "explanation": "shí 与 zhí 声母不同（sh 与 zh），意思是时间。"}, {"text": "池", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch 与 zh），意思是水池。"}, {"text": "至", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是到达、极。"}], "explanations": {"直": "正确：直（zhí）指不弯曲，成直线。", "止": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是停止。", "时": "shí 与 zhí 声母不同（sh 与 zh），意思是时间。", "池": "chí 与 zhí 声母不同（ch 与 zh），意思是水池。", "至": "zhì（第四声）与 zhí（第二声）声调不同，意思是到达、极。"}, "sentence_index": null, "correct_answer": "直"}, "level_3": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：“拉直”说把弯铁丝变平直，与后面“放进盒子里”相符。"}, {"text": "宽", "is_correct": false, "explanation": "搭配：“宽”说宽度，铁丝不能拉宽。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”说厚薄，与“拉”使铁丝变细的动作不合。"}, {"text": "深", "is_correct": false, "explanation": "搭配：“深”说深浅，铁丝不能拉深。"}], "explanations": {"直": "正确：“拉直”说把弯铁丝变平直，与后面“放进盒子里”相符。", "宽": "搭配：“宽”说宽度，铁丝不能拉宽。", "厚": "语义：“厚”说厚薄，与“拉”使铁丝变细的动作不合。", "深": "搭配：“深”说深浅，铁丝不能拉深。"}, "sentence_index": 6, "correct_answer": "直"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤很直，很好喝。", "explanation": "这里应该用〈香〉。汤说味道，“直”只说线条或物体不弯，不能用来形容汤。"}, {"text": "这块蛋糕很直，切开很好看。", "explanation": "这里应该用〈方〉。蛋糕的形状说“方”，“直”只说线条或物体不弯，不能用来形容蛋糕。"}, {"text": "这颗鸡蛋很直，放在桌上很稳。", "explanation": "这里应该用〈椭圆〉。鸡蛋是椭圆的，“直”只说线条不弯，不能用来形容鸡蛋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条小巷修很直，走起来很顺。", "corrected_sentence": "这条小巷修得很直，走起来很顺。", "error_description": "错误：“修很直”；正确：“修得很直”。动词后面接形容词作补语时要用“得”，漏掉“得”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "把这根铁丝直，再挂起来。", "corrected_sentence": "把这根铁丝弄直，再挂起来。", "error_description": "错误：“把……直”；正确：“把……弄直”。“把”字句中形容词不能直接作谓语，要加动词“弄”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
