INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90578, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "将帅发出的命令。", "primary_collocate": null, "pronunciation": "jiàng lìng", "ipa": "tɕjɑŋ˥˩ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "将令一下，全军立刻出发了。", "target_word": "将令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们必须听从将令，不能乱动。", "target_word": "将令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他违反了将令，被将军重重处罚。", "target_word": "将令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将令一出，没有人敢违抗。", "target_word": "将令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传令兵把将令送到了前线。", "target_word": "将令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大将军发出将令，命全军天亮时进城。", "target_word": "将令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道将令太急，士兵们连饭也没吃。", "target_word": "将令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军中最重要的是服从将令。", "target_word": "将令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有接到将令，所以不敢出兵。", "target_word": "将令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小兵听着将令，心里十分紧张。", "target_word": "将令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道将令", "label": "量词"}, {"form": "將令", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "将帅发出的命令", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0164a193-a1b9-4b34-a43a-61ec32a530f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将令", "is_correct": true, "explanation": "将令：将帅发出的命令。“将令一下”指命令一经发出，与句意相符。"}, {"text": "将士", "is_correct": false, "explanation": "语义：将士指士兵，不能作“一下”的主语，句意不通。"}, {"text": "粮草", "is_correct": false, "explanation": "搭配：粮草是物资，不能发出“一下”这一动作，“粮草一下，全军出发”不成搭配。"}, {"text": "战场", "is_correct": false, "explanation": "语义：战场是地点，不会发出指令，“战场一下，全军立刻出发”说不通。"}], "explanations": {"将令": "将令：将帅发出的命令。“将令一下”指命令一经发出，与句意相符。", "将士": "语义：将士指士兵，不能作“一下”的主语，句意不通。", "粮草": "搭配：粮草是物资，不能发出“一下”这一动作，“粮草一下，全军出发”不成搭配。", "战场": "语义：战场是地点，不会发出指令，“战场一下，全军立刻出发”说不通。"}, "sentence_index": 0, "correct_answer": "将令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校昨天发了一道将令，明天放假。", "explanation": "这里应该用〈通知〉。将令专指将帅发出的军令，学校发布的通知不能说成将令。"}, {"text": "老板在会上发了一道将令，要大家加班。", "explanation": "这里应该用〈指示〉。将令只用于军中将帅，老板对员工的指示不能说成将令。"}, {"text": "我在书店买了一本将令，回家慢慢看。", "explanation": "这里应该用〈书〉。将令是将帅发出的命令，不是可以在书店买来阅读的书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将令", "is_correct": true, "explanation": "将令：将帅的命令。“这道将令”指这道紧急的命令，与“太急”和士兵没吃饭的情境相符。"}, {"text": "题", "is_correct": false, "explanation": "语义：题目不会“太急”，也不会让士兵连饭都没吃，句意不通。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“太急”不能描述墙，“这道墙太急”与后文的因果关系无法成立。"}, {"text": "门", "is_correct": false, "explanation": "语义：门是建筑部件，不能“太急”，与士兵的处境无关，句意不通。"}], "explanations": {"将令": "将令：将帅的命令。“这道将令”指这道紧急的命令，与“太急”和士兵没吃饭的情境相符。", "题": "语义：题目不会“太急”，也不会让士兵连饭都没吃，句意不通。", "墙": "搭配：“太急”不能描述墙，“这道墙太急”与后文的因果关系无法成立。", "门": "语义：门是建筑部件，不能“太急”，与士兵的处境无关，句意不通。"}, "sentence_index": 6, "correct_answer": "将令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他手里拿着一只将令，很神气。", "explanation": "这里应该用〈道〉。量词“只”用于动物或成对物品中的一个，将令应用“道”。"}, {"text": "他拿了一把将令，一直看着。", "explanation": "这里应该用〈道〉。量词“把”用于有柄的器具，将令应用“道”。"}, {"text": "他捡到一颗将令，觉得很奇怪。", "explanation": "这里应该用〈道〉。量词“颗”用于小而圆的东西，将令应用“道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "主帅派人送来了一只将令。", "corrected_sentence": "主帅派人送来了一道将令。", "error_description": "量词错误：将令是军中的命令，量词应用“道”。“只”用于动物或成对物品中的一个，不能用于将令，应说“一道将令”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "参谋长昨晚发出了一首将令。", "corrected_sentence": "参谋长昨晚发出了一道将令。", "error_description": "量词错误：将令是军中的命令，量词应用“道”。“首”专用于诗词、歌曲，不能用于将令，应说“一道将令”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背对", "is_correct": true, "explanation": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。"}, {"text": "进入", "is_correct": false, "explanation": "无关：“进入”指从外到内，与朝向的意思没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：“搬运”指搬动物品，与朝向无关。"}, {"text": "收藏", "is_correct": false, "explanation": "无关：“收藏”指保存物品，与朝向无关。"}], "correct_answer": "背对", "explanations": {"背对": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。", "进入": "无关：“进入”指从外到内，与朝向的意思没有反义关系。", "搬运": "无关：“搬运”指搬动物品，与朝向无关。", "收藏": "无关：“收藏”指保存物品，与朝向无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背对", "is_correct": true, "explanation": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。"}, {"text": "融化", "is_correct": false, "explanation": "无关：“融化”指固体变成液体，与方位朝向无关。"}, {"text": "挖掘", "is_correct": false, "explanation": "无关：“挖掘”指向下刨土，与方位朝向无关。"}, {"text": "倾倒", "is_correct": false, "explanation": "无关：“倾倒”指把东西倒出，与方位朝向无关。"}], "correct_answer": "背对", "explanations": {"背对": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。", "融化": "无关：“融化”指固体变成液体，与方位朝向无关。", "挖掘": "无关：“挖掘”指向下刨土，与方位朝向无关。", "倾倒": "无关：“倾倒”指把东西倒出，与方位朝向无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "脸或东西直直地对着一个方向。", "primary_collocate": null, "pronunciation": "zhèng duì", "ipa": "ʈʂəŋ˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他正对着镜子整理头发。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你正对着我，不要看别处。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电风扇正对着我吹，有点冷。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正对着大家，大声地说话。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相的时候，请正对着镜头。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯正对着我的眼睛，太亮了。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把椅子转过来，正对着老师坐下。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调正对着床，晚上会冷。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子正对着妈妈，开心地笑。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机摄像头要正对着书页。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正对着", "label": "体标"}], "register": "中性", "sense_fingerprint": "正对：脸或物体直直朝向某个方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad9311d-2259-4b31-9471-d7d48a98239a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正对", "is_correct": true, "explanation": "正确：“正对着镜子”表示正朝着镜子，与整理头发的动作相符。"}, {"text": "摔碎", "is_correct": false, "explanation": "语义：“摔碎”表示破裂，与整理头发的动作不相容。"}, {"text": "挂", "is_correct": false, "explanation": "配价：“挂”需要挂在某处的宾语，句子无法这样成立。"}, {"text": "拆开", "is_correct": false, "explanation": "语义：“拆开”指打开包装，与“镜子”搭配不当，句子意思不通。"}], "explanations": {"正对": "正确：“正对着镜子”表示正朝着镜子，与整理头发的动作相符。", "摔碎": "语义：“摔碎”表示破裂，与整理头发的动作不相容。", "挂": "配价：“挂”需要挂在某处的宾语，句子无法这样成立。", "拆开": "语义：“拆开”指打开包装，与“镜子”搭配不当，句子意思不通。"}, "sentence_index": 0, "correct_answer": "正对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正对我的话，只是点点头。", "explanation": "这里应该用〈理睬〉。“理睬”指对别人的话作出反应，“正对”只表示朝向，不能用于回应话语。"}, {"text": "孩子正对妈妈的话，只是笑了笑。", "explanation": "这里应该用〈回答〉。“回答”针对话语或问题，“正对”只表示朝向，不能用于回应话语。"}, {"text": "他正对老师的建议，马上照做了。", "explanation": "这里应该用〈接受〉。“接受”表示采纳意见，“正对”不能表示接受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正对", "is_correct": true, "explanation": "正确：“正对着老师”表示椅子朝向老师，与“坐下”相符。"}, {"text": "推开", "is_correct": false, "explanation": "语义：“推开”指用力使分离，与“转过来”的朝向动作不符，句子意思不通。"}, {"text": "收拾", "is_correct": false, "explanation": "语义：“收拾”指整理物品，不能指朝向老师，句子意思不通。"}, {"text": "拖动", "is_correct": false, "explanation": "配价：“拖动”需要被拖动的物体，“老师”不能被拖动。"}], "explanations": {"正对": "正确：“正对着老师”表示椅子朝向老师，与“坐下”相符。", "推开": "语义：“推开”指用力使分离，与“转过来”的朝向动作不符，句子意思不通。", "收拾": "语义：“收拾”指整理物品，不能指朝向老师，句子意思不通。", "拖动": "配价：“拖动”需要被拖动的物体，“老师”不能被拖动。"}, "sentence_index": 6, "correct_answer": "正对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正对我们的请求，很快就点了头。", "explanation": "这里应该用〈答应〉。“答应”表示同意请求，“正对”只表示朝向，不能用来表示同意。"}, {"text": "他正对了妈妈的要求，每天早点回家。", "explanation": "这里应该用〈按照〉。“按照”表示依据要求去做，“正对”只表示朝向，不能表示依照要求。"}, {"text": "他正对每件事，很认真。", "explanation": "这里应该用〈对待〉。“认真对待”指处理事情的态度，“正对”不能表示态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她正对了窗户化妆。", "corrected_sentence": "她正对着窗户化妆。", "error_description": "体标错误：表示持续的朝向状态要用“着”，说“正对了”不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小猫正对在门口坐着。", "corrected_sentence": "小猫正对着门口坐着。", "error_description": "介词误用：表示朝向要用“着”，“在”不能接在“正对”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90580, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背对", "is_correct": true, "explanation": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。"}, {"text": "穿越", "is_correct": false, "explanation": "无关：“穿越”指从一端通过到另一端，与朝向的意思没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：“搬运”指搬动物品，与方位朝向无关。"}, {"text": "收藏", "is_correct": false, "explanation": "无关：“收藏”指保存物品，与方位朝向无关。"}], "correct_answer": "背对", "explanations": {"背对": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。", "穿越": "无关：“穿越”指从一端通过到另一端，与朝向的意思没有反义关系。", "搬运": "无关：“搬运”指搬动物品，与方位朝向无关。", "收藏": "无关：“收藏”指保存物品，与方位朝向无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90580, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背对", "is_correct": true, "explanation": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。"}, {"text": "漂浮", "is_correct": false, "explanation": "无关：“漂浮”指浮在液体或空中，与方位朝向无关。"}, {"text": "融化", "is_correct": false, "explanation": "无关：“融化”指固体变成液体，与方位朝向无关。"}, {"text": "挖掘", "is_correct": false, "explanation": "无关：“挖掘”指向下刨土，与方位朝向无关。"}], "correct_answer": "背对", "explanations": {"背对": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。", "漂浮": "无关：“漂浮”指浮在液体或空中，与方位朝向无关。", "融化": "无关：“融化”指固体变成液体，与方位朝向无关。", "挖掘": "无关：“挖掘”指向下刨土，与方位朝向无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90580, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "正面相对；直对着。", "primary_collocate": null, "pronunciation": "zhèng duì", "ipa": "ʈʂəŋ˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我家的窗户正对着公园。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校大门正对着一条大街。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间教室正对着操场。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店的门正对着车站。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房子正对着我家的大门。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子正对着窗户，光线很好。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院正对着一座小山。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的座位正对着舞台。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家饭店正对着地铁站的出口。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的房间正对着大海，风景很美。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正对着", "label": "体标"}], "register": "中性", "sense_fingerprint": "正对：建筑、位置正面相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad9311d-2259-4b31-9471-d7d48a98239a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正对", "is_correct": true, "explanation": "正确：“正对着”表示窗户朝向公园，正面相对。"}, {"text": "进入", "is_correct": false, "explanation": "语义：“进入”指从外到内，窗户不能进入公园，与朝向的意思不符。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”需要可以搬动的物体作宾语，“窗户”和“公园”都不能被搬运。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”需要有人作主语、有可保存的物品，与窗户的朝向不相容。"}], "explanations": {"正对": "正确：“正对着”表示窗户朝向公园，正面相对。", "进入": "语义：“进入”指从外到内，窗户不能进入公园，与朝向的意思不符。", "搬运": "配价：“搬运”需要可以搬动的物体作宾语，“窗户”和“公园”都不能被搬运。", "收藏": "语义：“收藏”需要有人作主语、有可保存的物品，与窗户的朝向不相容。"}, "sentence_index": 0, "correct_answer": "正对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他勇敢地正对着困难。", "explanation": "这里应该用〈面对〉。“面对”可以用于困难等抽象事物，“正对”只表示位置上的正面相对。"}, {"text": "我们要好好正对这次机会。", "explanation": "这里应该用〈把握〉。“把握机会”是固定说法，“正对”只表示空间上的朝向，不能用于机会。"}, {"text": "这次的成绩正对了我的希望。", "explanation": "这里应该用〈符合〉。“符合”表示与要求或希望一致，“正对”只表示位置上的正面相对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正对", "is_correct": true, "explanation": "正确：“正对着”表示医院朝向小山，正面相对。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“离开”指脱离，医院不能离开小山，与朝向的意思不符。"}, {"text": "倒塌", "is_correct": false, "explanation": "语义：“倒塌”指崩坏，与朝向无关，句子意思不通。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”的对象通常是建筑，与“小山”搭配不当，也不能表示朝向。"}], "explanations": {"正对": "正确：“正对着”表示医院朝向小山，正面相对。", "离开": "语义：“离开”指脱离，医院不能离开小山，与朝向的意思不符。", "倒塌": "语义：“倒塌”指崩坏，与朝向无关，句子意思不通。", "拆除": "搭配：“拆除”的对象通常是建筑，与“小山”搭配不当，也不能表示朝向。"}, "sentence_index": 6, "correct_answer": "正对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正对我们的问题给出了答案。", "explanation": "这里应该用〈针对〉。“针对”指对问题有所指向，“正对”只表示正面相对的方位，不能用来给问题作答。"}, {"text": "他正对同学的批评，只是笑了笑。", "explanation": "这里应该用〈面对〉。“面对”可以用于批评等抽象事物，“正对”只表示位置上的正面相对。"}, {"text": "他正对工作很认真。", "explanation": "这里应该用〈对待〉。“对待”指对事情所持的态度，“正对”只表示朝向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路正对了山顶。", "corrected_sentence": "这条路正对着山顶。", "error_description": "体标错误：表示持续的朝向状态要用“着”，说“正对了”不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的房间正对在河流。", "corrected_sentence": "我的房间正对着河流。", "error_description": "介词误用：表示朝向要用“着”，“在”不能接在“正对”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
