INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90581, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "研发是想出新东西，再把它做出来。", "primary_collocate": null, "pronunciation": "yán fā", "ipa": "jɛn˧˥ fa˥", "syllable_count": 2, "sentences": [{"text": "这家公司正在研发一种新手机。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们研发了一个新的游戏。", "target_word": "研发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师想研发更轻的行李箱。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的学生研发出一种帮助老人的机器。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个药是国内公司自己研发的。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了三年时间研发这个软件。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司希望研发更安全的汽车。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研发新产品需要很多钱。", "target_word": "研发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李和朋友一起研发了一种好喝的茶。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在研发一种不用电的灯。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "研发了", "label": "体标"}, {"form": "研发过", "label": "体标"}, {"form": "研发中心", "label": "复合"}], "register": "中性", "sense_fingerprint": "研发：想出新东西并把它做出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4d7aeb-bdb3-4b50-b630-bfe4d39c60e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90581, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "研发", "is_correct": true, "explanation": "研发（yán fā）：想出新东西并做出来，是本题的目标词。"}, {"text": "盐巴", "is_correct": false, "explanation": "盐巴（yán bā）与研发（yán fā）只有第二个音节声母不同（b/f），意思是盐。"}, {"text": "严防", "is_correct": false, "explanation": "严防（yán fáng）与研发（yán fā）第二个音节韵母和声调不同（ang/a，第二声与第一声），意思是严密防备。"}, {"text": "严罚", "is_correct": false, "explanation": "严罚（yán fá）与研发（yán fā）只有第二个音节声调不同（第二声与第一声），意思是严厉惩罚。"}], "explanations": {"研发": "研发（yán fā）：想出新东西并做出来，是本题的目标词。", "盐巴": "盐巴（yán bā）与研发（yán fā）只有第二个音节声母不同（b/f），意思是盐。", "严防": "严防（yán fáng）与研发（yán fā）第二个音节韵母和声调不同（ang/a，第二声与第一声），意思是严密防备。", "严罚": "严罚（yán fá）与研发（yán fā）只有第二个音节声调不同（第二声与第一声），意思是严厉惩罚。"}, "sentence_index": null, "correct_answer": "研发"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的动作由人或动物完成，对象多为食物，“这家公司正在吃一种新手机”说不通。"}, {"text": "研发", "is_correct": true, "explanation": "研发：研制新东西并做出来，与“一种新手机”搭配，符合句意。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是汽车、飞机等交通工具，不能与“手机”搭配。"}, {"text": "养", "is_correct": false, "explanation": "语义：“养”的对象是动物、植物等生物，手机不能被养。"}], "explanations": {"吃": "语义：“吃”的动作由人或动物完成，对象多为食物，“这家公司正在吃一种新手机”说不通。", "研发": "研发：研制新东西并做出来，与“一种新手机”搭配，符合句意。", "驾驶": "搭配：“驾驶”的对象是汽车、飞机等交通工具，不能与“手机”搭配。", "养": "语义：“养”的对象是动物、植物等生物，手机不能被养。"}, "sentence_index": 0, "correct_answer": "研发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们研发了这个问题。", "explanation": "这里应该用〈研究〉。研发指研制新产品、新技术，对象是产品或技术；“问题”要用研究。"}, {"text": "这家工厂每年研发几百万双鞋。", "explanation": "这里应该用〈生产〉。研发侧重研制、试制新产品，不指大批量制造；“几百万双鞋”这类批量要用生产。"}, {"text": "他昨天研发了一条河。", "explanation": "这里应该用〈开凿〉。研发指研制新产品、新技术；河道是挖出来的，要用开凿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”多用于火、灯等，不能与“汽车”搭配。"}, {"text": "研发", "is_correct": true, "explanation": "研发：研制新的产品，与“更安全的汽车”搭配，符合句意。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”的对象是食物等，汽车不能被吞下。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱汽车”。"}], "explanations": {"熄灭": "搭配：“熄灭”多用于火、灯等，不能与“汽车”搭配。", "研发": "研发：研制新的产品，与“更安全的汽车”搭配，符合句意。", "吞": "语义：“吞”的对象是食物等，汽车不能被吞下。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱汽车”。"}, "sentence_index": 6, "correct_answer": "研发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖先研发了长城。", "explanation": "这里应该用〈修建〉。研发针对新产品、新技术；长城是古人经过大量劳动建成的工程，要用修建。"}, {"text": "考古学家研发出一座古城。", "explanation": "这里应该用〈挖掘〉。研发是研制新东西；古城本来就存在，要用挖掘。"}, {"text": "记者研发了农村的情况。", "explanation": "这里应该用〈调研〉。研发针对产品、技术；“农村的情况”要用调研。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们研发了出一种新的耳机。", "corrected_sentence": "他们研发出了一种新的耳机。", "error_description": "错误：“研发了出”。正确：“研发出了”。“出”是结果补语，要紧跟动词“研发”，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们研发了过一种新机器。", "corrected_sentence": "我们研发过一种新机器。", "error_description": "错误：“研发了过”。正确：“研发过”。“过”表示曾经做过某事，直接附在动词后，不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
