INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90583, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对称是两边看起来一模一样。", "primary_collocate": null, "pronunciation": "duì chèn", "ipa": "tuei˥˩ ʈʂʰən˥˩", "syllable_count": 2, "sentences": [{"text": "她的两个耳环看起来很对称。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张脸左右很对称，真好看。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的沙发和桌子放得很对称。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口两边的花摆得很对称。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两棵树长得很对称。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眉毛两边不太对称。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕上的水果放得左右对称。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个花瓶是对称的，一边一个。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把头发分成两边，看起来很对称。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里，山和水中的影子上下对称。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对称性", "label": "复合词"}, {"form": "轴对称", "label": "复合词"}, {"form": "對稱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对称：日常说法，指事物两边看起来一模一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20866e08-b43e-403c-ad2b-6b6e0b8a5d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90583, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欢快", "is_correct": false, "explanation": "语义：“欢快”形容人的情绪或气氛，不能用来描述耳环的样子。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”形容味道，不能用来形容耳环的外观。"}, {"text": "对称", "is_correct": true, "explanation": "对称：两个耳环的样子左右相当，符合句意。"}, {"text": "空阔", "is_correct": false, "explanation": "搭配：“空阔”形容场所或空间，不能修饰耳环。"}], "explanations": {"欢快": "语义：“欢快”形容人的情绪或气氛，不能用来描述耳环的样子。", "辣": "搭配：“辣”形容味道，不能用来形容耳环的外观。", "对称": "对称：两个耳环的样子左右相当，符合句意。", "空阔": "搭配：“空阔”形容场所或空间，不能修饰耳环。"}, "sentence_index": 0, "correct_answer": "对称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全家人相处得很对称。", "explanation": "这里应该用〈和谐〉。对称指物体两侧的形状相当，人与人相处融洽要用“和谐”。"}, {"text": "他的情绪很对称。", "explanation": "这里应该用〈稳定〉。对称说的是形状，情绪平稳要用“稳定”。"}, {"text": "我们两个人的意见很对称。", "explanation": "这里应该用〈一致〉。对称只说两侧相当，意见相同要用“一致”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90583, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雪白", "is_correct": false, "explanation": "语义：“雪白”形容颜色，不能用来描述水果的摆放。"}, {"text": "凶猛", "is_correct": false, "explanation": "语义：“凶猛”形容动物或人的攻击性，不能用于水果的摆放。"}, {"text": "酸", "is_correct": false, "explanation": "搭配：“酸”形容味道，不能修饰摆放的位置。"}, {"text": "对称", "is_correct": true, "explanation": "对称：水果摆放的左右两边相当，符合句意。"}], "explanations": {"雪白": "语义：“雪白”形容颜色，不能用来描述水果的摆放。", "凶猛": "语义：“凶猛”形容动物或人的攻击性，不能用于水果的摆放。", "酸": "搭配：“酸”形容味道，不能修饰摆放的位置。", "对称": "对称：水果摆放的左右两边相当，符合句意。"}, "sentence_index": 6, "correct_answer": "对称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的判罚很对称。", "explanation": "这里应该用〈公平〉。对称指两侧形状相当，判罚的公正要用“公平”。"}, {"text": "他讲的笑话很对称。", "explanation": "这里应该用〈幽默〉。对称说的是形状，笑话的风趣要用“幽默”。"}, {"text": "他对客人说话很对称。", "explanation": "这里应该用〈礼貌〉。对称不用来形容说话的态度，待人有礼要用“礼貌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90583, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的两只眼睛看起来没对称。", "corrected_sentence": "我的两只眼睛看起来不对称。", "error_description": "错误形式：没对称；正确形式：不对称。形容词「对称」的否定要用「不」，不用「没」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90583, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把头发梳很对称。", "corrected_sentence": "她把头发梳得很对称。", "error_description": "错误形式：梳很对称；正确形式：梳得很对称。动词后接表示结果、状态的补语时要用「得」连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
