INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90584, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "图形或物体在某条线或点的两侧大小、形状完全相当。", "primary_collocate": null, "pronunciation": "duì chèn", "ipa": "tuei˥˩ ʈʂʰən˥˩", "syllable_count": 2, "sentences": [{"text": "这个图形左右对称。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圆形是对称的图形。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶的两个翅膀很对称。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片叶子左边和右边很对称。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个对称的三角形。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的两边完全对称。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把纸对折以后，两边是对称的。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房子的门在中间，两边的窗户也对称。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这个字的左右两部分对称吗？", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在纸上画一个上下对称的图。", "target_word": "对称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对称性", "label": "复合词"}, {"form": "轴对称", "label": "复合词"}, {"form": "對稱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对称：图形或物体在一条线或一个点两侧的大小、形状完全相当", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20866e08-b43e-403c-ad2b-6b6e0b8a5d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迟钝", "is_correct": false, "explanation": "语义：“迟钝”形容人的反应或感觉，不能用来描述图形的形状。"}, {"text": "对称", "is_correct": true, "explanation": "对称：图形左右两边的大小、形状完全相当，符合句意。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”多形容声音，不能修饰图形。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说的是味道，与图形的左右两边无关。"}], "explanations": {"迟钝": "语义：“迟钝”形容人的反应或感觉，不能用来描述图形的形状。", "对称": "对称：图形左右两边的大小、形状完全相当，符合句意。", "清脆": "搭配：“清脆”多形容声音，不能修饰图形。", "甜": "语义：“甜”说的是味道，与图形的左右两边无关。"}, "sentence_index": 0, "correct_answer": "对称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天的饮食很对称。", "explanation": "这里应该用〈平衡〉。对称指图形或物体两侧的形状完全相当，说饮食搭配得当要用“平衡”。"}, {"text": "我们的看法很对称。", "explanation": "这里应该用〈一致〉。对称只用于两侧的形状或位置相当，看法相同要用“一致”。"}, {"text": "两国以对称的身份谈判。", "explanation": "这里应该用〈对等〉。对称说的是形状，双方地位平等要用“对等”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容嗓音，不能用来描述纸的两边。"}, {"text": "对称", "is_correct": true, "explanation": "对称：纸对折以后两边的形状完全相当，符合句意。"}, {"text": "怯懦", "is_correct": false, "explanation": "语义：“怯懦”指人的性格，纸的两边不能怯懦。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”形容味道或言语，不能用来描述纸的两边。"}], "explanations": {"沙哑": "搭配：“沙哑”形容嗓音，不能用来描述纸的两边。", "对称": "对称：纸对折以后两边的形状完全相当，符合句意。", "怯懦": "语义：“怯懦”指人的性格，纸的两边不能怯懦。", "辛辣": "搭配：“辛辣”形容味道或言语，不能用来描述纸的两边。"}, "sentence_index": 6, "correct_answer": "对称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两队的人数很对称。", "explanation": "这里应该用〈相等〉。对称指两侧的形状相当，人数相同要用“相等”。"}, {"text": "股市近来运行很对称。", "explanation": "这里应该用〈平稳〉。对称指两侧相当，形势稳定要用“平稳”。"}, {"text": "裁判的判罚很对称。", "explanation": "这里应该用〈公平〉。对称说的是形状，判罚的公正要用“公平”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两幅画的构图没对称。", "corrected_sentence": "这两幅画的构图不对称。", "error_description": "错误形式：没对称；正确形式：不对称。表示否定时，形容词“对称”前要用“不”，不用“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
