INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90585, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让人或动物不再活着。", "primary_collocate": null, "pronunciation": "shā sǐ", "ipa": "ʂa˥ sɿ˨˩˦", "syllable_count": 2, "sentences": [{"text": "猎人杀死了一只大老虎。", "target_word": "杀死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农夫用刀杀死了那条蛇。", "target_word": "杀死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察说，是他杀死了那个人。", "target_word": "杀死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "猫杀死了院子里的老鼠。", "target_word": "杀死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们把生病的鸡杀死了。", "target_word": "杀死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼杀死了山上的一只羊。", "target_word": "杀死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不敢杀死一只小鸟。", "target_word": "杀死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个坏人杀死过很多人。", "target_word": "杀死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王下令杀死所有的敌人。", "target_word": "杀死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条狗杀死了三只鸡。", "target_word": "杀死", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "杀死了", "label": "完成体"}, {"form": "杀死过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "以暴力使人或动物丧命，宾语多为人或动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '741a067b-35ee-42ee-a9a5-e70920a0d4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90585, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生", "is_correct": false, "explanation": "语义：“生”指生育，猎人不能生出老虎，与句意不符。"}, {"text": "杀死", "is_correct": true, "explanation": "杀死：使老虎丧命，与“猎人”和“大老虎”的句意相符，是唯一能填入的词。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”的对象一般是食物，不能说烤老虎。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”用于修理器物，不能修理动物。"}], "explanations": {"生": "语义：“生”指生育，猎人不能生出老虎，与句意不符。", "杀死": "杀死：使老虎丧命，与“猎人”和“大老虎”的句意相符，是唯一能填入的词。", "烤": "搭配：“烤”的对象一般是食物，不能说烤老虎。", "修": "搭配：“修”用于修理器物，不能修理动物。"}, "sentence_index": 0, "correct_answer": "杀死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他杀死了一张旧桌子。", "explanation": "这里应该用〈砸烂〉。“杀死”只用于有生命的人或动物，桌子没有生命，不能说杀死。"}, {"text": "法院杀死了那份旧合同。", "explanation": "这里应该用〈作废〉。“杀死”只用于有生命的人或动物，合同没有生命，应说“作废”。"}, {"text": "他杀死了那台旧电脑。", "explanation": "这里应该用〈报废〉。“杀死”只用于有生命的人或动物，机器没有生命，应说“报废”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90585, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "娶", "is_correct": false, "explanation": "搭配：“娶”的对象是人，不能说娶小鸟。"}, {"text": "杀死", "is_correct": true, "explanation": "杀死：使小鸟丧命，与“他不敢”的语境相符，是唯一能填入的词。"}, {"text": "雇", "is_correct": false, "explanation": "语义：“雇”指雇用人，小鸟不能被雇用，与句意不符。"}, {"text": "弑", "is_correct": false, "explanation": "语域：“弑”是书面语，专指臣杀君、子杀父，不能用于小鸟。"}], "explanations": {"娶": "搭配：“娶”的对象是人，不能说娶小鸟。", "杀死": "杀死：使小鸟丧命，与“他不敢”的语境相符，是唯一能填入的词。", "雇": "语义：“雇”指雇用人，小鸟不能被雇用，与句意不符。", "弑": "语域：“弑”是书面语，专指臣杀君、子杀父，不能用于小鸟。"}, "sentence_index": 6, "correct_answer": "杀死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他杀死了一块石头。", "explanation": "这里应该用〈砸碎〉。“杀死”的对象必须是有生命的人或动物，石头不能用“杀死”。"}, {"text": "他杀死了那只手套。", "explanation": "这里应该用〈扔掉〉。“杀死”只用于有生命的人或动物，手套没有生命，不能说杀死，应说“扔掉”。"}, {"text": "他杀死了那张地图。", "explanation": "这里应该用〈撕毁〉。“杀死”只用于有生命的对象，地图是物品，应说“撕毁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90585, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猎人昨天杀死一头野猪。", "corrected_sentence": "猎人昨天杀死了一头野猪。", "error_description": "“了”漏用：“昨天”指已完成的具体事件，动词后应加完成体“了”，应说“杀死了”，不能省略“了”说“杀死一头野猪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90585, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个强盗杀死了过一个路人。", "corrected_sentence": "那个强盗杀死过一个路人。", "error_description": "「了」和「过」不能叠用在「杀死」后面。表示曾经的经历只用「过」，「杀死了过」是错误的，正确为「杀死过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
