INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90586, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使死亡；弄死。", "primary_collocate": null, "pronunciation": "shā sǐ", "ipa": "ʂa˥ sɿ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种药能杀死虫子。", "target_word": "杀死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳光可以杀死很多细菌。", "target_word": "杀死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药水会杀死院子里的草。", "target_word": "杀死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开水能杀死水里的细菌。", "target_word": "杀死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些小虫杀死了一大片树。", "target_word": "杀死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒精可以杀死手上的细菌。", "target_word": "杀死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用药杀死了病人身体里的细菌。", "target_word": "杀死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的冷风杀死了不少花。", "target_word": "杀死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用热水杀死了桌上的小虫。", "target_word": "杀死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药很厉害，能杀死老鼠。", "target_word": "杀死", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "杀死了", "label": "完成体"}, {"form": "杀死过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "使细菌、害虫、植物等失去生命，用药、高温等手段弄死", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '741a067b-35ee-42ee-a9a5-e70920a0d4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90586, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：药不会吃东西，“吃”的施事应是有生命的动物。"}, {"text": "杀死", "is_correct": true, "explanation": "杀死：使虫子失去生命，与“这种药”的用途相符，是唯一能填入的词。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”指饲养，药不能饲养虫子。"}, {"text": "喂", "is_correct": false, "explanation": "语义：喂养的施事应是有生命的人或动物，药不能喂虫子。"}], "explanations": {"吃": "语义：药不会吃东西，“吃”的施事应是有生命的动物。", "杀死": "杀死：使虫子失去生命，与“这种药”的用途相符，是唯一能填入的词。", "养": "搭配：“养”指饲养，药不能饲养虫子。", "喂": "语义：喂养的施事应是有生命的人或动物，药不能喂虫子。"}, "sentence_index": 0, "correct_answer": "杀死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这阵风杀死了那团烟。", "explanation": "这里应该用〈驱散〉。“杀死”用于细菌、害虫、植物等生物，烟雾不是生物，应说“驱散”。"}, {"text": "这台机器杀死了屋里的灰尘。", "explanation": "这里应该用〈清除〉。灰尘没有生命，不能用“杀死”，应说“清除”。"}, {"text": "他用药杀死了那件衣服上的污渍。", "explanation": "这里应该用〈洗掉〉。污渍不是生物，不能杀死，应说“洗掉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "治愈", "is_correct": false, "explanation": "搭配：“治愈”的对象是病人或疾病，不能说治愈细菌。"}, {"text": "杀死", "is_correct": true, "explanation": "杀死：使细菌失去生命，与“用药”和句意相符，是唯一能填入的词。"}, {"text": "修复", "is_correct": false, "explanation": "搭配：“修复”用于受损的器官或器物，不用于细菌。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：药不能搬运细菌，“搬运”需要有动作能力的施事。"}], "explanations": {"治愈": "搭配：“治愈”的对象是病人或疾病，不能说治愈细菌。", "杀死": "杀死：使细菌失去生命，与“用药”和句意相符，是唯一能填入的词。", "修复": "搭配：“修复”用于受损的器官或器物，不用于细菌。", "搬运": "语义：药不能搬运细菌，“搬运”需要有动作能力的施事。"}, "sentence_index": 6, "correct_answer": "杀死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药很厉害，能杀死那堵墙。", "explanation": "这里应该用〈拆除〉。墙不是生物，不能用“杀死”，应说“拆除”。"}, {"text": "这种药很厉害，能杀死我的手表。", "explanation": "这里应该用〈弄坏〉。手表没有生命，不能杀死，应说“弄坏”。"}, {"text": "这种药很厉害，能杀死那件新衣服。", "explanation": "这里应该用〈毁掉〉。衣服没有生命，不能杀死，应说“毁掉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种药昨天杀死院子里的蚊子。", "corrected_sentence": "这种药昨天杀死了院子里的蚊子。", "error_description": "“了”漏用：“昨天”指已完成的具体事件，动词后应加完成体“了”，应说“杀死了”，不能省略“了”说“杀死院子里的蚊子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药杀死了过很多蚊子。", "corrected_sentence": "这种药杀死过很多蚊子。", "error_description": "「了」和「过」不能叠用在「杀死」后面。表示曾经的经历只用「过」，「杀死了过」是错误的，正确为「杀死过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
