INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90587, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "素质是一个人身上本来有的好本事和好习惯。", "primary_collocate": null, "pronunciation": "sù zhì", "ipa": "su˥˩ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这位老师的素质很高，教得好，还很有耐心。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当医生要有好素质，不但要有本事，还要细心。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的素质不错，学东西很快，做事也认真。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想找素质高的人，会做事，习惯好。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说这批新人的素质比去年高了。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她素质很好，学新东西很快，也从不迟到。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个好队员的素质，不只是跑得快，还要守规矩。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的素质让大家都很放心，什么工作都能做好。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要培养学生的素质，让他们有本事，也有好习惯。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子素质很好，早睡早起，学习也努力。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "素質", "label": "繁体"}, {"form": "身体素质", "label": "复合"}, {"form": "素质教育", "label": "复合"}], "register": "中性", "sense_fingerprint": "人身上本来有的好本事和好习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '388a63b1-0373-4e8f-9a4b-1f114645e9ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90587, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "素质", "is_correct": true, "explanation": "正确：“素质”指人的好本事和好习惯，与“教得好、有耐心”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不说高低，“很高”不能修饰颜色。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”说好坏、大小，不说“高”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指身体条件，与后面的教学能力和耐心无关。"}], "explanations": {"素质": "正确：“素质”指人的好本事和好习惯，与“教得好、有耐心”相符。", "颜色": "搭配：“颜色”不说高低，“很高”不能修饰颜色。", "脾气": "搭配：“脾气”说好坏、大小，不说“高”。", "身高": "语义：“身高”指身体条件，与后面的教学能力和耐心无关。"}, "sentence_index": 0, "correct_answer": "素质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的素质很胖，走路有点慢。", "explanation": "这里应该用〈体型〉。形容身材胖瘦要说“体型”，“素质”指人的本事和习惯，不能说胖。"}, {"text": "这次考试他的素质很好，老师很满意。", "explanation": "这里应该用〈成绩〉。考试的结果说“成绩”，“素质”不用来形容考试表现。"}, {"text": "他的英语素质很薄，只会说几句。", "explanation": "这里应该用〈基础〉。英语的底子说“基础”，“素质”指人身上的本事和习惯，不能说“薄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90587, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "素质", "is_correct": true, "explanation": "正确：“素质”指队员的本事和习惯，与“不只是跑得快，还要守规矩”相符。"}, {"text": "字体", "is_correct": false, "explanation": "语义：“字体”说字的样式，与队员的本事和规矩无关。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：“发型”是外在样式，不属于队员的本事和习惯。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”与能力和规矩无关，句子说不通。"}], "explanations": {"素质": "正确：“素质”指队员的本事和习惯，与“不只是跑得快，还要守规矩”相符。", "字体": "语义：“字体”说字的样式，与队员的本事和规矩无关。", "发型": "体貌：“发型”是外在样式，不属于队员的本事和习惯。", "名字": "语义：“名字”与能力和规矩无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "素质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的素质很漂亮，大家都喜欢看。", "explanation": "这里应该用〈长相〉。形容容貌要说“长相”，“素质”不能用来说漂亮。"}, {"text": "他的素质很大，什么活都能干。", "explanation": "这里应该用〈本事〉。“素质”不说“大”，形容本领大要说“本事”。"}, {"text": "他的素质很熟练，修车又快又好。", "explanation": "这里应该用〈技术〉。“熟练”形容技术和动作，“素质”不能说熟练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90587, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很素质，跟人相处很客气。", "corrected_sentence": "他很有素质，跟人相处很客气。", "error_description": "错误：“他很素质”；正确：“他很有素质”。“很”不能直接修饰名词“素质”，要先加“有”组成“有素质”，再由“很”修饰，漏掉“有”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90587, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的素质增加了，做事更认真。", "corrected_sentence": "他的素质提高了，做事更认真。", "error_description": "错误：“素质增加了”；正确：“素质提高了”。“素质”是抽象的好本事和好习惯，要用“提高”，不用“增加”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
