INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "篇幅极短的小说，也叫微型小说。", "primary_collocate": null, "pronunciation": "xiǎo xiǎo shuō", "ipa": "ɕjɑʊ˨˩ ɕjɑʊ˨˩ ʂwo˥", "syllable_count": 3, "sentences": [{"text": "小小说也叫微型小说，篇幅非常短。", "target_word": "小小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最爱读的是小小说，不是长篇小说。", "target_word": "小小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇小小说的结尾让我吃了一惊。", "target_word": "小小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志上每期都有两篇小小说。", "target_word": "小小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写小小说要在很短的字数里讲好故事。", "target_word": "小小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加了小小说比赛，还得了奖。", "target_word": "小小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家以写小小说出名。", "target_word": "小小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这篇小小说读给了奶奶听。", "target_word": "小小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小说的人物不多，故事却很完整。", "target_word": "小小说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这篇小小说放在床头，天天读一读。", "target_word": "小小说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一篇小小说", "label": "量词"}, {"form": "小小說", "label": "繁体"}], "register": "中性", "sense_fingerprint": "篇幅极短的小说，即微型小说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0164a193-a1b9-4b34-a43a-61ec32a530f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小小说", "is_correct": true, "explanation": "小小说：篇幅极短的小说，即微型小说。“也叫微型小说”与句意相符。"}, {"text": "散文", "is_correct": false, "explanation": "语义：散文不是微型小说的别称，“散文也叫微型小说”说不通。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌与微型小说不是同一文体，“诗歌也叫微型小说”句意不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语词，与书面的文体名不协调，“玩意儿也叫微型小说”不成立。"}], "explanations": {"小小说": "小小说：篇幅极短的小说，即微型小说。“也叫微型小说”与句意相符。", "散文": "语义：散文不是微型小说的别称，“散文也叫微型小说”说不通。", "诗歌": "语义：诗歌与微型小说不是同一文体，“诗歌也叫微型小说”句意不通。", "玩意儿": "语域：“玩意儿”是口语词，与书面的文体名不协调，“玩意儿也叫微型小说”不成立。"}, "sentence_index": 0, "correct_answer": "小小说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在台上唱了小小说，大家都很开心。", "explanation": "这里应该用〈歌曲〉。歌曲可以唱，小小说是要阅读的文字，不能说“唱”。"}, {"text": "他们下了一下午小小说。", "explanation": "这里应该用〈棋〉。“下”的对象是棋，小小说不能下。"}, {"text": "他是一位出名的小小说，粉丝很多。", "explanation": "这里应该用〈作家〉。小小说是文体名，指写作的人要说作家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小小说", "is_correct": true, "explanation": "小小说：一种文体，“写”的对象，与“以……出名”的搭配相符。"}, {"text": "发票", "is_correct": false, "explanation": "语义：发票不是文学体裁，“以写发票出名”说不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“写”不能接“手机”，二者不成搭配。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不能被“写”，与作家出名的语境无关，句意不通。"}], "explanations": {"小小说": "小小说：一种文体，“写”的对象，与“以……出名”的搭配相符。", "发票": "语义：发票不是文学体裁，“以写发票出名”说不通。", "手机": "搭配：“写”不能接“手机”，二者不成搭配。", "饭菜": "语义：饭菜不能被“写”，与作家出名的语境无关，句意不通。"}, "sentence_index": 6, "correct_answer": "小小说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他借来一把小小说，一直放在包里。", "explanation": "这里应该用〈篇〉。量词“把”用于有柄的器具，小小说应用“篇”。"}, {"text": "他在床头放了一朵小小说，天天看看。", "explanation": "这里应该用〈篇〉。量词“朵”用于花朵等，小小说应用“篇”。"}, {"text": "他写了一颗小小说，投给了杂志社。", "explanation": "这里应该用〈篇〉。量词“颗”用于小而圆的东西，小小说应用“篇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把一首小小说讲给了我听。", "corrected_sentence": "妈妈把一篇小小说讲给了我听。", "error_description": "量词用错：“首”用于诗歌、歌曲，小小说应用量词“篇”，应说“一篇小小说”，不能说“一首小小说”。这里的量词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很快就读完了这幅小小说。", "corrected_sentence": "她很快就读完了这篇小小说。", "error_description": "量词错误：“幅”用于字画，小小说应用量词“篇”，应说“这篇小小说”，不能说“这幅小小说”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa37aeb0-ad8b-4dc6-acb6-5a46d4406ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
