INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90593, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "老公是妻子对自己丈夫的叫法。", "primary_collocate": null, "pronunciation": "lǎo gōng", "ipa": "lau̯˨˩˦ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "我老公今天加班，晚上不回家吃饭。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给老公买了一件新衬衫。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老公做的饭很好吃。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我和老公一起去公园。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老公，你看看我的新裙子。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我老公在银行工作。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着对老公说：“谢谢你。”", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老公每天开车送我上班。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给老公打电话，他没接。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的老公很爱看书。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个老公", "label": "量词"}], "register": "口语", "sense_fingerprint": "老公：妻子对自己丈夫的叫法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0a5c81-35f2-4930-926c-6a53b5a7efb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90593, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老公", "is_correct": true, "explanation": "正确：lǎo gōng 指妻子称呼的丈夫。"}, {"text": "劳工", "is_correct": false, "explanation": "láo（第二声）与 lǎo（第三声）声调不同，意思是劳动者、工人。"}, {"text": "老歌", "is_correct": false, "explanation": "gē 与 gōng 韵母不同（e 与 ong），意思是过去流行的老歌曲。"}, {"text": "老哥", "is_correct": false, "explanation": "gē 与 gōng 韵母不同（e 与 ong），意思是哥哥或朋友之间的称呼。"}, {"text": "老根", "is_correct": false, "explanation": "gēn 与 gōng 韵母不同（en 与 ong），意思是老根、旧根基。"}], "explanations": {"老公": "正确：lǎo gōng 指妻子称呼的丈夫。", "劳工": "láo（第二声）与 lǎo（第三声）声调不同，意思是劳动者、工人。", "老歌": "gē 与 gōng 韵母不同（e 与 ong），意思是过去流行的老歌曲。", "老哥": "gē 与 gōng 韵母不同（e 与 ong），意思是哥哥或朋友之间的称呼。", "老根": "gēn 与 gōng 韵母不同（en 与 ong），意思是老根、旧根基。"}, "sentence_index": null, "correct_answer": "老公"}, "level_3": {"options": [{"text": "老公", "is_correct": true, "explanation": "正确：老公是妻子称丈夫的口语说法，符合句中“加班、吃饭”的口语语境。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：孩子不能加班，“孩子今天加班”说不通。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不会加班，句子说不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能加班，“我椅子今天加班”说不通。"}], "explanations": {"老公": "正确：老公是妻子称丈夫的口语说法，符合句中“加班、吃饭”的口语语境。", "孩子": "语义：孩子不能加班，“孩子今天加班”说不通。", "猫": "语义：猫不会加班，句子说不通。", "椅子": "语义：椅子不能加班，“我椅子今天加班”说不通。"}, "sentence_index": 0, "correct_answer": "老公"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的老公今天请假了，老师很着急。", "explanation": "这里应该用〈同学〉。老公指妻子的丈夫，不能用来称呼同班的男同学。"}, {"text": "我老公是我的亲弟弟，我们从小一起长大。", "explanation": "这里不能用〈老公〉。它只指妻子的丈夫，不指亲兄弟这样的血缘关系。"}, {"text": "路上走来一个陌生的老公，他一直盯着我。", "explanation": "老公专指妻子的丈夫，不能用来称呼陌生的男人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90593, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老公", "is_correct": true, "explanation": "正确：她对丈夫说谢谢，老公是妻子口语中对丈夫的称呼。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能听懂感谢，对它说谢谢说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能回应感谢，句子说不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不能听懂感谢，句子说不通。"}], "explanations": {"老公": "正确：她对丈夫说谢谢，老公是妻子口语中对丈夫的称呼。", "桌子": "语义：桌子不能听懂感谢，对它说谢谢说不通。", "石头": "语义：石头不能回应感谢，句子说不通。", "黑板": "语义：黑板不能听懂感谢，句子说不通。"}, "sentence_index": 6, "correct_answer": "老公"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "丈夫对妻子说：“老公，今天你做的饭真好吃。”", "explanation": "老公是妻子称呼丈夫的词，丈夫不能用它称呼妻子。"}, {"text": "她的老公是一个女人，很会化妆。", "explanation": "老公指男性配偶，不能指女性，这里用来指女性是错误的。"}, {"text": "我家的老公是一只小狗，很可爱。", "explanation": "这里不能用〈老公〉。它指人类配偶，不能用来指宠物小狗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90593, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我嫁了一只老公，他很会做饭。", "corrected_sentence": "我嫁了一个老公，他很会做饭。", "error_description": "量词错误：老公指人，量词应用“个”，不能用“只”。正确说法是“一个老公”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90593, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个老公们周末一起去打球。", "corrected_sentence": "几个老公周末一起去打球。", "error_description": "复数错误：前面有“几个”表示数量，名词后不能再加“们”。正确说法是“几个老公”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
