INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90595, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "居民点是很多人住在一起的地方。", "primary_collocate": null, "pronunciation": "jū mín diǎn", "ipa": "tɕy˥ min˧˥ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "山脚下有一个小居民点。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个居民点离城市很远。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边新建了一个居民点。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "居民点里有一家小商店。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些居民点都在山谷里。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走了很久才找到居民点。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，居民点的房子倒了很多。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没去过这个居民点。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公路修到了居民点门口。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "居民点旁边有一条小河。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "居民點", "label": "繁体"}], "register": "书面", "sense_fingerprint": "很多人住在一起的小地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbaef05-ab62-4cb3-bccf-d75c1fe06dac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90595, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "居民点", "is_correct": true, "explanation": "正确。“居民点”指很多人聚居的小地方，与“山脚下有一个小”的描述相符。"}, {"text": "首都", "is_correct": false, "explanation": "语义：首都是国家的政治中心，不会是山脚下的小地方。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋面积广大，与“小”和“山脚下”的描述相矛盾。"}, {"text": "语法", "is_correct": false, "explanation": "语义：“语法”是语言规则，不是地方，不能说“山脚下有一个小语法”。"}], "explanations": {"居民点": "正确。“居民点”指很多人聚居的小地方，与“山脚下有一个小”的描述相符。", "首都": "语义：首都是国家的政治中心，不会是山脚下的小地方。", "海洋": "语义：海洋面积广大，与“小”和“山脚下”的描述相矛盾。", "语法": "语义：“语法”是语言规则，不是地方，不能说“山脚下有一个小语法”。"}, "sentence_index": 0, "correct_answer": "居民点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个居民点有一百万人口。", "explanation": "这里应该用〈城市〉。居民点指小型聚居地，人口规模远不到一百万。"}, {"text": "这个居民点有两个卧室。", "explanation": "这里应该用〈公寓〉。卧室属于单个住宅单元，居民点是一片聚居地，不能说它有几间卧室。"}, {"text": "我们去了一只居民点。", "explanation": "这里应该用〈个〉。“只”用于动物等，不能用来计量居民点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90595, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "居民点", "is_correct": true, "explanation": "正确。地震后房子倒了很多，指的是一个聚居地的住宅，“居民点”符合语境。"}, {"text": "树林", "is_correct": false, "explanation": "语义：树林里没有成片的房屋，“的房子倒了很多”说不通。"}, {"text": "宝石", "is_correct": false, "explanation": "语义：宝石是矿物，不会有房子，与“房子倒了很多”搭配不上。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮上没有人住，也没有房子，“月亮的房子倒了很多”说不通。"}], "explanations": {"居民点": "正确。地震后房子倒了很多，指的是一个聚居地的住宅，“居民点”符合语境。", "树林": "语义：树林里没有成片的房屋，“的房子倒了很多”说不通。", "宝石": "语义：宝石是矿物，不会有房子，与“房子倒了很多”搭配不上。", "月亮": "语义：月亮上没有人住，也没有房子，“月亮的房子倒了很多”说不通。"}, "sentence_index": 6, "correct_answer": "居民点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天吃了一个居民点。", "explanation": "居民点指聚居的地方，不是食物；这句把它当成了可以吃的东西。"}, {"text": "居民点是我最好的朋友。", "explanation": "居民点是地方，不是人，不能当朋友；这句把它当成了人。"}, {"text": "居民点决定了下个月的选举日期。", "explanation": "居民点是聚居的地方，不是机构，不能决定选举；这句把它当成了组织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90595, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些居民点们都很新。", "corrected_sentence": "这些居民点都很新。", "error_description": "错误：“居民点们”。正确：“这些居民点”。“们”只加在指人的名词后，居民点是地方，不能加“们”；“这些”已经表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90595, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没去了那个居民点。", "corrected_sentence": "他从来没去过那个居民点。", "error_description": "错误：“没去了”。正确：“没去过”。“没”不能和“了”搭配，否定经历要用“没……过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
