INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "居民聚居的地方。", "primary_collocate": null, "pronunciation": "jū mín diǎn", "ipa": "tɕy˥ min˧˥ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "政府给新居民点修了路。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片草原上有几个居民点。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "居民点的人大多种地。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的居民点很少。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个居民点住着二百多户人家。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的居民点比较分散。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的孩子要走路去另一个居民点上学。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们计划在湖边建一个居民点。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个居民点有学校和医院。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水来了，居民点的人都搬走了。", "target_word": "居民点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "居民點", "label": "繁体"}], "register": "书面", "sense_fingerprint": "居民集中居住的聚居地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbaef05-ab62-4cb3-bccf-d75c1fe06dac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "居民点", "is_correct": true, "explanation": "正确。“修路”的对象是一个地方，“新居民点”符合这一语境。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是电器，不是地方，不能“给新电视修路”。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“修路”的对象是地方，“电脑”不能作为修路的对象。"}, {"text": "府上", "is_correct": false, "explanation": "语域：“府上”是对别人住处的敬称，用在这里不符合语域，也不能指政府修路的地方。"}], "explanations": {"居民点": "正确。“修路”的对象是一个地方，“新居民点”符合这一语境。", "电视": "语义：电视是电器，不是地方，不能“给新电视修路”。", "电脑": "搭配：“修路”的对象是地方，“电脑”不能作为修路的对象。", "府上": "语域：“府上”是对别人住处的敬称，用在这里不符合语域，也不能指政府修路的地方。"}, "sentence_index": 0, "correct_answer": "居民点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个居民点有很多大学。", "explanation": "这里应该用〈城市〉。居民点规模小，不会有很多所大学。"}, {"text": "我们去了一首居民点。", "explanation": "这里应该用〈个〉。“首”用于诗歌、歌曲，不能用来计量居民点。"}, {"text": "这个居民点有十二层。", "explanation": "这里应该用〈住宅楼〉。居民点是一片聚居地，不能说它有几层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "居民点", "is_correct": true, "explanation": "正确。“去另一个……上学”指去另一个聚居地，“居民点”符合语境。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产的地方，孩子不会去工厂上学。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，不是上学的地方。"}, {"text": "寒舍", "is_correct": false, "explanation": "语域：“寒舍”是自谦说自己家的书面语，不能用来指孩子要去的地方。"}], "explanations": {"居民点": "正确。“去另一个……上学”指去另一个聚居地，“居民点”符合语境。", "工厂": "语义：工厂是生产的地方，孩子不会去工厂上学。", "医院": "语义：医院是看病的地方，不是上学的地方。", "寒舍": "语域：“寒舍”是自谦说自己家的书面语，不能用来指孩子要去的地方。"}, "sentence_index": 6, "correct_answer": "居民点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把居民点煮进了汤里。", "explanation": "居民点是地方，不能当食材；这句把它当成了可以煮的东西。"}, {"text": "居民点是我的老师，常常教我道理。", "explanation": "居民点是地方，不是人，不能当老师；这句把它当成了人。"}, {"text": "居民点通过了一项新法律。", "explanation": "居民点是聚居的地方，不是立法机构，不能通过法律；这句把它当成了机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那些居民点们都很小。", "corrected_sentence": "那些居民点都很小。", "error_description": "错误：“居民点们”。正确：“那些居民点”。“们”只加在指人的名词后，居民点是地方，不能加“们”；“那些”已经表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们这个居民点住了三年。", "corrected_sentence": "他们在这个居民点住了三年。", "error_description": "错误：居住地点“这个居民点”直接放在主语“他们”后、动词前，句子结构不通。正确：用“在”引出居住地点，应说“他们在这个居民点住了三年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90597, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
