INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90599, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "没有原因，无缘无故。", "primary_collocate": null, "pronunciation": "wú yóu", "ipa": "u˧˥ jou˧˥", "syllable_count": 2, "sentences": [{"text": "她心里无由地难过起来。", "target_word": "无由", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窗外下着雨，我无由地想起了老家。", "target_word": "无由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无由发怒，大家都觉得奇怪。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那条狗无由地对着我叫了起来。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子无由地哭了起来。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋里很暖和，他却无由地打了个寒战。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他无由地笑了笑，没有说话。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没说什么，却无由地摔门而去。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里，她无由醒来，再也睡不着。", "target_word": "无由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱无由消失，谁也说不清。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "無由", "label": "繁体"}], "register": "书面", "sense_fingerprint": "无由-没有原因，无缘无故", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b74abb-82e7-47f8-a7df-97bad8dedd21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90599, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无由", "is_correct": true, "explanation": "无由：wú yóu，副词，表示没有原因。"}, {"text": "无忧", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声）声调不同，意思是没有忧愁。"}, {"text": "乌有", "is_correct": false, "explanation": "wū 与 wú 声调不同，yǒu（第三声）与 yóu（第二声）声调也不同，意思是不存在。"}, {"text": "无有", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，意思是没有。"}], "explanations": {"无由": "无由：wú yóu，副词，表示没有原因。", "无忧": "yōu（第一声）与 yóu（第二声）声调不同，意思是没有忧愁。", "乌有": "wū 与 wú 声调不同，yǒu（第三声）与 yóu（第二声）声调也不同，意思是不存在。", "无有": "yǒu（第三声）与 yóu（第二声）声调不同，意思是没有。"}, "sentence_index": null, "correct_answer": "无由"}, "level_3": {"options": [{"text": "无由", "is_correct": true, "explanation": "无由表示没有原因，“她”的难过无端而来，与句意相符。"}, {"text": "欣然", "is_correct": false, "explanation": "语义：欣然表示高兴，与“心里难过”的情绪相反。"}, {"text": "认真", "is_correct": false, "explanation": "搭配：“认真”修饰动作，不能修饰“难过”这种情绪。"}, {"text": "特意", "is_correct": false, "explanation": "语义：特意表示有意为之，与“心里难过”这种非自主的情绪不相合。"}], "explanations": {"无由": "无由表示没有原因，“她”的难过无端而来，与句意相符。", "欣然": "语义：欣然表示高兴，与“心里难过”的情绪相反。", "认真": "搭配：“认真”修饰动作，不能修饰“难过”这种情绪。", "特意": "语义：特意表示有意为之，与“心里难过”这种非自主的情绪不相合。"}, "sentence_index": 0, "correct_answer": "无由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他崴了脚，无由地走不了路。", "explanation": "前文已有明确原因（崴了脚），〈无由〉（没有原因）与之矛盾。"}, {"text": "他考试得了满分，无由地高兴起来。", "explanation": "前文说考了满分，有明确原因，〈无由〉（没有原因）不符。"}, {"text": "下了一整天的雨，他无由地没有出门。", "explanation": "前文说下了一整天的雨，有明确原因，〈无由〉（没有原因）不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90599, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无由", "is_correct": true, "explanation": "无由表示没有原因，与“没有说话”的沉默语境相符。"}, {"text": "连夜", "is_correct": false, "explanation": "语义：「连夜」指整夜，与「笑了笑」这一短暂动作不搭配。"}, {"text": "拼命", "is_correct": false, "explanation": "搭配：“拼命”修饰用力的动作，不修饰“笑”。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：「一直」表示持续，与「笑了笑」这一短暂动作矛盾。"}], "explanations": {"无由": "无由表示没有原因，与“没有说话”的沉默语境相符。", "连夜": "语义：「连夜」指整夜，与「笑了笑」这一短暂动作不搭配。", "拼命": "搭配：“拼命”修饰用力的动作，不修饰“笑”。", "一直": "搭配：「一直」表示持续，与「笑了笑」这一短暂动作矛盾。"}, "sentence_index": 6, "correct_answer": "无由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摔了一跤，无由地哭了起来。", "explanation": "前文已有明确原因（摔了一跤），〈无由〉（没有原因）与之矛盾。"}, {"text": "孩子饿了好几个小时，无由地哭个不停。", "explanation": "前文说饿了好几个小时，有明确原因，〈无由〉（没有原因）不符。"}, {"text": "他的钱包被偷了，无由地急得团团转。", "explanation": "前文说钱包被偷，有明确原因，〈无由〉（没有原因）不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90599, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她无由的脸红，连自己都奇怪。", "corrected_sentence": "她无由地脸红，连自己都奇怪。", "error_description": "“无由”修饰动作时要用“无由地”，“无由的”不能修饰动词。“无由的脸红”错误，应说“无由地脸红”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90599, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗户无由的关上了，大家都很吃惊。", "corrected_sentence": "窗户无由地关上了，大家都很吃惊。", "error_description": "“无由地”修饰动作时要用“地”，“无由的”不能修饰动词。“无由的关上”错误，应说“无由地关上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
