INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90602, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "警察或士兵沿着一定的路线边走边查看。", "primary_collocate": null, "pronunciation": "xún luó", "ipa": "ɕyn˧˥ luo˧˥", "syllable_count": 2, "sentences": [{"text": "士兵沿着边境线巡逻。", "target_word": "巡逻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警察骑着马在广场上巡逻。", "target_word": "巡逻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们每天沿着河边巡逻一圈。", "target_word": "巡逻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "巡逻的警察发现了一个丢失的孩子。", "target_word": "巡逻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两名士兵在营地周围来回巡逻。", "target_word": "巡逻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警车每小时在这条街上巡逻一次。", "target_word": "巡逻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是边防战士，天天在山路上巡逻。", "target_word": "巡逻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察正在公园里巡逻，查看有没有危险。", "target_word": "巡逻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察带着警犬在车站附近巡逻。", "target_word": "巡逻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们已经巡逻过这座山了。", "target_word": "巡逻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巡逻了", "label": "体标"}, {"form": "巡逻着", "label": "体标"}, {"form": "巡逻过", "label": "体标"}, {"form": "巡逻队", "label": "复合"}], "register": "中性", "sense_fingerprint": "巡逻：警察或士兵沿路线边走边查看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52af20df-6e56-40f6-a8c1-0c1dd987e45e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毕业", "is_correct": false, "explanation": "语义：毕业指完成学业，不能「沿着边境线」毕业，与句意不符。"}, {"text": "派", "is_correct": false, "explanation": "配价：“派”必须带宾语（派某人去某地），这里没有宾语，句子不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：沿边境线值守的士兵不能在任务中“睡觉”，这与句中的职责相矛盾。"}, {"text": "巡逻", "is_correct": true, "explanation": "正确：士兵沿着边境线按路线边走边查看，符合“巡逻”。"}], "explanations": {"毕业": "语义：毕业指完成学业，不能「沿着边境线」毕业，与句意不符。", "派": "配价：“派”必须带宾语（派某人去某地），这里没有宾语，句子不成立。", "睡觉": "语义：沿边境线值守的士兵不能在任务中“睡觉”，这与句中的职责相矛盾。", "巡逻": "正确：士兵沿着边境线按路线边走边查看，符合“巡逻”。"}, "sentence_index": 0, "correct_answer": "巡逻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "将军在队伍前面巡逻部队。", "explanation": "这里应该用〈检阅〉。巡逻是沿路线边走边查看，不能带“部队”作宾语；检阅部队要用检阅。"}, {"text": "周末我去医院巡逻病人。", "explanation": "这里应该用〈探望〉。巡逻是为了执行安全任务，去医院看望病人要用探望。"}, {"text": "两名警察巡逻一名犯人。", "explanation": "这里应该用〈押送〉。巡逻不能以人为宾语，押送犯人才是护送、看管人员的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗澡", "is_correct": false, "explanation": "语义：边防战士在山路上执行任务，不会在路上“洗澡”，与“天天”值守的语境矛盾。"}, {"text": "运", "is_correct": false, "explanation": "配价：“运”必须带宾语（运某物），句中“在山路上运”后没有宾语，句子不成立。"}, {"text": "巡逻", "is_correct": true, "explanation": "正确：边防战士天天在山路上边走边查看，符合“巡逻”的意思。"}, {"text": "播种", "is_correct": false, "explanation": "搭配：“播种”的对象是种子或农田，山路上不能播种。"}], "explanations": {"洗澡": "语义：边防战士在山路上执行任务，不会在路上“洗澡”，与“天天”值守的语境矛盾。", "运": "配价：“运”必须带宾语（运某物），句中“在山路上运”后没有宾语，句子不成立。", "巡逻": "正确：边防战士天天在山路上边走边查看，符合“巡逻”的意思。", "播种": "搭配：“播种”的对象是种子或农田，山路上不能播种。"}, "sentence_index": 6, "correct_answer": "巡逻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游客们每天在景区里巡逻。", "explanation": "这里应该用〈游览〉。巡逻是有职责的人沿路线边走边查看、保障安全，四处观赏景点要用游览。"}, {"text": "这把椅子每天在办公室里巡逻。", "explanation": "这里应该用〈放置〉。巡逻要求有职责、能主动查看的人或动物，椅子不能巡逻，只能说放置在办公室里。"}, {"text": "这棵大树每天在路边巡逻。", "explanation": "这里应该用〈矗立〉。巡逻要求有职责、能主动查看的人或动物，树木不能巡逻，只能说矗立在路边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们从营地出发，沿着边境线巡逻很仔细。", "corrected_sentence": "士兵们从营地出发，沿着边境线巡逻得很仔细。", "error_description": "补语标记「得」漏掉：状态补语要用「动词+得+形容词」，应说「巡逻得很仔细」，不能说「巡逻很仔细」，学习者常漏掉「得」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支小队仔细的巡逻。", "corrected_sentence": "这支小队仔细地巡逻。", "error_description": "修饰动词的状语要用“地”连接，应说“仔细地巡逻”；“仔细的巡逻”没有谓语，是学习者常见的错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90603, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长期", "is_correct": true, "explanation": "长期与“短期”互为反义词，都指时间的长短。"}, {"text": "银行", "is_correct": false, "explanation": "银行与“短期”没有反义关系，是不同类的名词。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户与“短期”没有反义关系，二者不在同一语义范围内。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋与“短期”没有反义关系，不是时间概念。"}], "correct_answer": "长期", "explanations": {"长期": "长期与“短期”互为反义词，都指时间的长短。", "银行": "银行与“短期”没有反义关系，是不同类的名词。", "窗户": "窗户与“短期”没有反义关系，二者不在同一语义范围内。", "海洋": "海洋与“短期”没有反义关系，不是时间概念。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90603, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长期", "is_correct": true, "explanation": "长期与“短期”互为反义词，都指时间的长短。"}, {"text": "手机", "is_correct": false, "explanation": "手机与“短期”没有反义关系，是不同类的名词。"}, {"text": "课桌", "is_correct": false, "explanation": "课桌与“短期”没有反义关系，不是时间概念。"}, {"text": "云朵", "is_correct": false, "explanation": "云朵与“短期”没有反义关系，不在同一语义范围内。"}], "correct_answer": "长期", "explanations": {"长期": "长期与“短期”互为反义词，都指时间的长短。", "手机": "手机与“短期”没有反义关系，是不同类的名词。", "课桌": "课桌与“短期”没有反义关系，不是时间概念。", "云朵": "云朵与“短期”没有反义关系，不在同一语义范围内。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90603, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不长的一段时间。", "primary_collocate": null, "pronunciation": "duǎn qī", "ipa": "tuan˨˩˦ tɕʰi˥˥", "syllable_count": 2, "sentences": [{"text": "这是一份短期工作。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短期内，这里的天气不会变。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他报了一个短期课程。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个短期计划只有两周。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短期来看，价格不会涨。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只想找短期的工作，不想长期做。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加了一个短期的汉语班。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次是短期旅行，下周就回家。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我短期内不打算买新车。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱只是短期借用，下个月还你。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "短期内", "label": "复合"}, {"form": "短期计划", "label": "复合"}], "register": "中性", "sense_fingerprint": "短期：不长的一段时间，与长期相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0a5c81-35f2-4930-926c-6a53b5a7efb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90603, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "短期", "is_correct": true, "explanation": "正确：duǎn qī 指不长的一段时间。"}, {"text": "断气", "is_correct": false, "explanation": "duàn（第四声）与 duǎn（第三声）声调不同，qì 与 qī 声调也不同，意思是停止呼吸。"}, {"text": "远期", "is_correct": false, "explanation": "yuǎn 与 duǎn 声母不同（y 与 d），意思是遥远的将来。"}, {"text": "缓期", "is_correct": false, "explanation": "huǎn 与 duǎn 声母不同（h 与 d），意思是推迟、延后的时期。"}], "explanations": {"短期": "正确：duǎn qī 指不长的一段时间。", "断气": "duàn（第四声）与 duǎn（第三声）声调不同，qì 与 qī 声调也不同，意思是停止呼吸。", "远期": "yuǎn 与 duǎn 声母不同（y 与 d），意思是遥远的将来。", "缓期": "huǎn 与 duǎn 声母不同（h 与 d），意思是推迟、延后的时期。"}, "sentence_index": null, "correct_answer": "短期"}, "level_3": {"options": [{"text": "短期", "is_correct": true, "explanation": "正确：短期修饰“工作”，指时间较短的工作。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是工作的性质，“这是一份石头工作”说不通。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不能用来描述工作，句子说不通。"}, {"text": "红色", "is_correct": false, "explanation": "搭配：“红色”不能修饰“工作”，应说红色的东西，不说红色工作。"}], "explanations": {"短期": "正确：短期修饰“工作”，指时间较短的工作。", "石头": "语义：石头不是工作的性质，“这是一份石头工作”说不通。", "春天": "语义：春天是季节，不能用来描述工作，句子说不通。", "红色": "搭配：“红色”不能修饰“工作”，应说红色的东西，不说红色工作。"}, "sentence_index": 0, "correct_answer": "短期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一个短期的瞬间，转眼就过去了。", "explanation": "这里应该用〈短暂〉。短期指一段时间，不能用来修饰一瞬间。"}, {"text": "她给了我一个短期的笑容，很快就消失了。", "explanation": "这里应该用〈短暂〉。短期修饰时间段，不用来形容笑容这类瞬间。"}, {"text": "这个短期的习惯已经坚持了十年。", "explanation": "这里应该用〈长期〉。短期指时间短，与“坚持了十年”矛盾；持续很久要用长期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90603, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短期", "is_correct": true, "explanation": "正确：短期修饰“汉语班”，指时间较短的班，句子通顺。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁不能修饰班级，“钢铁的汉语班”说不通。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不能修饰班级，句子说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”不能用来修饰“汉语班”，搭配不当。"}], "explanations": {"短期": "正确：短期修饰“汉语班”，指时间较短的班，句子通顺。", "钢铁": "语义：钢铁不能修饰班级，“钢铁的汉语班”说不通。", "木头": "语义：木头不能修饰班级，句子说不通。", "冰箱": "搭配：“冰箱”不能用来修饰“汉语班”，搭配不当。"}, "sentence_index": 6, "correct_answer": "短期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找到一根短期的木棍，正好拿来撑衣服。", "explanation": "这里应该用〈短〉。短期只指时间，不用来形容木棍的长短。"}, {"text": "这条短期的河很浅，船开不进去。", "explanation": "这里应该用〈长〉。短期只指时间，不指河流的长度。"}, {"text": "这块短期的布做不成一件衣服。", "explanation": "这里应该用〈短〉。短期只指时间，不用来描述布料的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她找了一份短期内工作。", "corrected_sentence": "她找了一份短期工作。", "error_description": "错误：「短期内工作」；正确：「短期工作」。「短期内」表示时间范围，作状语；作定语修饰「工作」要说「短期工作」，去掉「内」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很短期内不会换手机。", "corrected_sentence": "我短期内不会换手机。", "error_description": "错误：“很”不能修饰时间状语“短期内”；去掉“很”，说“短期内不会换手机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90604, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长期", "is_correct": true, "explanation": "长期与“短期”互为反义词，指较长的一段时间，与较短的一段时间相对。"}, {"text": "灯泡", "is_correct": false, "explanation": "灯泡与“短期”没有反义关系，是不同类的名词。"}, {"text": "公园", "is_correct": false, "explanation": "公园与“短期”没有反义关系，不是时间概念。"}, {"text": "雨伞", "is_correct": false, "explanation": "雨伞与“短期”没有反义关系，不在同一语义范围内。"}], "correct_answer": "长期", "explanations": {"长期": "长期与“短期”互为反义词，指较长的一段时间，与较短的一段时间相对。", "灯泡": "灯泡与“短期”没有反义关系，是不同类的名词。", "公园": "公园与“短期”没有反义关系，不是时间概念。", "雨伞": "雨伞与“短期”没有反义关系，不在同一语义范围内。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90604, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长期", "is_correct": true, "explanation": "长期与“短期”互为反义词，指较长的一段时间。"}, {"text": "书包", "is_correct": false, "explanation": "书包与“短期”没有反义关系，是不同类的名词。"}, {"text": "草莓", "is_correct": false, "explanation": "草莓与“短期”没有反义关系，不是时间概念。"}, {"text": "闹钟", "is_correct": false, "explanation": "闹钟与“短期”没有反义关系，不在同一语义范围内。"}], "correct_answer": "长期", "explanations": {"长期": "长期与“短期”互为反义词，指较长的一段时间。", "书包": "书包与“短期”没有反义关系，是不同类的名词。", "草莓": "草莓与“短期”没有反义关系，不是时间概念。", "闹钟": "闹钟与“短期”没有反义关系，不在同一语义范围内。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90604, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "较短的一段时间。", "primary_collocate": null, "pronunciation": "duǎn qī", "ipa": "tuan˨˩˦ tɕʰi˥˥", "syllable_count": 2, "sentences": [{"text": "短期内他不会回国，因为工作很忙。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的短期目标是多卖一百台。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药短期吃没问题，长期吃不好。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短期的困难很快就会过去。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在短期内学会了游泳。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先做短期安排，以后再说。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短期贷款一年以内就要还。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店只做短期出租，最长三个月。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短期看，天气会一直很热。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的短期计划是先把工作找到。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "短期内", "label": "复合"}, {"form": "短期目标", "label": "复合"}], "register": "中性", "sense_fingerprint": "短期：较短的一段时间，常与长期对比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0a5c81-35f2-4930-926c-6a53b5a7efb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90604, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "短期", "is_correct": true, "explanation": "正确：duǎn qī 指较短的一段时间。"}, {"text": "断气", "is_correct": false, "explanation": "duàn（第四声）与 duǎn（第三声）声调不同，qì 与 qī 声调也不同，意思是停止呼吸。"}, {"text": "远期", "is_correct": false, "explanation": "yuǎn 与 duǎn 声母不同（y 与 d），意思是遥远的将来。"}, {"text": "缓期", "is_correct": false, "explanation": "huǎn 与 duǎn 声母不同（h 与 d），意思是推迟、延后的时期。"}], "explanations": {"短期": "正确：duǎn qī 指较短的一段时间。", "断气": "duàn（第四声）与 duǎn（第三声）声调不同，qì 与 qī 声调也不同，意思是停止呼吸。", "远期": "yuǎn 与 duǎn 声母不同（y 与 d），意思是遥远的将来。", "缓期": "huǎn 与 duǎn 声母不同（h 与 d），意思是推迟、延后的时期。"}, "sentence_index": null, "correct_answer": "短期"}, "level_3": {"options": [{"text": "短期", "is_correct": true, "explanation": "正确：“短期内”指较短的时间之内，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地点，不能表示时间范围，“厨房内他不会回国”说不通。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是地点，不能表示时间范围，句子说不通。"}, {"text": "中国", "is_correct": false, "explanation": "搭配：“中国内”不是常用说法，且“中国内他不会回国”语义别扭，不能填入。"}], "explanations": {"短期": "正确：“短期内”指较短的时间之内，符合句意。", "厨房": "语义：厨房是地点，不能表示时间范围，“厨房内他不会回国”说不通。", "书桌": "语义：书桌是地点，不能表示时间范围，句子说不通。", "中国": "搭配：“中国内”不是常用说法，且“中国内他不会回国”语义别扭，不能填入。"}, "sentence_index": 0, "correct_answer": "短期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的短期很长，听了半个小时还没结束。", "explanation": "这里应该用〈时长〉。短期指较短的一段时间，不能用“很长”修饰；说歌曲长度要用时长。"}, {"text": "这只乌龟的短期很长，已经活了一百年。", "explanation": "这里应该用〈寿命〉。短期指较短的一段时间，不能用“很长”修饰，也不用来指生物的寿命。"}, {"text": "这块石头的短期是一万年。", "explanation": "这里应该用〈年龄〉。短期指不长的一段时间，不用来说事物的年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短期", "is_correct": true, "explanation": "正确：短期修饰“贷款”，指一年以内的短期借款，符合句意。"}, {"text": "白云", "is_correct": false, "explanation": "语义：白云不能修饰贷款，“白云贷款”说不通。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不能修饰贷款，句子说不通。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“贷款”不能用早饭来修饰，搭配不当。"}], "explanations": {"短期": "正确：短期修饰“贷款”，指一年以内的短期借款，符合句意。", "白云": "语义：白云不能修饰贷款，“白云贷款”说不通。", "木头": "语义：木头不能修饰贷款，句子说不通。", "早饭": "搭配：“贷款”不能用早饭来修饰，搭配不当。"}, "sentence_index": 6, "correct_answer": "短期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根木棍的短期刚好能撑起衣服。", "explanation": "这里应该用〈短〉。短期指时间，不用来形容木棍的长短。"}, {"text": "这块布的短期不够做一件衣服。", "explanation": "这里应该用〈短〉。短期只指时间，不用来形容布料的长短。"}, {"text": "这条河的短期太短，船开不进去。", "explanation": "这里应该用〈长度〉。短期只指时间，不指河流的长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他短期内的学会了开车。", "corrected_sentence": "他短期内学会了开车。", "error_description": "错误：「短期内的学会」；正确：「短期内学会」。「短期内」是时间状语，后面直接接动词，不加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店很短期内就关门了。", "corrected_sentence": "这家店短期内就关门了。", "error_description": "错误：“很”不能修饰时间状语“短期内”；去掉“很”即可，“短期内”直接修饰后面的动词短语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
