INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90605, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "计是想一想，算一算。", "primary_collocate": null, "pronunciation": "jì", "ipa": "tɕi˥˩", "syllable_count": 1, "sentences": [{"text": "工资按小时计。", "target_word": "计", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "停车费按天计。", "target_word": "计", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "门票按人数计，每人五十元。", "target_word": "计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛不计分，大家放心玩。", "target_word": "计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运费按重量计，越重越贵。", "target_word": "计", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电话费按分钟计。", "target_word": "计", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "加班的时间也要计进工资里。", "target_word": "计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的菜按份计，不按斤计。", "target_word": "计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次的损失不计在内。", "target_word": "计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的年龄按岁计，小的按周计。", "target_word": "计", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "计算", "label": "复合"}, {"form": "计较", "label": "复合"}, {"form": "計", "label": "繁体"}], "register": "书面", "sense_fingerprint": "计：想一想，算一算，按单位计算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4d7aeb-bdb3-4b50-b630-bfe4d39c60e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90605, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "计", "is_correct": true, "explanation": "计（jì，第四声）：想一想、算一算，按单位计算。"}, {"text": "机", "is_correct": false, "explanation": "机（jī，第一声）与计声调不同，意思是机器。"}, {"text": "积", "is_correct": false, "explanation": "积（jī，第一声）与计声调不同，意思是积累。"}, {"text": "极", "is_correct": false, "explanation": "极（jí，第二声）与计声调不同，意思是极端。"}, {"text": "戏", "is_correct": false, "explanation": "戏（xì，第四声）与计（jì）声母不同（x 与 j），声调相同，意思是戏剧。"}], "explanations": {"计": "计（jì，第四声）：想一想、算一算，按单位计算。", "机": "机（jī，第一声）与计声调不同，意思是机器。", "积": "积（jī，第一声）与计声调不同，意思是积累。", "极": "极（jí，第二声）与计声调不同，意思是极端。", "戏": "戏（xì，第四声）与计（jì）声母不同（x 与 j），声调相同，意思是戏剧。"}, "sentence_index": null, "correct_answer": "计"}, "level_3": {"options": [{"text": "计", "is_correct": true, "explanation": "正确：计表示按……计算，“工资按小时计”即按小时算。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱与计算工资无关，“工资按小时唱”不通。"}, {"text": "跑", "is_correct": false, "explanation": "语义：跑与计算工资无关，“工资按小时跑”不通。"}, {"text": "看", "is_correct": false, "explanation": "搭配：“按……看”不用于表示计算工资的单位。"}], "explanations": {"计": "正确：计表示按……计算，“工资按小时计”即按小时算。", "唱": "语义：唱与计算工资无关，“工资按小时唱”不通。", "跑": "语义：跑与计算工资无关，“工资按小时跑”不通。", "看": "搭配：“按……看”不用于表示计算工资的单位。"}, "sentence_index": 0, "correct_answer": "计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔账计在我头上。", "explanation": "这里应该用〈算〉。“算在……头上”是固定说法，“计”不这样搭配。"}, {"text": "他计了一杯水，慢慢地喝。", "explanation": "这里应该用〈倒〉。“计”表示计算、思考，不能表示倒水。"}, {"text": "我把名字计在纸上。", "explanation": "这里应该用〈写〉。“计”表示计算，不能表示把字写在纸上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90605, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "计", "is_correct": true, "explanation": "计（jì，第四声）：想一想、算一算，按单位计算。"}, {"text": "击", "is_correct": false, "explanation": "击（jī，第一声）与计声调不同，意思是打击。"}, {"text": "鸡", "is_correct": false, "explanation": "鸡（jī，第一声）与计声调不同，意思是鸡。"}, {"text": "急", "is_correct": false, "explanation": "急（jí，第二声）与计声调不同，意思是着急。"}, {"text": "气", "is_correct": false, "explanation": "气（qì，第四声）与计（jì）声母不同（q 与 j），声调相同，意思是空气。"}], "explanations": {"计": "计（jì，第四声）：想一想、算一算，按单位计算。", "击": "击（jī，第一声）与计声调不同，意思是打击。", "鸡": "鸡（jī，第一声）与计声调不同，意思是鸡。", "急": "急（jí，第二声）与计声调不同，意思是着急。", "气": "气（qì，第四声）与计（jì）声母不同（q 与 j），声调相同，意思是空气。"}, "sentence_index": null, "correct_answer": "计"}, "level_3": {"options": [{"text": "计", "is_correct": true, "explanation": "正确：计进表示计入，“计进工资里”与句意相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝与计入工资无关，“喝进工资里”句子不通。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔不能表示计入工资，“扔进工资里”与句意冲突。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃与计入工资无关，“吃进工资里”句子不通。"}], "explanations": {"计": "正确：计进表示计入，“计进工资里”与句意相符。", "喝": "语义：喝与计入工资无关，“喝进工资里”句子不通。", "扔": "语义：扔不能表示计入工资，“扔进工资里”与句意冲突。", "吃": "语义：吃与计入工资无关，“吃进工资里”句子不通。"}, "sentence_index": 6, "correct_answer": "计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "衣服计在衣架上。", "explanation": "这里应该用〈挂〉。“计”表示计算，不能表示把衣服挂在衣架上。"}, {"text": "他计了一件新衣服，明天就换上。", "explanation": "这里应该用〈穿〉。“计”表示计算、想一想，不能表示穿衣服。"}, {"text": "货物计在箱子里。", "explanation": "这里应该用〈装〉。“计”表示计算，不能表示把货物装进箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车费公里计，每公里三元。", "corrected_sentence": "车费按公里计，每公里三元。", "error_description": "错误在于省略了“按”。“计”前需用“按”引出计算单位，应说“按公里计”，省略“按”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔钱要计出账本里。", "corrected_sentence": "这笔钱要计进账本里。", "error_description": "错误在于补语“出”。表示计入账本时应说“计进”，“计出”表示算出，与句意不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
