INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90612, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "富裕", "is_correct": true, "explanation": "富裕与贫困互为反义，指国家或地区经济状况宽裕、物资充足。"}, {"text": "健壮", "is_correct": false, "explanation": "健壮形容人的体格强壮，与“贫困”不构成反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰形容事物分明，与“贫困”不构成反义关系。"}, {"text": "灵活", "is_correct": false, "explanation": "灵活形容动作或思路敏捷，与“贫困”不构成反义关系。"}], "correct_answer": "富裕", "explanations": {"富裕": "富裕与贫困互为反义，指国家或地区经济状况宽裕、物资充足。", "健壮": "健壮形容人的体格强壮，与“贫困”不构成反义关系。", "清晰": "清晰形容事物分明，与“贫困”不构成反义关系。", "灵活": "灵活形容动作或思路敏捷，与“贫困”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
