INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90612, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "生活困难，缺乏钱财和物资。", "primary_collocate": null, "pronunciation": "pín kùn", "ipa": "pʰin˧˥ kʰuən˥˩", "syllable_count": 2, "sentences": [{"text": "这个山区很贫困，缺少水和电。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贫困的村子里没有医院，也没有学校。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府帮助贫困的地区修了新路。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争以后，这个国家变得很贫困。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人想帮助那些生活贫困的人。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的人们生活很贫困，缺少药品和粮食。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里很贫困，冬天很多人没有煤烧。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家很贫困，粮食和药品都不够。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，这座小城缺水缺粮，非常贫困。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们捐了衣服，送到贫困的山村。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "貧困", "label": "繁体"}, {"form": "贫困户", "label": "复合"}, {"form": "贫困地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "地区或人群生活困难，缺少钱财和物资", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e60a67-5d39-493a-b9c5-106ceed17226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贫困", "is_correct": true, "explanation": "贫困：形容山区生活困难，与“缺少水和电”一致。"}, {"text": "繁华", "is_correct": false, "explanation": "语义：“繁华”指热闹兴旺，与“缺少水和电”的落后状况矛盾。"}, {"text": "健壮", "is_correct": false, "explanation": "搭配：“健壮”形容人的体格，不用来形容山区。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的才智，不用来形容山区。"}], "explanations": {"贫困": "贫困：形容山区生活困难，与“缺少水和电”一致。", "繁华": "语义：“繁华”指热闹兴旺，与“缺少水和电”的落后状况矛盾。", "健壮": "搭配：“健壮”形容人的体格，不用来形容山区。", "聪明": "搭配：“聪明”形容人的才智，不用来形容山区。"}, "sentence_index": 0, "correct_answer": "贫困"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条山路很贫困，汽车根本开不过去。", "explanation": "这里应该用〈崎岖〉。贫困形容生活条件，形容山路高低不平、难走要用〈崎岖〉。"}, {"text": "这条山路很贫困，汽车根本开不过去。", "explanation": "这里应该用〈艰难〉。贫困形容生活条件，路况险峻要用〈艰难〉。"}, {"text": "这次会议的气氛很贫困，大家都不说话。", "explanation": "这里应该用〈沉闷〉。贫困指生活缺钱财物资，形容会场气氛不活跃要用〈沉闷〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贫困", "is_correct": true, "explanation": "贫困：形容这里生活困难，与“很多人没有煤烧”一致。"}, {"text": "富足", "is_correct": false, "explanation": "语义：“富足”指物资充裕，与“很多人没有煤烧”矛盾。"}, {"text": "繁华", "is_correct": false, "explanation": "语义：“繁华”指热闹兴旺，与“很多人没有煤烧”矛盾。"}, {"text": "老成", "is_correct": false, "explanation": "搭配：“老成”形容人的举止稳重，不用来形容地方。"}], "explanations": {"贫困": "贫困：形容这里生活困难，与“很多人没有煤烧”一致。", "富足": "语义：“富足”指物资充裕，与“很多人没有煤烧”矛盾。", "繁华": "语义：“繁华”指热闹兴旺，与“很多人没有煤烧”矛盾。", "老成": "搭配：“老成”形容人的举止稳重，不用来形容地方。"}, "sentence_index": 6, "correct_answer": "贫困"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "最近的工作很贫困，常常要加班到深夜。", "explanation": "这里应该用〈紧张〉。贫困指生活缺钱财物资，工作节奏紧迫要用〈紧张〉。"}, {"text": "他的衣服很贫困，冬天穿着很冷。", "explanation": "这里应该用〈单薄〉。贫困不能形容衣服，衣物薄要用〈单薄〉。"}, {"text": "这道菜的口味很贫困，一点都不好吃。", "explanation": "这里应该用〈寡淡〉。贫困不形容口味，味道淡而无味要用〈寡淡〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
