INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90613, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "强国是很有力量、很厉害的国家。", "primary_collocate": null, "pronunciation": "qiáng guó", "ipa": "tɕʰjɑŋ˧˥ kwo˧˥", "syllable_count": 2, "sentences": [{"text": "美国是世界上有名的强国。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弱国常常怕强国。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，这个小国的旁边有一个强国。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年前，这里的人都想让自己的国家变成强国。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强国的军队很多，武器也很好。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家想做强国，就要让人们都吃饱。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小国和强国一起开会，大家都坐着说话。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的国家已经是一个强国了。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个强国，不只有钱，还要有好朋友。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：“世界上哪些国家是强国？”", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "強國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很有力量、很厉害的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd51ad7a1-a286-491d-9bbd-bb1f05a74ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90613, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城市", "is_correct": false, "explanation": "语义：美国是国家，不是城市，「美国是世界上有名的城市」句意不通。"}, {"text": "弱国", "is_correct": false, "explanation": "语义：「弱国」与「强国」意思相反，与「有名的」冲突，美国不是有名的弱国。"}, {"text": "大陆", "is_correct": false, "explanation": "搭配：「有名的」多修饰国家或城市，「大陆」是地理概念，不说有名的大陆。"}, {"text": "强国", "is_correct": true, "explanation": "正确。「强国」指很有力量、很厉害的国家，美国符合这一点。"}], "explanations": {"城市": "语义：美国是国家，不是城市，「美国是世界上有名的城市」句意不通。", "弱国": "语义：「弱国」与「强国」意思相反，与「有名的」冲突，美国不是有名的弱国。", "大陆": "搭配：「有名的」多修饰国家或城市，「大陆」是地理概念，不说有名的大陆。", "强国": "正确。「强国」指很有力量、很厉害的国家，美国符合这一点。"}, "sentence_index": 0, "correct_answer": "强国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车很有力量，是一个强国。", "explanation": "应该用〈强劲〉。「强国」只指国家，不指汽车。"}, {"text": "这支足球队是全市的强国。", "explanation": "应该用〈强队〉。「强国」指国家，不指球队，这里不能这样用。"}, {"text": "他是我们班的强国。", "explanation": "应该用〈尖子〉或〈强者〉。「强国」只指国家，不指人，不能用来称呼同学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90613, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学校", "is_correct": false, "explanation": "语义：学校不是国家，不能与小国一起开会。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：「花园」不能参加会议，「开会」的参与者应是国家。"}, {"text": "行星", "is_correct": false, "explanation": "语义：行星不是国家，无法与小国一起开会。"}, {"text": "强国", "is_correct": true, "explanation": "正确。「强国」与「小国」形成对比，指力量强大的国家，可以参加会议。"}], "explanations": {"学校": "语义：学校不是国家，不能与小国一起开会。", "花园": "搭配：「花园」不能参加会议，「开会」的参与者应是国家。", "行星": "语义：行星不是国家，无法与小国一起开会。", "强国": "正确。「强国」与「小国」形成对比，指力量强大的国家，可以参加会议。"}, "sentence_index": 6, "correct_answer": "强国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小镇是一个强国。", "explanation": "应该用〈名镇〉。「强国」指国家，不指小镇。"}, {"text": "这支部队是一个强国。", "explanation": "应该用〈强军〉。「强国」只指国家，不指部队。"}, {"text": "这家公司在世界上是一个强国。", "explanation": "应该用〈巨头〉。「强国」指国家，不指公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "日本是东亚的一条强国。", "corrected_sentence": "日本是东亚的一个强国。", "error_description": "量词错误：「强国」是国家，应用「个」，不用「条」。正确说法是「一个强国」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家很强国。", "corrected_sentence": "这个国家是一个强国。", "error_description": "词性错误：「强国」是名词，前面不能用「很」修饰；应说「是一个强国」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
