INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90614, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "经济、军事等方面力量强大的国家。", "primary_collocate": null, "pronunciation": "qiáng guó", "ipa": "tɕʰjɑŋ˧˥ kwo˧˥", "syllable_count": 2, "sentences": [{"text": "这个国家的经济和军事都很强，是世界强国。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济强国的公司，在很多地方都有工厂。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是研究强国历史的老师。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个强国的军队，有很多新武器。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个国家的经济好了，才能变成强国。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个强国在经济上有很多合作。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军事强国未必在经济上领先。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个强国卖给别的国家很多汽车。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小国经济不好时，常常要问强国借钱。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，几个强国明天开会谈经济。", "target_word": "强国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "強國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "经济、军事等方面力量强大的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd51ad7a1-a286-491d-9bbd-bb1f05a74ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90614, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "搭配：「世界」后接国家，不能接「厨房」，句意不通。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是国家，「是世界玩具」与前文的经济和军事描述不符。"}, {"text": "弱国", "is_correct": false, "explanation": "语义：「弱国」与「很强」相反，与句中描述冲突。"}, {"text": "强国", "is_correct": true, "explanation": "正确。「强国」指经济、军事等方面力量强大的国家，与句中描述相符。"}], "explanations": {"厨房": "搭配：「世界」后接国家，不能接「厨房」，句意不通。", "玩具": "语义：玩具不是国家，「是世界玩具」与前文的经济和军事描述不符。", "弱国": "语义：「弱国」与「很强」相反，与句中描述冲突。", "强国": "正确。「强国」指经济、军事等方面力量强大的国家，与句中描述相符。"}, "sentence_index": 0, "correct_answer": "强国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司是一个经济强国。", "explanation": "应该用〈经济巨头〉。「经济强国」指国家，不指公司。"}, {"text": "这所学校是全市的强国。", "explanation": "应该用〈强校〉。「强国」指国家，不指学校。"}, {"text": "这个国家人口很多，是人口强国。", "explanation": "应该用〈大国〉。强国说的是力量，说人口多要用〈人口大国〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "搭配：「军事」不修饰「花园」，「军事花园」说不通。"}, {"text": "行星", "is_correct": false, "explanation": "语义：行星不是国家，无法谈军事或经济上的强弱。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不是国家，句子讨论的是国家的实力。"}, {"text": "强国", "is_correct": true, "explanation": "正确。「军事强国」与「经济强国」对比，说明两者不一定相同。"}], "explanations": {"花园": "搭配：「军事」不修饰「花园」，「军事花园」说不通。", "行星": "语义：行星不是国家，无法谈军事或经济上的强弱。", "饼干": "语义：饼干不是国家，句子讨论的是国家的实力。", "强国": "正确。「军事强国」与「经济强国」对比，说明两者不一定相同。"}, "sentence_index": 6, "correct_answer": "强国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村子是一个经济强国。", "explanation": "应该用〈经济强村〉。「经济强国」指国家，不指村子。"}, {"text": "这家商店在这条街上是一个强国。", "explanation": "应该用〈大商家〉。「强国」指国家，不指商店。"}, {"text": "这个学生的成绩很好，是班里的强国。", "explanation": "应该用〈尖子〉。「强国」只指国家，不指学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家的经济很好，是一只经济强国。", "corrected_sentence": "这个国家的经济很好，是一个经济强国。", "error_description": "量词错误：「经济强国」指国家，应用「个」，不用「只」。正确说法是「是一个经济强国」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个国家都很经济强国。", "corrected_sentence": "两个国家都是经济强国。", "error_description": "词性错误：「经济强国」是名词，前面不能用「很」修饰；应说「都是经济强国」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
