INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90618, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻达到目的所经过的方法或渠道。", "primary_collocate": null, "pronunciation": "tú jìng", "ipa": "tʰu˧˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "网络是获取信息的重要途径。", "target_word": "途径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书是增长知识的好途径。", "target_word": "途径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他通过正当途径赚钱。", "target_word": "途径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "解决这个问题还有别的途径吗？", "target_word": "途径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行是了解不同文化的途径。", "target_word": "途径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一个练习口语的途径。", "target_word": "途径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是通过什么途径知道这件事的？", "target_word": "途径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛是提高水平的途径之一。", "target_word": "途径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用各种途径联系了那位老人。", "target_word": "途径", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给学生提供了很多交流途径。", "target_word": "途径", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "通用", "sense_fingerprint": "比喻达到目的所经过的方法或渠道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628153f8-23f4-4783-aca5-17ac6551aa7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90618, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "途径", "is_correct": true, "explanation": "正确。“途径”指获取信息的渠道，与“重要”和“获取信息”搭配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是获取信息的渠道，“获取信息的重要天气”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用来获取信息，句子意思不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“重要”不修饰“脾气”，“重要的脾气”不成立。"}], "explanations": {"途径": "正确。“途径”指获取信息的渠道，与“重要”和“获取信息”搭配。", "天气": "语义：天气不是获取信息的渠道，“获取信息的重要天气”说不通。", "颜色": "语义：颜色不能用来获取信息，句子意思不通。", "脾气": "搭配：“重要”不修饰“脾气”，“重要的脾气”不成立。"}, "sentence_index": 0, "correct_answer": "途径"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们用途径修好了车。", "explanation": "这里应该用〈工具〉。“途径”指路径或达到目的的办法，修车用的器具要用〈工具〉，不能说“用途径修车”。"}, {"text": "这个途径很感人。", "explanation": "这里应该用〈故事〉。“途径”指路或办法，不能用来形容感人的内容，形容感人的内容要用〈故事〉。"}, {"text": "他用幽默的途径说话。", "explanation": "这里应该用〈方式〉。“途径”指达到目的的办法或渠道，说话的样子要用〈方式〉，不能说“用幽默的途径说话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "途径", "is_correct": true, "explanation": "正确。“通过什么途径”指通过什么渠道，与“知道这件事”搭配。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情不是获知事情的渠道，“通过什么感情知道这件事”说不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不能用来获知事情，句子意思不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“通过”后接“时间”不成立，不能说“通过什么时间知道”。"}], "explanations": {"途径": "正确。“通过什么途径”指通过什么渠道，与“知道这件事”搭配。", "感情": "语义：感情不是获知事情的渠道，“通过什么感情知道这件事”说不通。", "心情": "语义：心情不能用来获知事情，句子意思不通。", "时间": "搭配：“通过”后接“时间”不成立，不能说“通过什么时间知道”。"}, "sentence_index": 6, "correct_answer": "途径"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他走了一条很长的途径才到家。", "explanation": "这里应该用〈路〉。“途径”是比喻的办法或渠道，实际走的道路要用〈路〉。"}, {"text": "这次考试的途径很好，我得了九十分。", "explanation": "这里应该用〈成绩〉。“途径”指达到目的的办法，考试得的分数要用〈成绩〉。"}, {"text": "我把书放在途径上了。", "explanation": "这里应该用〈桌子〉。“途径”是抽象的渠道，不能放东西，放书的地方要用〈桌子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想找一张适合自己的学习途径。", "corrected_sentence": "他想找一条适合自己的学习途径。", "error_description": "错误形式是量词“一张”，正确形式是“一条”。“途径”是抽象的办法或渠道，量词用“条”或“种”，不用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校提供了两本交流途径。", "corrected_sentence": "学校提供了两条交流途径。", "error_description": "错误形式是量词“两本”，正确形式是“两条”。“途径”是抽象的渠道，量词用“条”或“种”，不用“本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
