INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90619, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "彩虹是下雨以后天上出现的彩色的弯弯的桥。", "primary_collocate": null, "pronunciation": "cǎi hóng", "ipa": "tsʰaɪ˨˩˦ xʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "天上的彩虹像一座彩色的桥。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带我去公园看彩虹。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨一停，彩虹就出来了。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我画了一道彩虹，还画了太阳。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗望着天上的彩虹。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彩虹弯弯的，像一座桥。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，那边有彩虹！", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，我们一起等彩虹。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下雨，也许会有彩虹。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥说他从没见过彩虹。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道彩虹", "label": "量词"}, {"form": "彩虹桥", "label": "复合"}], "register": "中性", "sense_fingerprint": "下雨以后天上彩色的弯弯的桥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc33cf92-9150-4ca4-818a-13201fe562bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90619, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彩虹", "is_correct": true, "explanation": "正确。下雨以后天上彩色的弯弯的桥就是彩虹，与“像一座彩色的桥”相符。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是无色的水滴，不能像一座彩色的桥。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是实物，不会出现在天上像一座彩色的桥。"}, {"text": "小鸟", "is_correct": false, "explanation": "搭配：“像一座彩色的桥”是拿天空中的景象作比，小鸟不能这样比作桥。"}], "explanations": {"彩虹": "正确。下雨以后天上彩色的弯弯的桥就是彩虹，与“像一座彩色的桥”相符。", "雨水": "语义：雨水是无色的水滴，不能像一座彩色的桥。", "石头": "语义：石头是实物，不会出现在天上像一座彩色的桥。", "小鸟": "搭配：“像一座彩色的桥”是拿天空中的景象作比，小鸟不能这样比作桥。"}, "sentence_index": 0, "correct_answer": "彩虹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她头上扎着一条彩虹。", "explanation": "这里应该用〈彩带〉。彩带是布条或纸条，可以扎在头上；彩虹是天空中的光，不能扎在头上。"}, {"text": "他推开了彩虹。", "explanation": "这里应该用〈门〉。推开的是门，彩虹不是可以推开的东西。"}, {"text": "下雨了，他撑起了彩虹。", "explanation": "这里应该用〈伞〉。撑起的是伞，彩虹不能用来撑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90619, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彩虹", "is_correct": true, "explanation": "正确。“你看，那边有彩虹！”指的是能看见的彩色光带，与“你看”相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，不能用“你看，那边有”来指。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“你看”指的是看得见的事物，“声音”不能用“看”来感知。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道要用鼻子闻，不能用“你看”来指。"}], "explanations": {"彩虹": "正确。“你看，那边有彩虹！”指的是能看见的彩色光带，与“你看”相符。", "空气": "语义：空气看不见，不能用“你看，那边有”来指。", "声音": "搭配：“你看”指的是看得见的事物，“声音”不能用“看”来感知。", "味道": "语义：味道要用鼻子闻，不能用“你看”来指。"}, "sentence_index": 6, "correct_answer": "彩虹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "哥哥说他从没见过一只彩虹。", "explanation": "这里应该用〈道〉。“只”多用于动物，彩虹前应说“一道彩虹”。"}, {"text": "哥哥说他从没见过一块彩虹。", "explanation": "这里应该用〈道〉。“块”用于成块的东西，彩虹不是一块一块的，应说“一道彩虹”。"}, {"text": "哥哥说他从没见过一本彩虹。", "explanation": "这里应该用〈道〉。“本”用于书本，彩虹前应说“一道彩虹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90619, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天上有一只彩虹，像一座彩色的桥。", "corrected_sentence": "天上有一道彩虹，像一座彩色的桥。", "error_description": "“彩虹”前的量词应用“道”，不用“只”；“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90619, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是天上得彩虹，很美。", "corrected_sentence": "这是天上的彩虹，很美。", "error_description": "错误：“得”。正确：“的”。彩虹前的修饰语要用结构助词“的”，“得”用于动词后作补语，不能用在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
