INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90620, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雨后天空中出现的弧形七色光带。", "primary_collocate": null, "pronunciation": "cǎi hóng", "ipa": "tsʰaɪ˨˩˦ xʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "雨停了，天上出现了一道彩虹。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们指着天空的彩虹笑了。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彩虹有红橙黄绿蓝靛紫七种颜色。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下过雨以后，我们看到了彩虹。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彩虹出现在太阳对面的天空。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机拍下了美丽的彩虹。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的彩虹是弯弯的。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的雨后，常常能看到彩虹。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彩虹慢慢消失了。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画里的彩虹有七种颜色。", "target_word": "彩虹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道彩虹", "label": "量词"}, {"form": "彩虹桥", "label": "复合"}], "register": "中性", "sense_fingerprint": "雨后天空中出现的弧形七色光带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc33cf92-9150-4ca4-818a-13201fe562bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彩虹", "is_correct": true, "explanation": "正确。彩虹是雨后天空中出现的弧形七色光带，与“雨停了，天上出现了一道”相符。"}, {"text": "雷声", "is_correct": false, "explanation": "语义：雷声是声音，听得见但看不见，不能说天上出现了一道雷声。"}, {"text": "雪花", "is_correct": false, "explanation": "语义：雨停了天上不会出现雪花，雪花也不是这样出现的。"}, {"text": "冰雹", "is_correct": false, "explanation": "搭配：“一道”多用于光、线、墙、河等，冰雹不能用“一道”来数。"}], "explanations": {"彩虹": "正确。彩虹是雨后天空中出现的弧形七色光带，与“雨停了，天上出现了一道”相符。", "雷声": "语义：雷声是声音，听得见但看不见，不能说天上出现了一道雷声。", "雪花": "语义：雨停了天上不会出现雪花，雪花也不是这样出现的。", "冰雹": "搭配：“一道”多用于光、线、墙、河等，冰雹不能用“一道”来数。"}, "sentence_index": 0, "correct_answer": "彩虹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里亮着彩虹，很暖和。", "explanation": "这里应该用〈灯光〉。彩虹只出现在雨后的天空，不会亮在屋里。"}, {"text": "这座桥是彩虹做的。", "explanation": "这里应该用〈钢铁〉。彩虹是天上的光带，不是建桥的材料。"}, {"text": "夜空中闪着彩虹。", "explanation": "这里应该用〈星星〉。彩虹出现在雨后白天的天空，不会在夜空中闪烁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彩虹", "is_correct": true, "explanation": "正确。雨后的彩虹是弯弯的，与“雨后”和“弯弯的”相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是圆的光源，不说雨后的太阳是弯弯的。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑物，雨后不会说房子是弯弯的。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“雨后”后面接的多是天空中的景象，“小猫”不能这样搭配。"}], "explanations": {"彩虹": "正确。雨后的彩虹是弯弯的，与“雨后”和“弯弯的”相符。", "太阳": "语义：太阳是圆的光源，不说雨后的太阳是弯弯的。", "房子": "语义：房子是建筑物，雨后不会说房子是弯弯的。", "小猫": "搭配：“雨后”后面接的多是天空中的景象，“小猫”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "彩虹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天上挂着一把彩虹，很美。", "explanation": "这里应该用〈道〉。“把”多用于有柄的东西，彩虹前应说“一道彩虹”。"}, {"text": "天上挂着一只彩虹，很美。", "explanation": "这里应该用〈道〉。“只”多用于动物，彩虹前应说“一道彩虹”。"}, {"text": "天上挂着一本彩虹，很美。", "explanation": "这里应该用〈道〉。“本”用于书本，彩虹前应说“一道彩虹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨后的傍晚，天边出现了一只彩虹。", "corrected_sentence": "雨后的傍晚，天边出现了一道彩虹。", "error_description": "量词用错：“只”多用于动物，“彩虹”应说“一道彩虹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候见过一张彩虹。", "corrected_sentence": "我小时候见过一道彩虹。", "error_description": "量词用错：“张”用于纸、桌子等平面的东西，“彩虹”应说“一道彩虹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ebe08f-246a-4f02-9018-729a6ce2c78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
