INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90621, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人在公司里做的工作和位置。", "primary_collocate": null, "pronunciation": "zhí wèi", "ipa": "ʈʂɨ˧˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "他在公司的职位是经理。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在的职位是什么？", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个职位需要会说英语。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她换了新的职位，工资也高了。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想申请销售职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的职位比我高一级。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司为他准备了新职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个职位已经有人了。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找一个适合自己的职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这家公司换过三个职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "職位", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公司里某人担任的工作岗位和级别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3664d668-2958-407a-84af-382c04e663fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90621, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职位", "is_correct": true, "explanation": "正确：职位指公司里的工作岗位，与“是经理”相符。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位指坐的地方，不是人的职务，不能说“座位是经理”。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：办公室指房间，不是岗位，不能用“是经理”来指称。"}, {"text": "性别", "is_correct": false, "explanation": "配价：“性别”后接“是男/女”，不接职务名称“经理”。"}], "explanations": {"职位": "正确：职位指公司里的工作岗位，与“是经理”相符。", "座位": "语义：座位指坐的地方，不是人的职务，不能说“座位是经理”。", "办公室": "语义：办公室指房间，不是岗位，不能用“是经理”来指称。", "性别": "配价：“性别”后接“是男/女”，不接职务名称“经理”。"}, "sentence_index": 0, "correct_answer": "职位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天的职位很好吃。", "explanation": "这里应该用〈饭菜〉。职位指岗位和级别，不能用“好吃”来形容。"}, {"text": "这个职位很难完成。", "explanation": "这里应该用〈任务〉。职位指岗位和级别，不是要去完成的事情，不能说“很难完成”。"}, {"text": "他有参加比赛的职位。", "explanation": "这里应该用〈资格〉。职位指机构中的岗位，不指参加活动的条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08207e-ba0d-47c1-91ac-7fbdd82699f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90621, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职位", "is_correct": true, "explanation": "正确：职位是公司为他安排的工作岗位，与“准备了新”相符。"}, {"text": "学期", "is_correct": false, "explanation": "语义：学期是学校的时间单位，公司不设学期，不能准备。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房属于医院，与公司无关，不能说“准备了新病房”。"}, {"text": "春天", "is_correct": false, "explanation": "搭配：“准备”后接具体物品或计划，不接季节。"}], "explanations": {"职位": "正确：职位是公司为他安排的工作岗位，与“准备了新”相符。", "学期": "语义：学期是学校的时间单位，公司不设学期，不能准备。", "病房": "语义：病房属于医院，与公司无关，不能说“准备了新病房”。", "春天": "搭配：“准备”后接具体物品或计划，不接季节。"}, "sentence_index": 6, "correct_answer": "职位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书架上的职位很合适。", "explanation": "这里应该用〈位置〉。职位指工作岗位，不指物体所在的地方。"}, {"text": "电影院的职位已经坐满了。", "explanation": "这里应该用〈座位〉。职位指工作岗位，不能说“坐满”。"}, {"text": "他有投票的职位。", "explanation": "这里应该用〈权利〉。职位指工作岗位，不指法律规定的权利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08207e-ba0d-47c1-91ac-7fbdd82699f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90621, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在这家公司担任一本技术职位。", "corrected_sentence": "他在这家公司担任一个技术职位。", "error_description": "量词错误：“职位”应用量词“个”，不能用“本”。正确说法是“一个技术职位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08207e-ba0d-47c1-91ac-7fbdd82699f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90621, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在这个部门换着一次职位。", "corrected_sentence": "她在这个部门换过一次职位。", "error_description": "“着”误用：“换”后表示曾经发生过应用“过”，“着”表示动作持续，与“一次”的完成意义矛盾。正确说法是“换过一次职位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08207e-ba0d-47c1-91ac-7fbdd82699f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
