INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90622, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机构中的工作岗位及其地位。", "primary_collocate": null, "pronunciation": "zhí wèi", "ipa": "ʈʂɨ˧˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "他在政府里有重要的职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长的职位很重要。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠努力得到了现在的职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里这个职位需要有经验的人。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的职位不高，但很受尊敬。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学有一个空着的职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开了军队，放弃了原来的职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在学校的职位是老师。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长这个职位责任很大。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用关系得到一个更高的职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "職位", "label": "繁体"}], "register": "中性", "sense_fingerprint": "政府、学校、医院等机构中的岗位及其地位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3664d668-2958-407a-84af-382c04e663fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职位", "is_correct": true, "explanation": "正确：职位指政府中的岗位，与“重要的”搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是政府里的岗位，“重要的颜色”说不通。"}, {"text": "草坪", "is_correct": false, "explanation": "语义：草坪是一片草地，不能是政府中的岗位。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“有重要的体重”不成立，“体重”不能与“有重要的”搭配。"}], "explanations": {"职位": "正确：职位指政府中的岗位，与“重要的”搭配自然。", "颜色": "语义：颜色不是政府里的岗位，“重要的颜色”说不通。", "草坪": "语义：草坪是一片草地，不能是政府中的岗位。", "体重": "搭配：“有重要的体重”不成立，“体重”不能与“有重要的”搭配。"}, "sentence_index": 0, "correct_answer": "职位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的职位很开朗。", "explanation": "这里应该用〈性格〉。职位指岗位，不能用来形容人的性情。"}, {"text": "这辆车的职位很快。", "explanation": "这里应该用〈速度〉。职位指机构中的岗位，不能用来形容车辆的快慢。"}, {"text": "这个职位很便宜。", "explanation": "这里应该用〈价格〉。职位指岗位，不能用“便宜”来形容，说价钱低才用“便宜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08207e-ba0d-47c1-91ac-7fbdd82699f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职位", "is_correct": true, "explanation": "正确：职位是机构中的岗位，与“放弃了原来的”搭配自然。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被放弃，不能说“放弃了原来的天气”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“放弃”后不接“年龄”，年龄不能被放弃。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“放弃了原来的体重”不成立，体重不说放弃。"}], "explanations": {"职位": "正确：职位是机构中的岗位，与“放弃了原来的”搭配自然。", "天气": "语义：天气不能被放弃，不能说“放弃了原来的天气”。", "年龄": "搭配：“放弃”后不接“年龄”，年龄不能被放弃。", "体重": "搭配：“放弃了原来的体重”不成立，体重不说放弃。"}, "sentence_index": 6, "correct_answer": "职位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的职位很好。", "explanation": "这里应该用〈天气〉。职位指岗位，不能用来形容天气。"}, {"text": "这首歌歌手的职位很好听。", "explanation": "这里应该用〈声音〉。职位指岗位，不能用“好听”来形容。"}, {"text": "这件衣服的职位很漂亮。", "explanation": "这里应该用〈颜色〉。职位指岗位，不能用来描述衣服的外观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08207e-ba0d-47c1-91ac-7fbdd82699f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他担任一座重要的职位。", "corrected_sentence": "他担任一个重要的职位。", "error_description": "量词错误：“职位”应用量词“个”，“座”用于山、楼等大型物体。正确说法是“一个重要的职位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08207e-ba0d-47c1-91ac-7fbdd82699f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她换着一次职位。", "corrected_sentence": "她换过一次职位。", "error_description": "“着”误用：“换”后表示曾经换过应用“过”，“着”表示持续状态，与“一次”的完成意义矛盾。正确说法是“换过一次职位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08207e-ba0d-47c1-91ac-7fbdd82699f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
