INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90625, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "过当是做得太多，超过了该有的样子。", "primary_collocate": null, "pronunciation": "guò dàng", "ipa": "kuo̯˥˩ taŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的反应有点过当。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样处理明显过当。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的批评有些过当。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你对孩子的保护有些过当了。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生觉得这次检查过当，没有必要。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话并不过当，只是太直接。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的宣传做得过当，客人反而不信。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对小错误这样重罚，是不是过当？", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的热情已经过当，让人不舒服。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得你的要求有些过当了。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "做得太多，超出了应有的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a22d3499-ca45-4e80-9518-98ccdc905de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90625, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过当", "is_correct": true, "explanation": "“过当”指超过适当的程度，“有点过当”说的是反应太过。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”多形容外貌或做得出色的事，“有点漂亮”是夸赞，与“过当”超出限度的意思相反。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“反应”不能说“干净”，“反应有点干净”不成立。"}, {"text": "空旷", "is_correct": false, "explanation": "语义：“空旷”形容空间开阔，不能修饰“反应”。"}], "explanations": {"过当": "“过当”指超过适当的程度，“有点过当”说的是反应太过。", "漂亮": "语义：“漂亮”多形容外貌或做得出色的事，“有点漂亮”是夸赞，与“过当”超出限度的意思相反。", "干净": "搭配：“反应”不能说“干净”，“反应有点干净”不成立。", "空旷": "语义：“空旷”形容空间开阔，不能修饰“反应”。"}, "sentence_index": 0, "correct_answer": "过当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的表现很过当，值得大家表扬。", "explanation": "这里应该用〈出色〉。“过当”指超出限度，含贬义，不能形容值得称赞的表现。"}, {"text": "这份礼物太过当了，正好合适。", "explanation": "这里应该用〈恰当〉。“过当”指超出限度，不能用来形容恰到好处的礼物。"}, {"text": "这双鞋的大小过当，穿上很舒服。", "explanation": "这里应该用〈合脚〉。“过当”指行为或程度超出限度，不能用来形容鞋子的尺码。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90625, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过当", "is_correct": true, "explanation": "“过当”指超过适当的限度，“做得过当”说的是宣传做得太过。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容场面或环境，不能形容宣传的做法。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不能说“宣传做得咸”。"}, {"text": "慢跑", "is_correct": false, "explanation": "搭配：“做得”之后接描述做法的词语，“慢跑”是动作，“宣传做得慢跑”不成立。"}], "explanations": {"过当": "“过当”指超过适当的限度，“做得过当”说的是宣传做得太过。", "冷清": "语义：“冷清”形容场面或环境，不能形容宣传的做法。", "咸": "搭配：“咸”形容味道，不能说“宣传做得咸”。", "慢跑": "搭配：“做得”之后接描述做法的词语，“慢跑”是动作，“宣传做得慢跑”不成立。"}, "sentence_index": 6, "correct_answer": "过当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次的奖金太少了，有点过当。", "explanation": "这里应该用〈偏少〉。“过当”指超出限度，不能用来形容数额偏少的情况。"}, {"text": "他的身高很过当，让人羡慕。", "explanation": "这里应该用〈高挑〉。“过当”指行为或程度超出限度，不能用来形容身材。"}, {"text": "他说话很过当，大家都很满意。", "explanation": "这里应该用〈中肯〉。“过当”指超出限度，不能用来形容言语得体、令人认可的说话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90625, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她对孩子的管教有些过当得。", "corrected_sentence": "她对孩子的管教有些过当。", "error_description": "补语错误：“过当”后面不能再加补语标记“得”，应说“有些过当”，末尾的“得”要删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90625, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次的处罚定得过当得，员工们很不满。", "corrected_sentence": "这次的处罚定得过当，员工们很不满。", "error_description": "补语错误：“得”引出的补语只需一次，“定得过当”后不能再加“得”，应说“定得过当”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
