INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90626, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "超过适当的限度；过分。", "primary_collocate": null, "pronunciation": "guò dàng", "ipa": "kuo̯˥˩ taŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这样的处罚不算过当。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的玩笑开得过当。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用力过当会受伤。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长的管教不能过当。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打扮得过当，看起来很奇怪。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察的做法没有过当。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的做法过当，引起了大家的反感。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲话过当，大家都不高兴了。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夸奖要适度，不要过当。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的惩罚太重了，有点过当。", "target_word": "过当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "超过适当限度，过分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a22d3499-ca45-4e80-9518-98ccdc905de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90626, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过当", "is_correct": true, "explanation": "“过当”指超过适当的限度，“处罚不算过当”说的是处罚没有过分。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音，不能用来评价处罚。"}, {"text": "圆形", "is_correct": false, "explanation": "语义：“圆形”描述形状，不能用来评价处罚。"}, {"text": "矮小", "is_correct": false, "explanation": "语义：“矮小”形容身高或体型，不能用于处罚。"}], "explanations": {"过当": "“过当”指超过适当的限度，“处罚不算过当”说的是处罚没有过分。", "响亮": "语义：“响亮”形容声音，不能用来评价处罚。", "圆形": "语义：“圆形”描述形状，不能用来评价处罚。", "矮小": "语义：“矮小”形容身高或体型，不能用于处罚。"}, "sentence_index": 0, "correct_answer": "过当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的服务很过当，客人都很满意。", "explanation": "这里应该用〈周到〉。“过当”含贬义，指超出适当限度，不能用来夸奖服务好。"}, {"text": "这个价格很过当，正好合我的预算。", "explanation": "这里应该用〈合理〉。“过当”指超出限度，不能用来形容价钱合适的情况。"}, {"text": "这床被子的厚度很过当，盖起来刚刚好。", "explanation": "这里应该用〈适中〉。“过当”指超出限度，不能用来形容程度恰好的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过当", "is_correct": true, "explanation": "“过当”指超过适当的限度，“做法过当”说的是做法太过。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或颜色，不能形容做法。"}, {"text": "苦涩", "is_correct": false, "explanation": "语义：“苦涩”形容味道或心情，不能形容做法。"}, {"text": "香甜", "is_correct": false, "explanation": "语义：“香甜”形容味道，不能用来形容做法。"}], "explanations": {"过当": "“过当”指超过适当的限度，“做法过当”说的是做法太过。", "明亮": "语义：“明亮”形容光线或颜色，不能形容做法。", "苦涩": "语义：“苦涩”形容味道或心情，不能形容做法。", "香甜": "语义：“香甜”形容味道，不能用来形容做法。"}, "sentence_index": 6, "correct_answer": "过当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次的表扬太轻了，有点过当。", "explanation": "这里应该用〈不足〉。“过当”指超出限度，不能用来形容程度不够的情况。"}, {"text": "这次的比赛成绩很过当，我们都很满意。", "explanation": "这里应该用〈优秀〉。“过当”指超出限度，不能用来形容成绩好。"}, {"text": "这个房间的面积很过当，住起来刚刚好。", "explanation": "这里应该用〈宽敞〉。“过当”指超出限度，不能用来形容面积恰好的房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的批评说得过当得。", "corrected_sentence": "他的批评说得过当。", "error_description": "补语错误：补语标记“得”只能出现一次，“说得过当”后不能再加“得”，应删去末尾的“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他那过当得要求让人很为难。", "corrected_sentence": "他那过当的要求让人很为难。", "error_description": "结构错误：“过当”修饰名词时要用结构助词“的”，不能用补语标记“得”，应说“过当的要求”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
