INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90627, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "有一些，但不知道有多少。", "primary_collocate": null, "pronunciation": "ruò gān", "ipa": "ɻu̯ɔ˥˩ kan˥", "syllable_count": 2, "sentences": [{"text": "桌子上放着若干本书。", "target_word": "若干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议有若干人没来。", "target_word": "若干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在北京住过若干年。", "target_word": "若干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们还有若干问题没有解决。", "target_word": "若干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边停着若干辆车。", "target_word": "若干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过若干天的努力，我们完成了工作。", "target_word": "若干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们若干个题目，要我们分组来做。", "target_word": "若干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里有若干条鱼在游。", "target_word": "若干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子里装着若干个苹果。", "target_word": "若干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上提出了若干意见。", "target_word": "若干", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示有一些，具体数量说不清", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b68f76f-19ce-4182-879c-f07998280520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90627, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "若干", "is_correct": true, "explanation": "正确：若干表示有一些、数量说不清，与“放着……本书”搭配自然。"}, {"text": "每", "is_correct": false, "explanation": "搭配：「每」指逐一的全部，“放着每本书”不自然，要说“每一本”并与“都”呼应。"}, {"text": "哪", "is_correct": false, "explanation": "语义：「哪」是疑问代词，陈述桌上的书时不用它。"}, {"text": "各", "is_correct": false, "explanation": "语义：「各」指分别的每一个，句子说的是不定的数量，而不是逐一分别。"}], "explanations": {"若干": "正确：若干表示有一些、数量说不清，与“放着……本书”搭配自然。", "每": "搭配：「每」指逐一的全部，“放着每本书”不自然，要说“每一本”并与“都”呼应。", "哪": "语义：「哪」是疑问代词，陈述桌上的书时不用它。", "各": "语义：「各」指分别的每一个，句子说的是不定的数量，而不是逐一分别。"}, "sentence_index": 0, "correct_answer": "若干"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想喝若干水。", "explanation": "这里应该用〈一些〉。若干只修饰可以一个个计数的人或事物，不能修饰“水”这样不可数的东西。"}, {"text": "你们班有若干个学生吗？", "explanation": "这里应该用〈几〉。若干用于陈述，不用于疑问句；问数量要说“几个”。"}, {"text": "我们班有若干个学生，一共三十人。", "explanation": "这里人数已经确定，应直接用具体的数词，不能用表示不确定数量的“若干”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90627, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "若干", "is_correct": true, "explanation": "正确：若干表示有一些、数量不确定，符合句意。"}, {"text": "多少", "is_correct": false, "explanation": "语义：「多少」是疑问代词，用来问数量，陈述“老师给了我们”这件事时不用它。"}, {"text": "怎么", "is_correct": false, "explanation": "语法：「怎么」是询问方式的疑问代词，不能放在「个」前修饰名词。"}, {"text": "任一", "is_correct": false, "explanation": "配价：「任一」只能指任选其中一个，不能与“给了我们”一批多个题目相配。"}], "explanations": {"若干": "正确：若干表示有一些、数量不确定，符合句意。", "多少": "语义：「多少」是疑问代词，用来问数量，陈述“老师给了我们”这件事时不用它。", "怎么": "语法：「怎么」是询问方式的疑问代词，不能放在「个」前修饰名词。", "任一": "配价：「任一」只能指任选其中一个，不能与“给了我们”一批多个题目相配。"}, "sentence_index": 6, "correct_answer": "若干"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现在是若干点。", "explanation": "这里应该用〈几〉。若干表示不确定的数量，说具体时间要用「几点」或具体数字，不能说「若干点」。"}, {"text": "他这次考试得了第若干名。", "explanation": "这里应该用〈三〉。名次是确定的，要说具体的序数，如「第三名」；若干不能用于序数。"}, {"text": "我只有若干个妈妈。", "explanation": "这里应该用〈一〉。妈妈只有一个，若干表示不确定的多数，不能修饰唯一的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90627, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了若干水。", "corrected_sentence": "他买了若干杯水。", "error_description": "「若干」后面要接可以计数的个体，不能直接修饰不可数的「水」；应加量词，改为「若干杯水」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90627, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会上提出了若干张意见。", "corrected_sentence": "会上提出了若干条意见。", "error_description": "「意见」的量词要用「条」，「张」多用于纸、桌子等平面的东西，不能用于意见；应说「若干条意见」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
