INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90629, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "必需是说一定要有，少了不行。", "primary_collocate": null, "pronunciation": "bì xū", "ipa": "pi˥˩ ɕy˥", "syllable_count": 2, "sentences": [{"text": "空气对生活是必需的。", "target_word": "必需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭时，盐是必需的。", "target_word": "必需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去海边玩，帽子是必需的。", "target_word": "必需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个城市，车不是必需的。", "target_word": "必需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只买了生活必需的东西。", "target_word": "必需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个学生都有上课必需的本子。", "target_word": "必需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会必需的资料，我已经发给你了。", "target_word": "必需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子成长，爱和时间都是必需的。", "target_word": "必需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这份工作来说，好身体是必需的。", "target_word": "必需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，厚衣服是必需的。", "target_word": "必需", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "必需品", "label": "复合"}], "register": "中性", "sense_fingerprint": "少了不行、一定要有（说明某物对某事不可缺）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52af20df-6e56-40f6-a8c1-0c1dd987e45e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90629, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必需", "is_correct": true, "explanation": "正确：空气是人类生活不可缺少的，“必需”表示一定要有，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来说明“空气”对生活的作用。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：空气不会“拥挤”，这个词与“对生活是……”的说明不相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外观，不能用来评价“空气”对生活的作用。"}], "explanations": {"必需": "正确：空气是人类生活不可缺少的，“必需”表示一定要有，符合句意。", "甜": "搭配：“甜”形容味道，不能用来说明“空气”对生活的作用。", "拥挤": "语义：空气不会“拥挤”，这个词与“对生活是……”的说明不相符。", "漂亮": "搭配：“漂亮”形容外观，不能用来评价“空气”对生活的作用。"}, "sentence_index": 0, "correct_answer": "必需"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的必需很多。", "explanation": "这里应该用〈需求〉。“必需”强调不可缺少，说孩子对关爱、照顾的需求量要用“需求”，不能用“必需”。"}, {"text": "这次比赛很必需。", "explanation": "这里应该用〈重要〉。“必需”强调不可缺少，说比赛的分量要用“重要”。"}, {"text": "这种药有很大的必需。", "explanation": "这里应该用〈需求〉。“必需”不作名词，表示需求量要用“需求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90629, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美味", "is_correct": false, "explanation": "搭配：“美味”形容食物，不能用来修饰“资料”。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：资料不会“高兴”，这与“开会”时需要的内容相矛盾。"}, {"text": "必需", "is_correct": true, "explanation": "正确：开会要用的资料不可缺少，“必需”表示一定要有，符合句意。"}, {"text": "好听", "is_correct": false, "explanation": "搭配：“好听”形容声音，不能用来修饰“资料”。"}], "explanations": {"美味": "搭配：“美味”形容食物，不能用来修饰“资料”。", "高兴": "语义：资料不会“高兴”，这与“开会”时需要的内容相矛盾。", "必需": "正确：开会要用的资料不可缺少，“必需”表示一定要有，符合句意。", "好听": "搭配：“好听”形容声音，不能用来修饰“资料”。"}, "sentence_index": 6, "correct_answer": "必需"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的表现很必需。", "explanation": "这里应该用〈出色〉。“必需”强调不可缺少，评价表现好坏要用“出色”。"}, {"text": "这顿饭的味道很必需。", "explanation": "这里应该用〈好吃〉。“必需”强调不可缺少，说味道好不好要用“好吃”。"}, {"text": "这张照片拍得很必需。", "explanation": "这里应该用〈好看〉。“必需”强调不可缺少，说照片拍得美不美要用“好看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爬山的时候，手套是必需地。", "corrected_sentence": "爬山的时候，手套是必需的。", "error_description": "“必需”作谓语后面要用“的”，应说“是必需的”；“地”用来修饰动词，这里用错了结构助词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏天出门，防晒霜是必需得。", "corrected_sentence": "夏天出门，防晒霜是必需的。", "error_description": "“必需”作谓语时后面要用“的”，应说“是必需的”；“得”用在形容词后面引出补语，这里用错了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
