INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90631, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "金额是钱的数目，有多少钱。", "primary_collocate": null, "pronunciation": "jīn é", "ipa": "tɕin˥ ɤ˧˥", "syllable_count": 2, "sentences": [{"text": "请在这里写上你要付的金额。", "target_word": "金额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张发票上的金额是三百元。", "target_word": "金额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看一下，金额对不对？", "target_word": "金额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一次转了很大的金额。", "target_word": "金额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金额太大的话，银行会打电话问你。", "target_word": "金额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西前，先算一下金额。", "target_word": "金额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把金额写大写，不要写错。", "target_word": "金额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱的金额不小，你要小心保管。", "target_word": "金额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "付款金额不对，所以钱没有转出去。", "target_word": "金额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板看了看账单上的金额，没有说话。", "target_word": "金额", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "总金额", "label": "复合词"}], "register": "中性", "sense_fingerprint": "钱的数目，有多少钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '741a067b-35ee-42ee-a9a5-e70920a0d4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90631, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "搭配：“付的”后面要接钱的数目，不能接人名。"}, {"text": "金额", "is_correct": true, "explanation": "正确：“金额”指要付的钱数，与“付”搭配，符合句意。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”不是钱，“要付的地址”说不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“付”只能支付钱款，不能支付“时间”。"}], "explanations": {"名字": "搭配：“付的”后面要接钱的数目，不能接人名。", "金额": "正确：“金额”指要付的钱数，与“付”搭配，符合句意。", "地址": "语义：“地址”不是钱，“要付的地址”说不通。", "时间": "搭配：“付”只能支付钱款，不能支付“时间”。"}, "sentence_index": 0, "correct_answer": "金额"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他借了很多本书，金额很多。", "explanation": "这里应该用〈数量〉。金额指钱的数目，书的多少要用数量，不能用金额。"}, {"text": "这件衣服的金额很贵。", "explanation": "这里应该用〈价格〉。金额指一笔钱的总数，单件商品的价钱要用价格。"}, {"text": "来参加活动的金额很多。", "explanation": "这里应该用〈人数〉。金额指钱的数目，人的多少要用人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90631, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能被“写大写”，大写只用于数字金额。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”不能写成大写，“大写”指金额数字的写法。"}, {"text": "金额", "is_correct": true, "explanation": "正确：“写大写”的对象是金额，是财务书写的常见用法，符合句意。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”不能写成大写，“写大写”的对象是数字金额。"}], "explanations": {"颜色": "语义：“颜色”不能被“写大写”，大写只用于数字金额。", "味道": "语义：“味道”不能写成大写，“大写”指金额数字的写法。", "金额": "正确：“写大写”的对象是金额，是财务书写的常见用法，符合句意。", "心情": "语义：“心情”不能写成大写，“写大写”的对象是数字金额。"}, "sentence_index": 6, "correct_answer": "金额"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板看了看账单上的一座金额，没有说话。", "explanation": "量词错误：金额应用“笔”计数，“座”用于建筑，不能修饰金额；应说“一笔金额”。"}, {"text": "老板看了看账单上的一朵金额，没有说话。", "explanation": "量词错误：“朵”用于花朵，不能修饰金额；应说“一笔金额”。"}, {"text": "老板看了看账单上的一条金额，没有说话。", "explanation": "量词错误：“条”用于细长的东西，不能修饰金额；应说“一笔金额”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90631, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只金额是五百元。", "corrected_sentence": "这笔金额是五百元。", "error_description": "量词错误：“金额”的量词应为“笔”，说“这笔金额”；“只”用于动物等，不能用于金额。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔钱的金额很贵。", "corrected_sentence": "这笔钱的金额很大。", "error_description": "搭配错误：“金额”说“大”或“小”，不能说“贵”；“贵”用来说东西的价格。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放弃", "is_correct": true, "explanation": "反义：放弃是主动不去行使（权利），与“行使”构成反义关系。"}, {"text": "接受", "is_correct": false, "explanation": "“接受”表示收下或同意，与“行使”没有反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "“完成”表示做完某件事，与“行使”没有反义关系。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”表示维持原状，与“行使”没有反义关系。"}], "correct_answer": "放弃", "explanations": {"放弃": "反义：放弃是主动不去行使（权利），与“行使”构成反义关系。", "接受": "“接受”表示收下或同意，与“行使”没有反义关系。", "完成": "“完成”表示做完某件事，与“行使”没有反义关系。", "保持": "“保持”表示维持原状，与“行使”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放弃", "is_correct": true, "explanation": "反义：放弃是主动不去行使（权利），与“行使”构成反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”表示加入某项活动，与“行使”没有反义关系。"}, {"text": "赞成", "is_correct": false, "explanation": "“赞成”表示同意，与“行使”没有反义关系。"}, {"text": "坚持", "is_correct": false, "explanation": "“坚持”的反义词是“放弃”，但它与“行使”没有反义关系。"}], "correct_answer": "放弃", "explanations": {"放弃": "反义：放弃是主动不去行使（权利），与“行使”构成反义关系。", "参加": "“参加”表示加入某项活动，与“行使”没有反义关系。", "赞成": "“赞成”表示同意，与“行使”没有反义关系。", "坚持": "“坚持”的反义词是“放弃”，但它与“行使”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用自己有的权力去做事。", "primary_collocate": null, "pronunciation": "xíng shǐ", "ipa": "ɕiŋ˧˥ ʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "公民要依法行使自己的权利。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上行使了投票的权利。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不能随便行使自己的权力。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了十八岁，你就可以行使选举权了。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理没有行使他的否决权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律保护公民行使自己的权利。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次行使投票权，心里很紧张。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股东有权在会议上行使表决权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长不应该乱行使自己的权力。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未成年人也要学会依法行使自己的权利。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行使了", "label": "体标"}, {"form": "行使着", "label": "体标"}, {"form": "行使过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "行使：个人运用自己拥有的权利或权力去做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de67917-7f36-4640-ba0a-be9730ecd119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行使", "is_correct": true, "explanation": "正确答案。行使（xíng shǐ）指运用权利或权力去做事，第二个音节 shǐ 为第三声。"}, {"text": "形势", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，形势指事物发展的局面。"}, {"text": "形式", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，形式指事物的外在样子或格式。"}, {"text": "刑事", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，刑事指与刑罚有关的案件。"}, {"text": "行事", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，行事指做事、办事。"}], "explanations": {"行使": "正确答案。行使（xíng shǐ）指运用权利或权力去做事，第二个音节 shǐ 为第三声。", "形势": "shì（第四声）与 shǐ（第三声）声调不同，形势指事物发展的局面。", "形式": "shì（第四声）与 shǐ（第三声）声调不同，形式指事物的外在样子或格式。", "刑事": "shì（第四声）与 shǐ（第三声）声调不同，刑事指与刑罚有关的案件。", "行事": "shì（第四声）与 shǐ（第三声）声调不同，行事指做事、办事。"}, "sentence_index": null, "correct_answer": "行使"}, "level_3": {"options": [{"text": "行使", "is_correct": true, "explanation": "与“依法”“权利”搭配，表示依照法律运用权利，符合句意。"}, {"text": "打听", "is_correct": false, "explanation": "语义：“打听”指探问消息，不能用于权利，与句意不符。"}, {"text": "完成", "is_correct": false, "explanation": "语义：“完成”指做完任务或工作，与“依法运用权利”的意思不合。"}, {"text": "增长", "is_correct": false, "explanation": "搭配：“增长”用于数量、能力、知识，不说“增长权利”。"}], "explanations": {"行使": "与“依法”“权利”搭配，表示依照法律运用权利，符合句意。", "打听": "语义：“打听”指探问消息，不能用于权利，与句意不符。", "完成": "语义：“完成”指做完任务或工作，与“依法运用权利”的意思不合。", "增长": "搭配：“增长”用于数量、能力、知识，不说“增长权利”。"}, "sentence_index": 0, "correct_answer": "行使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都行使这台电脑。", "explanation": "这里应该用〈使用〉。行使只用于权力、权利，不能用于电脑这类具体物品。"}, {"text": "他在会上行使了一个建议。", "explanation": "这里应该用〈提出〉。行使的对象是权利或权力，不能是建议，提出建议要说“提出”。"}, {"text": "他行使了这份工作。", "explanation": "这里应该用〈担任〉。行使表示运用权利或权力，不能用来表示担任、从事某份工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "行使", "is_correct": true, "explanation": "正确答案。行使（xíng shǐ）指运用权利或权力去做事。"}, {"text": "形似", "is_correct": false, "explanation": "sì 与 shǐ 声母、声调都不同，形似指形状相像。"}, {"text": "型式", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，型式指样式或类型。"}, {"text": "幸事", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，shì 与 shǐ 的声调也不同，幸事指令人高兴的事。"}, {"text": "姓氏", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，姓氏指姓的统称。"}], "explanations": {"行使": "正确答案。行使（xíng shǐ）指运用权利或权力去做事。", "形似": "sì 与 shǐ 声母、声调都不同，形似指形状相像。", "型式": "shì（第四声）与 shǐ（第三声）声调不同，型式指样式或类型。", "幸事": "xìng（第四声）与 xíng（第二声）声调不同，shì 与 shǐ 的声调也不同，幸事指令人高兴的事。", "姓氏": "xìng（第四声）与 xíng（第二声）声调不同，姓氏指姓的统称。"}, "sentence_index": null, "correct_answer": "行使"}, "level_3": {"options": [{"text": "行使", "is_correct": true, "explanation": "与“投票权”搭配，表示运用投票的权利，符合句意。"}, {"text": "感到", "is_correct": false, "explanation": "搭配：“感到”后接感觉、压力，不能说“感到投票权”。"}, {"text": "买", "is_correct": false, "explanation": "语义：投票权是法定权利，不能用“买”，与句意相悖。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”用于纪录、局面、规定，不说“打破投票权”。"}], "explanations": {"行使": "与“投票权”搭配，表示运用投票的权利，符合句意。", "感到": "搭配：“感到”后接感觉、压力，不能说“感到投票权”。", "买": "语义：投票权是法定权利，不能用“买”，与句意相悖。", "打破": "搭配：“打破”用于纪录、局面、规定，不说“打破投票权”。"}, "sentence_index": 6, "correct_answer": "行使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都行使身体，很健康。", "explanation": "这里应该用〈锻炼〉。行使用于权力、权利，不能用于身体。"}, {"text": "他在会上行使了自己的看法。", "explanation": "这里应该用〈发表〉。行使用于权利、权力，不能用于表达看法。"}, {"text": "我们要行使自己的未来。", "explanation": "这里应该用〈选择〉。行使指运用权利或权力，不能用于选择未来这类事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他决定在下次选举中行使了自己的投票权。", "corrected_sentence": "他决定在下次选举中行使自己的投票权。", "error_description": "“行使了”的“了”表示动作已经完成，与“下次选举”这样的将来时间矛盾，应去掉“了”，改为“行使”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人第一次行使着投票权，很激动。", "corrected_sentence": "老人第一次行使投票权，很激动。", "error_description": "“行使着”表示动作正在持续，与“第一次”这种一次性的事件矛盾，应去掉“着”，改为“行使”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
