INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90634, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "执行；使用（职权等）。", "primary_collocate": null, "pronunciation": "xíng shǐ", "ipa": "ɕiŋ˧˥ ʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察依法行使职权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官在法庭上行使审判权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长不能超出范围行使职权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要按规定行使管理权力。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察官正在行使自己的职权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位官员从不乱行使职权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家机关必须依法行使权力。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关人员有权行使检查的职权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长行使了最后的决定权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察行使职权时，要出示证件。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行使了", "label": "体标"}, {"form": "行使着", "label": "体标"}, {"form": "行使过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "行使：官员或机关执行、使用职权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de67917-7f36-4640-ba0a-be9730ecd119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90634, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行使", "is_correct": true, "explanation": "正确答案。行使（xíng shǐ）指官员或机关执行、使用职权。"}, {"text": "形势", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，形势指局面。"}, {"text": "刑事", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，刑事指与刑罚有关的案件。"}, {"text": "型式", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，型式指样式或类型。"}, {"text": "形似", "is_correct": false, "explanation": "sì 与 shǐ 声母、声调都不同，形似指形状相像。"}], "explanations": {"行使": "正确答案。行使（xíng shǐ）指官员或机关执行、使用职权。", "形势": "shì（第四声）与 shǐ（第三声）声调不同，形势指局面。", "刑事": "shì（第四声）与 shǐ（第三声）声调不同，刑事指与刑罚有关的案件。", "型式": "shì（第四声）与 shǐ（第三声）声调不同，型式指样式或类型。", "形似": "sì 与 shǐ 声母、声调都不同，形似指形状相像。"}, "sentence_index": null, "correct_answer": "行使"}, "level_3": {"options": [{"text": "行使", "is_correct": true, "explanation": "与“依法”“职权”搭配，表示依照法律执行职权，符合句意。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”指用打印机输出文件，与职权无关，与句意不符。"}, {"text": "锻炼", "is_correct": false, "explanation": "语义：“锻炼”指训练身体或能力，与依法履行职务的语境不符。"}, {"text": "推荐", "is_correct": false, "explanation": "搭配：“推荐”的对象是人或事物，不说“推荐职权”。"}], "explanations": {"行使": "与“依法”“职权”搭配，表示依照法律执行职权，符合句意。", "打印": "语义：“打印”指用打印机输出文件，与职权无关，与句意不符。", "锻炼": "语义：“锻炼”指训练身体或能力，与依法履行职务的语境不符。", "推荐": "搭配：“推荐”的对象是人或事物，不说“推荐职权”。"}, "sentence_index": 0, "correct_answer": "行使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要合理行使资源，不能浪费。", "explanation": "这里应该用〈使用〉。行使只用于权力、权利，不用于资源等物品。"}, {"text": "农民行使了很多鸡。", "explanation": "这里应该用〈饲养〉。行使只用于权力、权利，不能用于动物。"}, {"text": "她在音乐会上行使了一首曲子。", "explanation": "这里应该用〈演奏〉。行使指运用权力，不能用于演奏乐曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90634, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "行使", "is_correct": true, "explanation": "正确答案。行使（xíng shǐ）指官员或机关执行、使用职权。"}, {"text": "形式", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，形式指外在样子或格式。"}, {"text": "行事", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，行事指做事、办事。"}, {"text": "幸事", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，shì 与 shǐ 的声调也不同，幸事指令人高兴的事。"}, {"text": "姓氏", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，姓氏指姓的统称。"}], "explanations": {"行使": "正确答案。行使（xíng shǐ）指官员或机关执行、使用职权。", "形式": "shì（第四声）与 shǐ（第三声）声调不同，形式指外在样子或格式。", "行事": "shì（第四声）与 shǐ（第三声）声调不同，行事指做事、办事。", "幸事": "xìng（第四声）与 xíng（第二声）声调不同，shì 与 shǐ 的声调也不同，幸事指令人高兴的事。", "姓氏": "xìng（第四声）与 xíng（第二声）声调不同，姓氏指姓的统称。"}, "sentence_index": null, "correct_answer": "行使"}, "level_3": {"options": [{"text": "行使", "is_correct": true, "explanation": "与“依法”“权力”搭配，表示依照法律执行权力，符合句意。"}, {"text": "夺取", "is_correct": false, "explanation": "语义：“夺取”指用强力取得，与“依法”的要求相悖。"}, {"text": "兑现", "is_correct": false, "explanation": "搭配：“兑现”搭配承诺、支票，不说“兑现权力”。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：“挑选”的对象是人或物，与“依法履行权力”的语境不符。"}], "explanations": {"行使": "与“依法”“权力”搭配，表示依照法律执行权力，符合句意。", "夺取": "语义：“夺取”指用强力取得，与“依法”的要求相悖。", "兑现": "搭配：“兑现”搭配承诺、支票，不说“兑现权力”。", "挑选": "语义：“挑选”的对象是人或物，与“依法履行权力”的语境不符。"}, "sentence_index": 6, "correct_answer": "行使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人要按规定行使机器。", "explanation": "这里应该用〈操作〉。行使指运用权力，不指操作机器。"}, {"text": "老人在晚上行使了一个故事。", "explanation": "这里应该用〈讲述〉。行使只用于权利、权力，不能用于讲故事。"}, {"text": "工厂每天行使很多汽车。", "explanation": "这里应该用〈制造〉。行使指运用权力，不能用于生产汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院将依法行使了职权。", "corrected_sentence": "法院将依法行使职权。", "error_description": "“行使了”的“了”表示动作已经完成，与“将”表示的将来矛盾，应去掉“了”，改为“行使”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位官员从来没有乱行使了职权。", "corrected_sentence": "这位官员从来没有乱行使过职权。", "error_description": "“从来没有”否定过去的经历，不能和“了”连用，应把“行使了”改为“行使过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
