INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90635, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "恐怖主义是用吓人、伤人的办法，让大家害怕。", "primary_collocate": null, "pronunciation": "kǒng bù zhǔ yì", "ipa": "kʰʊŋ˨˩ pu˥˩ ʈʂu˨˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "恐怖主义让很多人不敢出门。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐怖主义用伤人的办法吓大家。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是恐怖主义。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐怖主义让城市里的人很害怕。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都反对恐怖主义。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了一部关于恐怖主义的电影。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐怖主义伤害了许多无辜的人。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上没有人喜欢恐怖主义。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上常常写到恐怖主义。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐怖主义会让孩子们睡不好觉。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恐怖主义者", "label": "复合"}, {"form": "恐怖主義", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用吓人伤人的办法让大家害怕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20866e08-b43e-403c-ad2b-6b6e0b8a5d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90635, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "春天", "is_correct": false, "explanation": "语义：春天不会让人不敢出门，句意不通。"}, {"text": "冰淇淋", "is_correct": false, "explanation": "语义：冰淇淋不会让很多人害怕出门，句意不通。"}, {"text": "恐怖主义", "is_correct": true, "explanation": "恐怖主义：用吓人的办法让大家害怕，正好使很多人不敢出门，符合句意。"}, {"text": "杂志", "is_correct": false, "explanation": "语义：杂志不会让人不敢出门，句意不通。"}], "explanations": {"春天": "语义：春天不会让人不敢出门，句意不通。", "冰淇淋": "语义：冰淇淋不会让很多人害怕出门，句意不通。", "恐怖主义": "恐怖主义：用吓人的办法让大家害怕，正好使很多人不敢出门，符合句意。", "杂志": "语义：杂志不会让人不敢出门，句意不通。"}, "sentence_index": 0, "correct_answer": "恐怖主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他心里充满了恐怖主义。", "explanation": "这里应该用〈恐惧〉。恐怖主义指用吓人办法的行为，不表示心里的感受，心里的感受要用“恐惧”。"}, {"text": "他看了一部恐怖主义。", "explanation": "这里应该用〈恐怖片〉。恐怖主义指用吓人、伤人的办法，是行为或手段，不能指一部作品，作品要说“恐怖片”。"}, {"text": "警察抓住了一个恐怖主义。", "explanation": "这里应该用〈恐怖分子〉。恐怖主义是用吓人、伤人的办法，不能指人，指人要说“恐怖分子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90635, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨衣", "is_correct": false, "explanation": "语义：雨衣是用来挡雨的，不会伤害人，句意不通。"}, {"text": "恐怖主义", "is_correct": true, "explanation": "恐怖主义：用伤人的办法吓人，能够伤害许多无辜的人，符合句意。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：微笑不会伤害无辜的人，句意不通。"}, {"text": "咸鱼", "is_correct": false, "explanation": "语义：咸鱼不会伤害无辜的人，句意不通。"}], "explanations": {"雨衣": "语义：雨衣是用来挡雨的，不会伤害人，句意不通。", "恐怖主义": "恐怖主义：用伤人的办法吓人，能够伤害许多无辜的人，符合句意。", "微笑": "语义：微笑不会伤害无辜的人，句意不通。", "咸鱼": "语义：咸鱼不会伤害无辜的人，句意不通。"}, "sentence_index": 6, "correct_answer": "恐怖主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种恐怖主义会让人发烧。", "explanation": "这里应该用〈病毒〉。恐怖主义不会让人发烧，会让人发烧的是病毒。"}, {"text": "这项恐怖主义让大家得到了好处。", "explanation": "这里应该用〈政策〉。恐怖主义是主张和行为，不能让大家得到好处，能带来好处的是政策。"}, {"text": "恐怖主义让人感觉温暖。", "explanation": "这里应该用〈阳光〉。恐怖主义让人害怕，不会让人感觉温暖，温暖的感觉要用“阳光”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90635, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察一直在打击一个恐怖主义。", "corrected_sentence": "警察一直在打击恐怖主义。", "error_description": "错误形式：一个恐怖主义；正确形式：恐怖主义。“恐怖主义”是抽象名词，不能用“一个”来数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90635, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们坚决反对恐怖主义们。", "corrected_sentence": "我们坚决反对恐怖主义。", "error_description": "错误形式：恐怖主义们；正确形式：恐怖主义。“恐怖主义”表示抽象的主张和行为，不能加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
