INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90636, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以暴力或威胁手段制造恐慌，以达到政治等目的的主张和行为。", "primary_collocate": null, "pronunciation": "kǒng bù zhǔ yì", "ipa": "kʰʊŋ˨˩ pu˥˩ ʈʂu˨˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "各国政府一起打击恐怖主义。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐怖主义威胁着世界和平。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位专家研究恐怖主义很多年了。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里说，恐怖主义是全世界的大问题。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐怖主义用暴力制造恐慌，想达到政治目的。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国通过了反对恐怖主义的决议。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上谈到了恐怖主义的危害。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有一个国家支持恐怖主义。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方说，这次事件和恐怖主义有关。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要用法律来对付恐怖主义。", "target_word": "恐怖主义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恐怖主义者", "label": "复合"}, {"form": "恐怖主義", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "用暴力或威胁制造恐慌以达到政治目的的主张和行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20866e08-b43e-403c-ad2b-6b6e0b8a5d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90636, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "搭配：“打击”的对象多是犯罪或敌人，不能说打击天气。"}, {"text": "恐怖主义", "is_correct": true, "explanation": "恐怖主义：各国政府一起打击的对象，符合句意。"}, {"text": "蔬菜", "is_correct": false, "explanation": "搭配：“打击”不能用于蔬菜，蔬菜不是打击的对象。"}, {"text": "和平", "is_correct": false, "explanation": "语义：和平是要维护的，不能被打击，句意不通。"}], "explanations": {"天气": "搭配：“打击”的对象多是犯罪或敌人，不能说打击天气。", "恐怖主义": "恐怖主义：各国政府一起打击的对象，符合句意。", "蔬菜": "搭配：“打击”不能用于蔬菜，蔬菜不是打击的对象。", "和平": "语义：和平是要维护的，不能被打击，句意不通。"}, "sentence_index": 0, "correct_answer": "恐怖主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个恐怖主义，经常在街上伤人。", "explanation": "这里应该用〈恐怖分子〉。恐怖主义指主张和行为，不能用来指人，指人要说“恐怖分子”。"}, {"text": "人们听到消息后都感到恐怖主义。", "explanation": "这里应该用〈恐慌〉。恐怖主义是主张和行为，不表示心理状态，人们的心理要用“恐慌”。"}, {"text": "那些恐怖主义冲进商店抢东西。", "explanation": "这里应该用〈暴徒〉。恐怖主义指主张，不能指冲进商店抢东西的人，这种人要说“暴徒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐曲", "is_correct": false, "explanation": "语义：乐曲是艺术作品，不会造成危害，句意不通。"}, {"text": "书法", "is_correct": false, "explanation": "语义：书法是艺术，不会造成危害，句意不通。"}, {"text": "恐怖主义", "is_correct": true, "explanation": "恐怖主义：会在会上被谈到其危害的对象，符合句意。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹是自然现象，不会造成危害，句意不通。"}], "explanations": {"乐曲": "语义：乐曲是艺术作品，不会造成危害，句意不通。", "书法": "语义：书法是艺术，不会造成危害，句意不通。", "恐怖主义": "恐怖主义：会在会上被谈到其危害的对象，符合句意。", "彩虹": "语义：彩虹是自然现象，不会造成危害，句意不通。"}, "sentence_index": 6, "correct_answer": "恐怖主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种恐怖主义很难治疗。", "explanation": "这里应该用〈疾病〉。恐怖主义指主张和行为，不是需要治疗的对象，能治疗的是疾病。"}, {"text": "政府制定了新的恐怖主义。", "explanation": "这里应该用〈政策〉。恐怖主义不是可以制定的东西，政府制定的是政策。"}, {"text": "今年这个地区的恐怖主义很丰富。", "explanation": "这里应该用〈粮食〉。恐怖主义是抽象的主张和行为，不能说丰富，丰富的是粮食。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警方抓住了两个恐怖主义。", "corrected_sentence": "警方抓住了两个恐怖主义者。", "error_description": "错误形式：两个恐怖主义；正确形式：两个恐怖主义者。“恐怖主义”指主张和行为，不能指人，也不能用“个”来数；指人要说“恐怖主义者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "各国都在反对恐怖主义们。", "corrected_sentence": "各国都在反对恐怖主义。", "error_description": "错误形式：恐怖主义们；正确形式：恐怖主义。“恐怖主义”表示抽象的主张和行为，不能加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
