INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90641, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90641, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "骗子是说假话骗别人的坏人。", "primary_collocate": null, "pronunciation": "piàn zi", "ipa": "pʰjɛn˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "他总是说假话，大家都说他是骗子。", "target_word": "骗子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个骗子骗了好多人，没有人再相信他。", "target_word": "骗子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别信他的话，他是个骗子。", "target_word": "骗子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明说他会飞，我觉得他是个骗子。", "target_word": "骗子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个骗子的话听起来很好，其实都是假的。", "target_word": "骗子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不喜欢故事里的骗子。", "target_word": "骗子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对朋友说谎，朋友生气地叫他骗子。", "target_word": "骗子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是骗子！你说过会来的，可是没有来。", "target_word": "骗子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不想和骗子做朋友。", "target_word": "骗子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直骗人，现在大家都知道他是骗子。", "target_word": "骗子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大骗子", "label": "复合"}, {"form": "騙子", "label": "繁体"}], "register": "口语", "sense_fingerprint": "经常说假话、欺骗别人的坏人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f17da28-59f8-418f-b207-d6e528bd9ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90641, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骗子", "is_correct": true, "explanation": "正确：「骗子」指经常说假话、欺骗别人的人，与“总是说假话”相符。"}, {"text": "老实人", "is_correct": false, "explanation": "语义：「老实人」指诚实、不说假话的人，与句中“总是说假话”正好相反。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：「小偷」指偷东西的人，与“说假话”无关，句中没有偷窃的线索。"}, {"text": "胖子", "is_correct": false, "explanation": "体貌：「胖子」描述身材，句中说的是说假话，外形与此无关。"}], "explanations": {"骗子": "正确：「骗子」指经常说假话、欺骗别人的人，与“总是说假话”相符。", "老实人": "语义：「老实人」指诚实、不说假话的人，与句中“总是说假话”正好相反。", "小偷": "语义：「小偷」指偷东西的人，与“说假话”无关，句中没有偷窃的线索。", "胖子": "体貌：「胖子」描述身材，句中说的是说假话，外形与此无关。"}, "sentence_index": 0, "correct_answer": "骗子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个人翻墙进屋偷东西，被抓住以后，他是个骗子。", "explanation": "这里应该用〈小偷〉。骗子指用谎话骗人的人，翻墙偷东西是小偷的行为，不能用骗子。"}, {"text": "那个人拿刀冲进银行抢钱，他是个骗子。", "explanation": "这里应该用〈强盗〉。骗子靠谎话骗人，不用暴力，拿刀抢钱要用强盗。"}, {"text": "他在地铁上偷偷摸走了别人的钱包，是个骗子。", "explanation": "这里应该用〈扒手〉。骗子靠谎话骗人，偷偷摸走别人钱包是扒手的行为，不能用骗子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90641, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骗子", "is_correct": true, "explanation": "正确：「对朋友说谎」的人，朋友因此生气地叫他“骗子”，相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：「厨师」是做饭的人，与说谎无关，朋友生气时也不会这样叫他。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：「叫他」后面接的称呼要能指责对方的行为，「学生」不能用来指责说谎的人。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：「歌手」指唱歌的人，与“说谎”无关，朋友生气时不会这样称呼他。"}], "explanations": {"骗子": "正确：「对朋友说谎」的人，朋友因此生气地叫他“骗子”，相符。", "厨师": "语义：「厨师」是做饭的人，与说谎无关，朋友生气时也不会这样叫他。", "学生": "搭配：「叫他」后面接的称呼要能指责对方的行为，「学生」不能用来指责说谎的人。", "歌手": "语义：「歌手」指唱歌的人，与“说谎”无关，朋友生气时不会这样称呼他。"}, "sentence_index": 6, "correct_answer": "骗子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在地铁口弹吉他唱歌，他是个骗子。", "explanation": "这里应该用〈歌手〉。骗子指用谎话骗人的人，地铁口弹吉他唱歌是正常的表演，应说歌手。"}, {"text": "他每天在店里卖东西，他是个骗子。", "explanation": "这里应该用〈售货员〉。骗子指用假话骗人，正常在店里卖东西的人应说售货员。"}, {"text": "他每天凌晨在工地搬砖，是个骗子。", "explanation": "这里应该用〈工人〉。骗子指用谎话骗人的人，在工地搬砖的人应说工人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90641, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班有一个骗子们，他总是说谎。", "corrected_sentence": "我们班有一个骗子，他总是说谎。", "error_description": "“一个”已经表示数量，“骗子”后不能再加复数后缀“们”，正确的说法是“一个骗子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90641, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是个的骗子，总是拿假话糊弄人。", "corrected_sentence": "他是个骗子，总是拿假话糊弄人。", "error_description": "量词“个”和“骗子”之间不能插入“的”，正确的说法是“个骗子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
