INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90642, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用谎话或手段骗取财物的人。", "primary_collocate": null, "pronunciation": "piàn zi", "ipa": "pʰjɛn˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "骗子打电话说我中奖了，要我先给钱。", "target_word": "骗子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把银行卡里的钱给了骗子。", "target_word": "骗子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察昨天抓住了一个骗子。", "target_word": "骗子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个骗子用假身份骗走了很多钱。", "target_word": "骗子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有些骗子专门骗老人的钱。", "target_word": "骗子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骗子说他是银行的人，要我的密码。", "target_word": "骗子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收到一个不认识的人发来的消息，要小心，他可能是骗子。", "target_word": "骗子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骗子骗走了她一年的工资。", "target_word": "骗子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个骗子卖假药，赚了不少钱。", "target_word": "骗子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友提醒我，打电话来要钱的人是骗子。", "target_word": "骗子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大骗子", "label": "复合"}, {"form": "騙子", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用谎话或手段骗取别人钱财的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f17da28-59f8-418f-b207-d6e528bd9ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骗子", "is_correct": true, "explanation": "正确：「骗子」指用谎话骗钱的人，与打电话骗中奖、要先付钱相符。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：「小偷」指偷东西的人，句中是打电话骗钱，不是偷窃。"}, {"text": "大个子", "is_correct": false, "explanation": "体貌：「大个子」描述身材，与打电话骗钱的内容无关。"}, {"text": "医生", "is_correct": false, "explanation": "语义：「医生」指治病的人，句中是中奖电话并要求先付钱，与此不符。"}], "explanations": {"骗子": "正确：「骗子」指用谎话骗钱的人，与打电话骗中奖、要先付钱相符。", "小偷": "语义：「小偷」指偷东西的人，句中是打电话骗钱，不是偷窃。", "大个子": "体貌：「大个子」描述身材，与打电话骗钱的内容无关。", "医生": "语义：「医生」指治病的人，句中是中奖电话并要求先付钱，与此不符。"}, "sentence_index": 0, "correct_answer": "骗子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个骗子半夜撬开门，偷走了很多钱。", "explanation": "这里应该用〈小偷〉。骗子靠假话骗钱，撬门偷东西要用小偷。"}, {"text": "这个骗子拿着刀抢走了很多钱。", "explanation": "这里应该用〈强盗〉。骗子不靠暴力，拿刀抢钱要用强盗。"}, {"text": "她每天清扫街道，是个骗子。", "explanation": "这里应该用〈清洁工〉。骗子指用假话骗钱的人，清扫街道的人应说清洁工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骗子", "is_correct": true, "explanation": "正确：「骗子」指骗钱的人，与“不认识的人发来消息、要小心”相符。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：「朋友」是熟悉的人，与“不认识的人”相矛盾，不会让人特别小心。"}, {"text": "老同学", "is_correct": false, "explanation": "语义：「老同学」也是熟人，与“不认识的人”相矛盾。"}, {"text": "邻居", "is_correct": false, "explanation": "语义：「邻居」是住在附近的熟人，与“不认识的人”相矛盾。"}], "explanations": {"骗子": "正确：「骗子」指骗钱的人，与“不认识的人发来消息、要小心”相符。", "朋友": "语义：「朋友」是熟悉的人，与“不认识的人”相矛盾，不会让人特别小心。", "老同学": "语义：「老同学」也是熟人，与“不认识的人”相矛盾。", "邻居": "语义：「邻居」是住在附近的熟人，与“不认识的人”相矛盾。"}, "sentence_index": 6, "correct_answer": "骗子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天在医院给病人打针，她是个骗子。", "explanation": "这里应该用〈护士〉。骗子指用谎话骗钱的人，在医院正常工作的人应说护士。"}, {"text": "他每天在学校教书，他是个骗子。", "explanation": "这里应该用〈老师〉。骗子指用假话骗人，在学校教书的人应说老师。"}, {"text": "他每天在街边修鞋，是个骗子。", "explanation": "这里应该用〈修鞋匠〉。骗子指用假话骗钱的人，街边修鞋的人应说修鞋匠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那几个骗子们都被警察抓住了。", "corrected_sentence": "那几个骗子都被警察抓住了。", "error_description": "“几个”已经表示复数，“骗子”后不能再加“们”，正确的说法是“那几个骗子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里来了一骗子，大家要小心。", "corrected_sentence": "这里来了一个骗子，大家要小心。", "error_description": "“骗子”是可数名词，前面要有量词，正确的说法是“一个骗子”，不能省略量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
