INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90643, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想问别人一件事时，先说的有礼貌的话。", "primary_collocate": null, "pronunciation": "qǐng wèn", "ipa": "tɕʰiŋ˨˩˦ wən˥˩", "syllable_count": 2, "sentences": [{"text": "请问，地铁站怎么走？", "target_word": "请问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这里有人坐吗？", "target_word": "请问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，现在几点了？", "target_word": "请问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，你是王老师吗？", "target_word": "请问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，洗手间在哪儿？", "target_word": "请问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这个字怎么读？", "target_word": "请问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，您贵姓？", "target_word": "请问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，去火车站坐几路车？", "target_word": "请问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这本书多少钱？", "target_word": "请问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，附近有银行吗？", "target_word": "请问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "礼貌口语", "sense_fingerprint": "向陌生人问路、问时间等之前先说的礼貌开场语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53db9dd3-8e45-4d0b-b8b6-d4711d195280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90643, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "请问", "is_correct": true, "explanation": "“请问”是礼貌地引出询问的开场语，放在句首询问路线正合适。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示感激，不能用来引出问路的问题。"}, {"text": "回答", "is_correct": false, "explanation": "语义：“回答”需要先有别人的提问，不能作为句首的开场语。"}, {"text": "告诉", "is_correct": false, "explanation": "配价：“告诉”需要接收话的对象（如“告诉我”），这里缺少对象，句子不成立。"}], "explanations": {"请问": "“请问”是礼貌地引出询问的开场语，放在句首询问路线正合适。", "感谢": "语义：“感谢”表示感激，不能用来引出问路的问题。", "回答": "语义：“回答”需要先有别人的提问，不能作为句首的开场语。", "告诉": "配价：“告诉”需要接收话的对象（如“告诉我”），这里缺少对象，句子不成立。"}, "sentence_index": 0, "correct_answer": "请问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请问，我今天很高兴。", "explanation": "“请问”后面要接向对方发问的问句，这句是陈述，不应用“请问”引出。"}, {"text": "请问，快让开，我要过去！", "explanation": "“请问”只用于礼貌地发问，不用来催促或命令别人；这句是命令，与该词的用法不符。"}, {"text": "请问，你好！", "explanation": "这里把“请问”当作问候用语，它只用于礼貌地向对方发问，不表示问候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90643, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "请问", "is_correct": true, "explanation": "“请问”是礼貌地引出询问的开场语，放在句首询问对方姓名正合适。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：“道歉”表示认错，不能用来开口询问对方姓名。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”表示庆祝，与询问对方姓名的语境不相符。"}, {"text": "认识", "is_correct": false, "explanation": "配价：“认识”需要接人作宾语（如“认识您”），这里缺少对象，句子不成立。"}], "explanations": {"请问": "“请问”是礼貌地引出询问的开场语，放在句首询问对方姓名正合适。", "道歉": "语义：“道歉”表示认错，不能用来开口询问对方姓名。", "祝贺": "语义：“祝贺”表示庆祝，与询问对方姓名的语境不相符。", "认识": "配价：“认识”需要接人作宾语（如“认识您”），这里缺少对象，句子不成立。"}, "sentence_index": 6, "correct_answer": "请问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一直请问他的帮助。", "explanation": "这里应该用〈感谢〉。“请问”表示向人发问或请教，不能用来表示对他人帮助的感谢。"}, {"text": "医生请问他戒烟。", "explanation": "这里应该用〈劝〉。“请问”表示向人发问，不表示劝说他人。"}, {"text": "他请问我一个好消息。", "explanation": "这里应该用〈告诉〉。“请问”只表示提问，不能表示把消息告诉别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90643, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请问了，去机场怎么走？", "corrected_sentence": "请问，去机场怎么走？", "error_description": "体标错误：“请问”是固定的开场语，不能带“了”，应说“请问，去机场怎么走？”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90643, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很请问，附近有药店吗？", "corrected_sentence": "请问，附近有药店吗？", "error_description": "修饰错误：“请问”是固定的开场语，不能用程度副词“很”修饰，应说“请问，附近有药店吗？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
