INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90645, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一带是某个地方和它的四周。", "primary_collocate": null, "pronunciation": "yí dài", "ipa": "i˧˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "南方一带夏天很热。", "target_word": "一带", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "机场一带今天堵车。", "target_word": "一带", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他对这一带非常熟悉。", "target_word": "一带", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公园一带有不少老人在散步。", "target_word": "一带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "黄河一带是中国文明的发源地之一。", "target_word": "一带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一带的路我走过很多次。", "target_word": "一带", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "西边那一带晚上没有灯，你要小心。", "target_word": "一带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天夜里，江边一带起了大雾。", "target_word": "一带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一带的房子又新又便宜。", "target_word": "一带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁站一带新开了好几家咖啡店。", "target_word": "一带", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一帶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某个地方和它的四周，放在地名或“这/那”之后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab11b7c9-d5a8-4a17-9c0b-0279c3fa91db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90645, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一带", "is_correct": true, "explanation": "正确：yí dài，指某地及其周围地区。"}, {"text": "一派", "is_correct": false, "explanation": "pài（第四声）与 dài 声母不同，“一派”意思是派别、流派。"}, {"text": "一概", "is_correct": false, "explanation": "gài（第四声）与 dài 声母不同，“一概”意思是全部、一律。"}, {"text": "一道", "is_correct": false, "explanation": "dào（第四声）与 dài 韵母不同，“一道”意思是一起、同行。"}], "explanations": {"一带": "正确：yí dài，指某地及其周围地区。", "一派": "pài（第四声）与 dài 声母不同，“一派”意思是派别、流派。", "一概": "gài（第四声）与 dài 声母不同，“一概”意思是全部、一律。", "一道": "dào（第四声）与 dài 韵母不同，“一道”意思是一起、同行。"}, "sentence_index": null, "correct_answer": "一带"}, "level_3": {"options": [{"text": "一带", "is_correct": true, "explanation": "正确：“南方一带”指南方某地及其周围地区，可以作“夏天很热”的主语。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：“钢笔”是书写工具，不指地区，不能作“夏天很热”的主语。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高矮，不能用来指地点。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：“饼干”是食品，不指地区，句子说不通。"}], "explanations": {"一带": "正确：“南方一带”指南方某地及其周围地区，可以作“夏天很热”的主语。", "钢笔": "语义：“钢笔”是书写工具，不指地区，不能作“夏天很热”的主语。", "身高": "体貌：“身高”指人的身体高矮，不能用来指地点。", "饼干": "语义：“饼干”是食品，不指地区，句子说不通。"}, "sentence_index": 0, "correct_answer": "一带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一带放进了书包。", "explanation": "这里应该用〈书〉。“一带”指地区，无法放进书包。"}, {"text": "很多一带在操场上玩。", "explanation": "这里应该用〈学生〉。“一带”指地区，不指人，不能作“玩”的主语。"}, {"text": "他一带会来。", "explanation": "这里应该用〈一定〉。“一带”是地区名词，不能作状语表示肯定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90645, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一带", "is_correct": true, "explanation": "正确：“西边那一带”指西边某地及其周围地区，可以作“晚上没有灯”的主语。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：“面容”指脸的样子，不能用来指地区。"}, {"text": "饭碗", "is_correct": false, "explanation": "语义：“饭碗”是盛饭的器具，不指地区，句子说不通。"}, {"text": "面包", "is_correct": false, "explanation": "语义：“面包”是食物，不能作“晚上没有灯”的主语。"}], "explanations": {"一带": "正确：“西边那一带”指西边某地及其周围地区，可以作“晚上没有灯”的主语。", "面容": "体貌：“面容”指脸的样子，不能用来指地区。", "饭碗": "语义：“饭碗”是盛饭的器具，不指地区，句子说不通。", "面包": "语义：“面包”是食物，不能作“晚上没有灯”的主语。"}, "sentence_index": 6, "correct_answer": "一带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们三点一带到。", "explanation": "这里应该用〈左右〉。“一带”只指地方，表示时间大约要用“左右”。"}, {"text": "我们坐一带去北京。", "explanation": "这里应该用〈火车〉。“一带”指地区，不能作交通工具。"}, {"text": "妈妈给我买了一带，我很喜欢穿。", "explanation": "这里应该用〈裙子〉。“一带”指地区，不能买来穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个一带有很多游客。", "corrected_sentence": "那一带有很多游客。", "error_description": "错误在于多加了“个”。“一带”前面不用“个”，应说“那一带”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天在湖边那个一带跑步。", "corrected_sentence": "我每天在湖边那一带跑步。", "error_description": "错误在于多加了量词“个”。“那一带”中已有指示词“那”，“一带”前不能再加“个”，应说“那一带”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
