INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90646, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某个地方及其附近地区。", "primary_collocate": null, "pronunciation": "yí dài", "ipa": "i˧˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这一带的空气很好。", "target_word": "一带", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家住在学校这一带。", "target_word": "一带", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "长江一带最近下了很大的雨。", "target_word": "一带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一带有很多好吃的小饭馆。", "target_word": "一带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京一带冬天特别冷。", "target_word": "一带", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请问，这一带有银行吗？", "target_word": "一带", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山东一带的人爱吃面条。", "target_word": "一带", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海边一带晚上很安静，人也不多。", "target_word": "一带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说他在上海一带工作了三年。", "target_word": "一带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一带以前是一片农田，现在都盖了楼房。", "target_word": "一带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一帶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某地及其附近地区，常说“这一带”“某地一带”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab11b7c9-d5a8-4a17-9c0b-0279c3fa91db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90646, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一带", "is_correct": true, "explanation": "正确：yí dài，指某地及其附近地区。"}, {"text": "一派", "is_correct": false, "explanation": "pài（第四声）与 dài 声母不同，“一派”意思是派别、流派。"}, {"text": "一概", "is_correct": false, "explanation": "gài（第四声）与 dài 声母不同，“一概”意思是全部、一律。"}, {"text": "一道", "is_correct": false, "explanation": "dào（第四声）与 dài 韵母不同，“一道”意思是一起、同行。"}], "explanations": {"一带": "正确：yí dài，指某地及其附近地区。", "一派": "pài（第四声）与 dài 声母不同，“一派”意思是派别、流派。", "一概": "gài（第四声）与 dài 声母不同，“一概”意思是全部、一律。", "一道": "dào（第四声）与 dài 韵母不同，“一道”意思是一起、同行。"}, "sentence_index": null, "correct_answer": "一带"}, "level_3": {"options": [{"text": "一带", "is_correct": true, "explanation": "正确：指某地及其附近地区，可以说“这一带的空气”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”指装东西的袋子，不是地方，不能说“空气很好”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体型，不能用来指地方。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“空气很好”要求地点作主语，“手机”不能与之搭配。"}], "explanations": {"一带": "正确：指某地及其附近地区，可以说“这一带的空气”。", "书包": "语义：“书包”指装东西的袋子，不是地方，不能说“空气很好”。", "身材": "体貌：“身材”指人的体型，不能用来指地方。", "手机": "搭配：“空气很好”要求地点作主语，“手机”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "一带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们坐一带去学校。", "explanation": "这里应该用〈地铁〉。“一带”指地区，不能作交通工具。"}, {"text": "他一带有很多朋友。", "explanation": "这里应该用〈身边〉。“一带”指某地及其附近的地区，不能指人身边的人。"}, {"text": "这个一带有很多饭馆。", "explanation": "这里应该用〈这一带〉。“一带”前面不加量词“个”，应说“这一带”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一带", "is_correct": true, "explanation": "正确：指山东及其附近地区，可以说“山东一带的人”。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是学习用的书，不指地区，不能用来限定“人”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，不能用来限定地区。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”是交通工具，不指地区，句子说不通。"}], "explanations": {"一带": "正确：指山东及其附近地区，可以说“山东一带的人”。", "课本": "语义：“课本”是学习用的书，不指地区，不能用来限定“人”。", "身高": "体貌：“身高”指身体的高矮，不能用来限定地区。", "汽车": "语义：“汽车”是交通工具，不指地区，句子说不通。"}, "sentence_index": 6, "correct_answer": "一带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一带去公园吧。", "explanation": "这里应该用〈一起〉。“一带”是名词，不能作状语修饰动词“去”。"}, {"text": "他关上了一带。", "explanation": "这里应该用〈门〉。“一带”指地区，不能被“关上”。"}, {"text": "我每天早上喝一带牛奶。", "explanation": "这里应该用〈杯〉。“一带”指地区，不能用来计量牛奶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个一带的公园很大。", "corrected_sentence": "这一带的公园很大。", "error_description": "错误在于多加了量词“个”。“一带”前面不用“个”，应说“这一带”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对一带很熟悉。", "corrected_sentence": "他对这一带很熟悉。", "error_description": "错误在于漏掉指示词。“一带”单独使用时须有“这/那”等指示词或地名限定，应说“这一带”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
