INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90647, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在网站或软件里，属于你自己的名字和号码。", "primary_collocate": null, "pronunciation": "zhàng hào", "ipa": "ʈʂɑŋ˥˩ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我在这个网站有一个账号。", "target_word": "账号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的游戏账号是什么？", "target_word": "账号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想在这个软件注册一个账号。", "target_word": "账号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "账号和密码都不能告诉别人。", "target_word": "账号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她有两个微信账号，一个工作用，一个生活用。", "target_word": "账号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了账号，只好重新注册。", "target_word": "账号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友的账号突然登不上了。", "target_word": "账号", "complexity_tier": "T3", "furigana": "péngyou de zhànghào tūrán dēng bu shàng le", "sentence_source": "generated"}, {"text": "请在网站上输入你的账号。", "target_word": "账号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把旧账号换成了新账号。", "target_word": "账号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的账号很有意思，是你自己起的吗？", "target_word": "账号", "complexity_tier": "T3", "furigana": "nǐ de zhànghào hěn yǒu yìsi shì nǐ zìjǐ qǐ de ma", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个账号", "label": "量词"}, {"form": "账号密码", "label": "复合"}, {"form": "帳號", "label": "繁体"}], "register": "通用", "sense_fingerprint": "账号：在网站或软件里属于自己的名字和号码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d48bf1a-fcce-4795-8810-0494f4f470de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90647, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：“在这个网站有一个电脑”说不通，电脑是实物。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：网站里不存在冰箱这样的东西，句子说不通。"}, {"text": "账号", "is_correct": true, "explanation": "正确：网站注册后用户拥有的名称和编号就是账号。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是身体部位，网站里不会有人的眼睛，句子说不通。"}], "explanations": {"电脑": "语义：“在这个网站有一个电脑”说不通，电脑是实物。", "冰箱": "语义：网站里不存在冰箱这样的东西，句子说不通。", "账号": "正确：网站注册后用户拥有的名称和编号就是账号。", "眼睛": "语义：眼睛是身体部位，网站里不会有人的眼睛，句子说不通。"}, "sentence_index": 0, "correct_answer": "账号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有一支账号，平时用。", "explanation": "这里应该用〈个〉。“支”用于笔等细长的东西，账号要用“个”。"}, {"text": "我用账号浇花，花长得很好。", "explanation": "这里应该用〈水〉。水是液体，可以用来浇花；账号不能用来浇花。"}, {"text": "妈妈用账号打开了房门。", "explanation": "这里应该用〈钥匙〉。钥匙是实物，可以用来开门；账号不能用来开门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90647, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本不能“登不上”，句子说不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能“登不上”，句子说不通。"}, {"text": "账号", "is_correct": true, "explanation": "正确：账号可以登录，“登不上”说的正是账号的问题。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不能“登不上”，句子说不通。"}], "explanations": {"课本": "语义：课本不能“登不上”，句子说不通。", "房子": "语义：房子不能“登不上”，句子说不通。", "账号": "正确：账号可以登录，“登不上”说的正是账号的问题。", "雨伞": "语义：雨伞不能“登不上”，句子说不通。"}, "sentence_index": 6, "correct_answer": "账号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的账号，很可爱。", "explanation": "账号是名称和编号，不指人。这里把账号当成了人，说不通。"}, {"text": "我的账号跑得很快，比我还快。", "explanation": "这里应该用〈车〉。车能跑，可以说“跑得很快”；账号不会跑，“跑”不能用于账号。"}, {"text": "这个账号很好吃，我尝了一口。", "explanation": "账号不是食物，不能吃，“好吃”只能用于食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90647, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想换一条新账号。", "corrected_sentence": "我想换一个新账号。", "error_description": "量词错误：“条”用于长而窄的东西，账号要用“个”。应把“一条新账号”改为“一个新账号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90647, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我有一台微信账号，平时工作用。", "corrected_sentence": "我有一个微信账号，平时工作用。", "error_description": "量词错误：“台”用于机器、电器，账号不是机器，要用“个”。应把“一台微信账号”改为“一个微信账号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
