INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90649, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不一定是说也许这样，也许不这样，没有说准。", "primary_collocate": null, "pronunciation": "bù yí dìng", "ipa": "pu˥˩ i˧˥ tiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "他今天不一定来，你先别等。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有钱的人不一定快乐。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贵的东西不一定好用。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得对，但事情不一定这样。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你明天去爬山吗？不一定，要看天气。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习好的人不一定聪明。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不一定知道所有的答案。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭我不一定回家吃，你们先吃吧。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作多的时候，周末不一定能休息。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑了，不一定是高兴。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "可能这样也可能不这样，没有定论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e60a67-5d39-493a-b9c5-106ceed17226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90649, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不一定", "is_correct": true, "explanation": "不一定：表示不确定，与后句“你先别等”相合。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示永远不，与“今天”这样具体的时间矛盾。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”不能直接修饰动词“来”，句子不通。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”要与否定词连用，此处没有否定词，句子不通。"}], "explanations": {"不一定": "不一定：表示不确定，与后句“你先别等”相合。", "从不": "语义：“从不”表示永远不，与“今天”这样具体的时间矛盾。", "非常": "搭配：“非常”不能直接修饰动词“来”，句子不通。", "从来": "搭配：“从来”要与否定词连用，此处没有否定词，句子不通。"}, "sentence_index": 0, "correct_answer": "不一定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你不一定再来，我们已经忙完了。", "explanation": "这里应该用〈请不要〉。不一定表示没有把握，不能用来礼貌地请人别再做某事，要用〈请不要〉。"}, {"text": "你不一定乱说话，安静一点。", "explanation": "这里应该用〈别〉。不一定表示不确定，不能用来劝阻；劝人不要做某事要用〈别〉。"}, {"text": "你不一定客气，我们是朋友。", "explanation": "这里应该用〈不用〉。不一定表示不确定，表示没有必要做某事要用〈不用〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90649, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不一定", "is_correct": true, "explanation": "不一定：表示不能肯定，与句意相合。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示仅仅，与句意“不一定知道”的不确定不符。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”修饰形容词，不能修饰“知道”。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”一般修饰形容词，“知道”前不能用“很”，句子不通。"}], "explanations": {"不一定": "不一定：表示不能肯定，与句意相合。", "只": "语义：“只”表示仅仅，与句意“不一定知道”的不确定不符。", "太": "搭配：“太”修饰形容词，不能修饰“知道”。", "很": "搭配：“很”一般修饰形容词，“知道”前不能用“很”，句子不通。"}, "sentence_index": 6, "correct_answer": "不一定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天的比赛我们不一定赢了，比分是三比零输的。", "explanation": "这里不能用〈不一定〉。比分已经确定，“不一定”只表示没有把握，与已知结果矛盾，应直接用〈没〉否定。"}, {"text": "这些药千万不一定饭前吃。", "explanation": "这里应该用〈千万不要〉。不一定表示没有把握，不能用来告诫别人不要做某事。"}, {"text": "上课的时候不一定玩手机！", "explanation": "这里应该用〈不要〉。不一定表示没有把握，不能用来命令别人不做某事，要用〈不要〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90649, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天我没不一定能去，我们再说吧。", "corrected_sentence": "明天我不一定能去，我们再说吧。", "error_description": "“没”用错：“不一定”本身已含否定，不能与“没”连用，应删去“没”，写作“明天我不一定能去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90649, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方法没不一定很好。", "corrected_sentence": "这个方法不一定很好。", "error_description": "“没”用错：“不一定”本身已含否定，不能与“没”连用，应删去“没”，写作“这个方法不一定很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
